import type { Locale } from '../../../constants';

// Site-authored Build help; formulas stay in the feature and prose lives in the shared UI phrase catalog.
export const buildHelpTranslations: Partial<Record<Locale, Readonly<Record<string, string>>>> = {
  "ru": {
    "What the capture contains": "Что содержит снимок данных",
    "The file provides the first received profile stats, equipped items and captured progression. ATK has both a displayed base before ATK% and a native final value. HP and resistance are final values; their full percentage totals are not supplied. Missing fields remain unknown. These are snapshot values, rather than a live reading of the current game screen.": "Файл содержит первые полученные характеристики профиля, экипированные предметы и зафиксированный прогресс. Для АТК указаны отображаемая база до применения АТК% и итоговое значение родной стихии. ОЗ и сопротивление уже приведены как итоговые значения; полные суммы процентных бонусов для них не передаются. Отсутствующие поля остаются неизвестными. Это данные снимка, а не текущие показания игрового экрана.",
    "The pair inherits whole gear percentages": "Пара наследует полные проценты экипировки",
    "1 is the selected element and 2 its weapon partner. g is total gear ATK%; q is total gear DMG%. Their winners are chosen independently across the equipped set. Other sources stay on their own element. The stronger element keeps its own percentage; the weaker replaces only its gear portion. A standalone item’s GRV can choose its own winners, while Build totals keep one source per percentage for every slot.": "1 — выбранная стихия, 2 — стихия связанного с ней оружия. g — суммарный АТК% экипировки, q — суммарный УРОН% экипировки. Лучшие значения g и q независимо выбираются среди всех экипированных предметов. Остальные источники остаются у своих стихий. Более сильная стихия сохраняет собственные проценты, а у более слабой заменяется только часть от экипировки. Для отдельного предмета GRV может выбрать свои лучшие значения, а в общей сумме билда для каждого процента и каждого слота учитывается один источник.",
    "Pair ATK and Space Support": "АТК пары и Space Support",
    "B is a displayed base, including its own Space Support S. Compare the pair after removing each element’s support, then add only the selected element’s support before ATK%. A selected Enhancement Shot’s universal flat ATK is already in both effective bases and is counted once. Do not add support again after percentages. Flat ATK used by the combat table and the per-item GRV choice are separate calculations.": "B — отображаемая база, уже включающая собственный Space Support S. Сначала сравните пару, вычтя поддержку каждой стихии, затем до применения АТК% прибавьте поддержку только выбранной стихии. Универсальная плоская АТК выбранного Enhancement Shot уже входит в обе эффективные базы и учитывается один раз. Не прибавляйте поддержку повторно после процентов. Плоская АТК в боевой таблице и выбор для GRV отдельного предмета рассчитываются независимо.",
    "Altered combat ATK": "Боевая АТК Altered",
    "The combat model copies the strongest native element’s own final ATK, without duo inheritance, and keeps the captured or entered own Altered remainder. Native shot bonuses are inherited after that source’s percentages, once. The card’s imported displayed Altered base already contains the copy, so it is not added to that base again. Altered gear rating uses a different source selection: one gear-only source for GRV, the personal source for PRV.": "Боевая модель копирует итоговую АТК сильнейшей родной стихии без наследования пары и сохраняет зафиксированный или введённый остаток собственной АТК Altered. Бонусы выстрела для родной стихии наследуются после её процентных бонусов и только один раз. Отображаемая импортированная база Altered на карточке уже содержит скопированное значение, поэтому повторно его к базе не прибавляют. Для оценки экипировки Altered источники выбираются иначе: для GRV берётся один источник только из экипировки, для PRV — персональный источник.",
    "Temporary buffs at capture time": "Временные эффекты на момент снимка",
    "Recognized removable constant ATK% buffs are subtracted per element on import, including their stack count. A recognized flat or unknown-magnitude temporary ATK effect can block import. Permitted food and shots remain separate selected consumables. Unrecognized effects are not proof of a clean snapshot; use an out-of-combat capture and the source list when checking a discrepancy.": "При импорте для каждой стихии вычитаются распознанные постоянные бонусы АТК%, которые можно снять; учитывается и число их уровней. Распознанный временный эффект плоской АТК или эффекта неизвестной величины может заблокировать импорт. Разрешённая еда и выстрелы остаются отдельными выбранными расходуемыми предметами. Нераспознанные эффекты не подтверждают, что снимок сделан без баффов: при проверке расхождений используйте снимок вне боя и список источников.",
    "Account relic passives": "Пассивные эффекты аккаунтных реликвий",
    "Captured account relic passives apply even when those relics are not equipped. Their DMG% and RES% are distinct per-element values. Damage-received reduction is not automatically a resistance-stat multiplier: the capture’s attribute mapping determines which pool a passive affects. Relic A4 DMG% is included once in its own element’s combat DMG% and also shown in the relic summary. Relic RES% joins the known resistance multiplier once; changing the two equipped relics does not reset account passives.": "Зафиксированные пассивные эффекты аккаунтных реликвий действуют, даже если сами реликвии не надеты. Их УРОН% и СОПР% учитываются отдельно для каждой стихии. Снижение получаемого урона не обязательно является множителем характеристики сопротивления: к какой группе относится пассивный эффект, определяется сопоставлением атрибутов в снимке. УРОН% A4 реликвии один раз входит в боевой УРОН% своей стихии и также показывается в сводке реликвии. СОПР% реликвии один раз добавляется к известному множителю сопротивления; смена двух надетых реликвий не сбрасывает пассивные эффекты аккаунта.",
    "Unknown data and rounding": "Неизвестные данные и округление",
    "Calculations retain fractional values; separate displayed rows can differ by a unit after rounding. A blank required base is unknown, rather than zero. Unknown catalog items remain empty and are listed; catalog fitting is not verification of their effects. The badge ≈ denotes a modeled estimate. Up displays the normalized upgrade level stored in the file: the exporter has already converted the raw profile suffix by adding one. The card does not add one again. This model has no separate Up multiplier for weapon stat endpoints or weapon CS.": "В расчётах сохраняются дробные значения, поэтому после округления отдельные строки могут различаться на единицу. Пустое обязательное базовое значение считается неизвестным, а не нулевым. Неизвестные предметы каталога остаются без данных и перечисляются отдельно: подбор похожего предмета не подтверждает его эффекты. Знак ≈ обозначает расчётную оценку. Up показывает нормализованный уровень улучшения из файла: экспортёр уже увеличил на единицу исходный суффикс профиля. Карточка повторно единицу не прибавляет. В этой модели для предельных значений характеристик оружия и его CS нет отдельного множителя Up.",
    "Universal ATK": "Универсальная АТК",
    "Universal ATK is inferred, not a separately captured stat. The remainder includes universal gear ATK and external sources. The card shows it only when all four native bases are available and their remainders agree within one ATK. Otherwise it shows —. Its tooltip separates universal gear, the selected shot and remaining sources; it does not apply ATK% to this base.": "Универсальная АТК вычисляется, а не считывается как отдельная характеристика. В остаток входят универсальная АТК экипировки и внешние источники. Карточка показывает её, только если доступны все четыре родные базы, а их остатки различаются не более чем на одну единицу АТК. Иначе отображается —. В подсказке отдельно показаны универсальная АТК экипировки, выбранный выстрел и прочие источники; АТК% к этой базе не применяется.",
    "HP and HP%": "ОЗ и ОЗ%",
    "h is full HP% as a fraction. Without an explicitly entered total, only equipped gear HP% is known. The tooltip separates the pre-percentage pool into other sources, gear and the shot, then shows the percentage gain and final HP. Unknown external HP% or another multiplier makes the restored base an estimate. A missing HP snapshot stays missing.": "h — полный ОЗ% в виде дроби. Если итог не введён вручную, известен только ОЗ% надетой экипировки. Подсказка делит базу до применения процентов на прочие источники, экипировку и выстрел, а затем показывает процентную прибавку и итоговые ОЗ. Неизвестный внешний ОЗ% или другой множитель превращает восстановленную базу в оценку. Если ОЗ отсутствуют в снимке, они так и остаются неизвестными.",
    "Crit rating and chance": "Рейтинг и шанс крита",
    "The rating tooltip separates other sources, equipped gear and the shot. The level denominator comes from the game curve for the selected enemy level. The panel shows the uncapped sum; expected-output and personal rating calculations cap useful chance at 100%. Crit DMG is a bonus: the expected critical factor is 1 + c_rating × Crit DMG, rather than chance multiplied by full critical damage.": "В подсказке рейтинга отдельно показаны прочие источники, надетая экипировка и выстрел. Делитель для уровня берётся из игровой кривой для выбранного уровня врага. Панель показывает сумму без ограничения, а расчёты ожидаемого результата и персонального рейтинга учитывают полезный шанс не выше 100%. Критический УРОН — это бонус: ожидаемый множитель крита равен 1 + c_rating × Crit DMG, а не шансу, умноженному на полный критический урон.",
    "Resistance and damage reduction": "Сопротивление и снижение урона",
    "r is full RES%, or the known source sum when a full value is unavailable. Universal flat RES contributes to every element; elemental RES contributes only to its own. The shot is added before RES%. K uses character level, while the Crit curve uses enemy level. This reduction is the resistance component, not the product of every damage-reduction effect in combat. Tank EHP = HP × (1 + RES_effective / K).": "r — полный СОПР% или сумма известных источников, если полного значения нет. Универсальное плоское сопротивление учитывается для всех стихий, а стихийное — только для своей. Выстрел добавляется до применения СОПР%. В K используется уровень персонажа, а в кривой крита — уровень врага. Это только составляющая снижения урона от сопротивления, а не произведение всех боевых эффектов снижения урона. EHP танка = ОЗ × (1 + эффективное СОПР / K).",
    "The combat DMG% column": "Столбец боевого УРОН%",
    "For captures, this column is derived from the loadout; no full DMG% total is captured. Only generated recognized contributions enter it. Relic A4 is included once for its own element; duo inheritance replaces only gear DMG%, leaving relic and other non-gear bonuses on their own element. Alternative conditional Space Support modes do not stack: the strongest applicable mode per element is used. Imported Altered DMG% is zero in this model. This column is not a complete damage or rotation simulator.": "Для импортированных снимков значение столбца рассчитывается по экипировке: полная сумма УРОН% не считывается. В неё входят только распознанные вклады из сгенерированных данных. A4 реликвии учитывается один раз для своей стихии; наследование пары заменяет только УРОН% экипировки, а бонусы реликвии и другие бонусы вне экипировки остаются у своих стихий. Альтернативные условные режимы Space Support не складываются: для каждой стихии берётся сильнейший подходящий режим. В этой модели импортированный УРОН% Altered равен нулю. Этот столбец не является полным симулятором урона или ротации.",
    "Enhancement Shot stat gain": "Прибавка характеристик от Enhancement Shot",
    "For weapons, the target is the catalog’s maximum weapon level at the weapon’s actual stars. For matrices, it is the maximum level and maximum base-stat advancement. The selected shot adds these four flat gains to the first received stats. HP and RES gains are multiplied by their percentages; native ATK gains are multiplied by native ATK%; Altered inherits once. It does not change captured stars, Up or matrix set-effect ranks. Recalculation replaces the previous applied gain and does not add it again.": "Для оружия целевой уровень — максимальный уровень из каталога при фактическом числе звёзд оружия. Для матриц это максимальный уровень и максимальное улучшение базовых характеристик. Выбранный выстрел добавляет эти четыре плоские прибавки к первоначально полученным характеристикам. Прибавки ОЗ и СОПР умножаются на соответствующие проценты, прибавка родной АТК — на родной АТК%; Altered наследует её один раз. Число звёзд из снимка, Up и уровни эффектов набора матриц не меняются. При пересчёте предыдущая прибавка заменяется, а не добавляется повторно.",
    "Selected ATK% consumables": "Выбранные расходуемые предметы с АТК%",
    "The model applies only generated, recognized unconditional ATK% bonuses of selected consumables. A universal bonus targets the native elements declared by the catalog; it is not applied to Altered a second time. Unknown, conditional and other consumable effects are not inferred from their names. The expiry time describes the captured buff; the card is a saved configuration and does not automatically clear the selected consumable when that clock expires.": "Модель применяет только безусловные бонусы АТК% выбранных расходуемых предметов, которые распознаны и включены в сгенерированные данные. Универсальный бонус действует на родные стихии, указанные в каталоге, и не применяется к Altered повторно. Неизвестные, условные и прочие эффекты расходуемых предметов не выводятся из их названий. Время окончания относится к зафиксированному баффу; карточка хранит конфигурацию и не снимает выбранный предмет автоматически по истечении этого времени.",
    "Current CS and Apex CS": "Текущий CS и Apex CS",
    "Current CS starts from the captured profile score or the manual input. The selected Enhancement Shot adds its modeled flat-stat CS delta once; when a precise captured CS is available, rounding starts from that value. Apex CS remains the recorded historical maximum with its recorded time. The model does not replace current CS with the sum of gear, weapons, matrices and other system estimates, and it does not infer a new complete CS after every manual loadout edit or recompute every other consumable’s CS impact. The displayed integer header difference can differ from the rounded shot subtotal by one because the original captured CS has a fraction.": "Текущий CS берётся из снимка профиля или вводится вручную. Выбранный Enhancement Shot один раз добавляет расчётную прибавку CS от плоских характеристик; если доступно точное значение CS из снимка, округление начинается с него. Apex CS остаётся зафиксированным историческим максимумом с исходным временем. Модель не заменяет текущий CS суммой оценок экипировки, оружия, матриц и других систем, не вычисляет новый полный CS после каждой ручной правки билда и не пересчитывает влияние на CS всех остальных расходуемых предметов. Целая разница в заголовке может отличаться на единицу от округлённой суммы прибавки выстрела, поскольку исходный CS в снимке дробный.",
    "Weapon CS": "CS оружия",
    "The card’s weapon source label scores the weapon alone. Level gains and star coefficients come from generated game tables. Only the current star’s StarSkillScore is added, not the sum of all earlier stars. Matrix scores and their set AddScore are separate. The reconstruction matches documented server-score samples within floating-point differences; that does not establish every weapon, upgrade field or native rounding case.": "Подпись источника на карточке оценивает только само оружие. Прибавки за уровни и коэффициенты звёзд берутся из сгенерированных игровых таблиц. Добавляется только StarSkillScore текущей звезды, а не сумма всех предыдущих звёзд. Оценки матриц и AddScore их набора рассчитываются отдельно. Реконструкция совпадает с задокументированными примерами серверных оценок с расхождением лишь на точность чисел с плавающей запятой; это не подтверждает значения для каждого оружия, поля улучшения или случая игрового округления.",
    "Matrices and set CS": "CS матриц и наборов",
    "Each matrix uses its own slot profile, level and star multiplier. Use fractional stats for the score; the displayed matrix stat has its own float32 truncation. Set AddScore is counted once per reached piece threshold on one weapon. The model ranks the set by the threshold’s Nth strongest matrix; mixed-star selection has not been separately verified in every case. Enhancement Shot changes base-stat endpoints, not these set ranks.": "Для каждой матрицы используются профиль её слота, уровень и множитель звёзд. В оценке применяются дробные характеристики; отображаемая характеристика матрицы отдельно усекается до float32. AddScore набора учитывается один раз за каждый достигнутый порог количества предметов на одном оружии. Модель оценивает набор по N-й сильнейшей матрице, необходимой для порога; выбор матриц с разным числом звёзд отдельно проверен не во всех случаях. Enhancement Shot меняет предельные значения базовых характеристик, но не эти уровни набора.",
    "Titan property: effect and CS": "Свойство Titan: эффект и CS",
    "The effect tooltip evaluates the game’s effect curve at the summed level. CS evaluates the separate display curve at each item’s own level and then sums its CS. A nonlinear curve means those two orders are not interchangeable. At level zero the effect is absent; between curve keys the model interpolates linearly and outside the keys it uses the endpoint. Gear CS already includes this property: do not add the Titan CS summary to gear CS again.": "В подсказке эффекта игровая кривая рассчитывается на суммарном уровне свойства. Для CS используется отдельная кривая отображения: сначала она рассчитывается на уровне каждого предмета, затем значения складываются. Из-за нелинейности кривой эти порядки расчёта нельзя менять местами. На нулевом уровне эффект отсутствует; между узловыми значениями модель использует линейную интерполяцию, а за их пределами — ближайшую конечную точку. CS экипировки уже включает это свойство, поэтому не прибавляйте сводное значение CS Titan к CS экипировки повторно.",
    "Supercomputing, Space Support and suppressor CS": "CS суперкомпьютера, Space Support и подавителя",
    "Raw attributes of the current level are weighted with the game attribute weights. Content modules give twice the DMG of a base DMG module and are scored with the same DMG% weight; the game weight of their final-DMG attribute is zero, so this is a model assumption. Supercomputing ATK% / RES%, healing and Shatter are not scored: weighting ATK% / RES% by the build’s bases would exceed the whole unexplained remainder of captured total CS. The game does not report a separate score for these systems, so each value is an estimate shown on hover over current CS; it is not added to the current CS.": "Необработанные характеристики текущего уровня взвешиваются по игровым коэффициентам атрибутов. Модули урона дают вдвое больше УРОН, чем базовый модуль урона, и оцениваются с тем же весом УРОН%; игровой вес их атрибута итогового урона равен нулю, поэтому это допущение модели. АТК% и СОПР% суперкомпьютера, лечение и Разрушение не оцениваются: если взвесить АТК% и СОПР% по базовым значениям билда, результат превысит весь не объяснённый другими системами остаток общего CS из снимка. Игра не показывает отдельную оценку этих систем, поэтому каждое значение — это оценка, отображаемая при наведении на текущий CS; к текущему CS она не прибавляется.",
    "Enhancement Shot CS": "CS от Enhancement Shot",
    "This is the weighted sum of the shot’s flat weapon/matrix gains. Universal ATK and RES count once, without combat ATK%/HP%/RES% and without matrix set AddScore or a new weapon StarSkillScore. The current profile model adds this subtotal once. It matches the documented before/after sample; it is not a universal proof of every indirect native CS change. Hovering current CS reveals this gain beside the shot, without a permanent caption.": "Это взвешенная сумма плоских прибавок выстрела к оружию и матрицам. Универсальные АТК и СОПР учитываются один раз, без боевых АТК%/ОЗ%/СОПР%, AddScore набора матриц и нового StarSkillScore оружия. Модель текущего профиля прибавляет эту сумму один раз. Значение совпадает с задокументированным примером до и после, но не доказывает универсальность для каждого косвенного изменения CS родной стихии. При наведении на текущий CS эта прибавка показывается рядом с выстрелом без постоянной подписи.",
    "Roll count and quality": "Число проков и качество",
    "Roll inference uses values before Titan, not current augmented values. The number of rolls must fit every row and the item’s total stars. If several splits fit, the card selects a likelihood estimate and marks disputed counts with ~; missing or impossible data gives ?. The likelihood model approximates sums of uniform rolls and is not a confirmed game drop distribution. Quality excludes initial values and is undefined for zero rolls or fixed-size rolls.": "Число проков определяется по значениям до Titan, а не по текущим усиленным значениям. Число проков должно подходить каждой строке и общему числу звёзд предмета. Если подходят несколько вариантов распределения, карточка выбирает наиболее вероятную оценку и отмечает неоднозначное число знаком ~; при отсутствующих или невозможных данных показывается ?. Модель вероятности приближает сумму равномерных проков и не является подтверждённым распределением выпадения в игре. При оценке качества начальные значения не учитываются; для нулевого числа проков и проков фиксированного размера качество не определяется.",
    "Titan maximum and pull-up": "Потолок Titan и подтягивание",
    "The row’s Titan maximum applies generated growth to its actual pre-Titan value; it does not replace its earlier rolls with perfect rolls. Elemental ATK, ATK% and DMG% have separate pull-up families among the native elements. Pull-up can raise a row’s maximum but cannot reduce its independent growth, including when original values are equal. Their ranks use generated factors; an unconfirmed rank leaves the projection unavailable. Tied primary stats are evaluated separately, and an ambiguous ceiling remains unknown. Current GRV/PRV uses actual captured values and does not require this forecast.": "Потолок Titan для строки рассчитывается по сгенерированному приросту от её фактического значения до Titan; прежние проки не заменяются идеальными. Для стихийной АТК, АТК% и УРОН% среди родных стихий предусмотрены отдельные семейства подтягивания. Подтягивание может увеличить потолок строки, но не может уменьшить её независимый прирост, даже если исходные значения равны. Ранг выбирается по сгенерированным коэффициентам; если ранг не подтверждён, прогноз недоступен. Одинаковые основные характеристики оцениваются отдельно, а неоднозначный потолок остаётся неизвестным. Для текущего GRV/PRV используются фактические данные снимка, и этот прогноз не требуется.",
    "Titan-added stat forecast": "Прогноз характеристик, добавленных Titan",
    "The primary is the stat with the most equivalent rolls before Titan. Each added stat uses that primary’s generated priority/fallback pool; existing random stats are excluded. Unused priority stats fill the available slots first, and fallback stats fill only the remainder. The added stat does not receive Titan growth again. The share is an observed calibration, not a proven game maximum or drop probability. Current ratings use the actual added value.": "Основная характеристика — та, у которой до Titan было больше всего эквивалентных проков. Для каждой добавленной характеристики используется сгенерированный список приоритетных и запасных значений этой основной характеристики; уже существующие случайные характеристики исключаются. Свободные приоритетные характеристики сначала занимают доступные слоты, а запасные заполняют только оставшиеся. Добавленная характеристика повторно не получает прирост Titan. Доля основана на наблюдениях и не является подтверждённым игровым максимумом или вероятностью выпадения. В текущих рейтингах используется фактическое добавленное значение."
  },
  "es": {
    "What the capture contains": "Contenido de la captura",
    "The file provides the first received profile stats, equipped items and captured progression. ATK has both a displayed base before ATK% and a native final value. HP and resistance are final values; their full percentage totals are not supplied. Missing fields remain unknown. These are snapshot values, rather than a live reading of the current game screen.": "El archivo proporciona las primeras estadísticas de perfil recibidas, elementos equipados y progresión capturada. ATQ tiene una base mostrada antes de ATQ% y un valor final nativo. PV y la resistencia son valores finales; no se proporcionan los totales porcentuales completos. Los campos faltantes siguen siendo desconocidos. Estos son valores instantáneos, en lugar de una lectura en vivo de la pantalla del juego actual.",
    "The pair inherits whole gear percentages": "El par hereda todos los porcentajes del equipo",
    "1 is the selected element and 2 its weapon partner. g is total gear ATK%; q is total gear DMG%. Their winners are chosen independently across the equipped set. Other sources stay on their own element. The stronger element keeps its own percentage; the weaker replaces only its gear portion. A standalone item’s GRV can choose its own winners, while Build totals keep one source per percentage for every slot.": "1 es el elemento seleccionado y 2 el elemento del arma que lo acompaña. g es el ATQ% total del equipo y q es su DMG% total. Los valores máximos de g y q se eligen por separado considerando todo el equipo equipado. Las demás fuentes de bonificación se mantienen en su elemento. El elemento más fuerte conserva su propio porcentaje; en el más débil solo se sustituye la parte procedente del equipo. El GRV de un objeto individual puede elegir sus propios máximos, mientras que el total de Configuración usa una sola fuente para cada porcentaje en todos los espacios.",
    "Pair ATK and Space Support": "ATQ del par y Apoyo espacial",
    "B is a displayed base, including its own Space Support S. Compare the pair after removing each element’s support, then add only the selected element’s support before ATK%. A selected Enhancement Shot’s universal flat ATK is already in both effective bases and is counted once. Do not add support again after percentages. Flat ATK used by the combat table and the per-item GRV choice are separate calculations.": "B es una base mostrada, que incluye su propio Apoyo espacial S. Compare el par después de eliminar el soporte de cada elemento, luego agregue solo el soporte del elemento seleccionado antes de ATQ%. Un ATQ plano universal de un Inyección de mejora seleccionado ya se encuentra en ambas bases efectivas y se cuenta una vez. No vuelva a agregar soporte después de los porcentajes. El ATQ plano utilizado por la tabla de combate y la elección GRV por elemento son cálculos separados.",
    "Altered combat ATK": "ATQ de combate Alterado",
    "The combat model copies the strongest native element’s own final ATK, without duo inheritance, and keeps the captured or entered own Altered remainder. Native shot bonuses are inherited after that source’s percentages, once. The card’s imported displayed Altered base already contains the copy, so it is not added to that base again. Altered gear rating uses a different source selection: one gear-only source for GRV, the personal source for PRV.": "El modelo de combate copia el ATQ final del elemento nativo más fuerte, sin herencia de dúo, y mantiene el resto del Alterado capturado o ingresado. Las bonificaciones de disparos nativos se heredan después de los porcentajes de esa fuente, una vez. La base Alterado importada de la tarjeta ya contiene la copia, por lo que no se vuelve a agregar a esa base. La clasificación de equipo Alterado utiliza una selección de fuente diferente: una fuente de solo equipo para GRV, la fuente personal para PRV.",
    "Temporary buffs at capture time": "Efectos temporales en el momento de la captura",
    "Recognized removable constant ATK% buffs are subtracted per element on import, including their stack count. A recognized flat or unknown-magnitude temporary ATK effect can block import. Permitted food and shots remain separate selected consumables. Unrecognized effects are not proof of a clean snapshot; use an out-of-combat capture and the source list when checking a discrepancy.": "Las mejoras ATQ% constantes extraíbles reconocidas se restan por elemento en el momento de la importación, incluido su recuento de pilas. Un efecto ATQ temporal reconocido, plano o de magnitud desconocida, puede bloquear la importación. Los alimentos y las vacunas permitidos siguen siendo consumibles seleccionados por separado. Los efectos no reconocidos no son prueba de una instantánea limpia; utilice una captura fuera de combate y la lista de fuentes al comprobar una discrepancia.",
    "Account relic passives": "Pasivas de reliquias de la cuenta",
    "Captured account relic passives apply even when those relics are not equipped. Their DMG% and RES% are distinct per-element values. Damage-received reduction is not automatically a resistance-stat multiplier: the capture’s attribute mapping determines which pool a passive affects. Relic A4 DMG% is included once in its own element’s combat DMG% and also shown in the relic summary. Relic RES% joins the known resistance multiplier once; changing the two equipped relics does not reset account passives.": "Las pasivas de reliquias de cuentas capturadas se aplican incluso cuando esas reliquias no están equipadas. Sus DMG% y RES% son valores distintos por elemento. La reducción del daño recibido no es automáticamente un multiplicador de estadísticas de resistencia: el mapeo de atributos de la captura determina a qué grupo afecta una pasiva. La reliquia A4 DMG% se incluye una vez en el combate de su propio elemento DMG% y también se muestra en el resumen de la reliquia. La reliquia RES% se une al multiplicador de resistencia conocido una vez; Cambiar las dos reliquias equipadas no restablece las pasivas de la cuenta.",
    "Unknown data and rounding": "Datos desconocidos y redondeo",
    "Calculations retain fractional values; separate displayed rows can differ by a unit after rounding. A blank required base is unknown, rather than zero. Unknown catalog items remain empty and are listed; catalog fitting is not verification of their effects. The badge ≈ denotes a modeled estimate. Up displays the normalized upgrade level stored in the file: the exporter has already converted the raw profile suffix by adding one. The card does not add one again. This model has no separate Up multiplier for weapon stat endpoints or weapon CS.": "Los cálculos conservan valores fraccionarios; Las filas separadas mostradas pueden diferir en una unidad después del redondeo. Se desconoce una base requerida en blanco, en lugar de cero. Los elementos desconocidos del catálogo permanecen vacíos y se enumeran; La adaptación del catálogo no es la verificación de sus efectos. La insignia ≈ denota una estimación modelada. Up muestra el nivel de actualización normalizado almacenado en el archivo: el exportador ya convirtió el sufijo del perfil sin formato agregando uno. La tarjeta no vuelve a agregar uno. Este modelo no tiene un multiplicador Up separado para los puntos finales de las estadísticas del arma o el CS del arma.",
    "Universal ATK": "ATQ universal",
    "Universal ATK is inferred, not a separately captured stat. The remainder includes universal gear ATK and external sources. The card shows it only when all four native bases are available and their remainders agree within one ATK. Otherwise it shows —. Its tooltip separates universal gear, the selected shot and remaining sources; it does not apply ATK% to this base.": "Universal ATQ se infiere, no es una estadística capturada por separado. El resto incluye equipo universal ATQ y fuentes externas. La tarjeta lo muestra solo cuando las cuatro bases nativas están disponibles y sus restos coinciden dentro de un ATQ. De lo contrario se nota —. Su información sobre herramientas separa el equipo universal, el disparo seleccionado y las fuentes restantes; no aplica ATQ% a esta base.",
    "HP and HP%": "PS y PS%",
    "h is full HP% as a fraction. Without an explicitly entered total, only equipped gear HP% is known. The tooltip separates the pre-percentage pool into other sources, gear and the shot, then shows the percentage gain and final HP. Unknown external HP% or another multiplier makes the restored base an estimate. A missing HP snapshot stays missing.": "h está completo PV% como fracción. Sin un total ingresado explícitamente, solo se conoce el equipo equipado PV%. La información sobre herramientas separa el grupo de porcentaje previo en otras fuentes, equipo y disparo, luego muestra el porcentaje de ganancia y el PV final. PV% externo desconocido u otro multiplicador hace que la base restaurada sea una estimación. Sigue faltando una instantánea PV.",
    "Crit rating and chance": "Valor de crítico y probabilidad de crítico",
    "The rating tooltip separates other sources, equipped gear and the shot. The level denominator comes from the game curve for the selected enemy level. The panel shows the uncapped sum; expected-output and personal rating calculations cap useful chance at 100%. Crit DMG is a bonus: the expected critical factor is 1 + c_rating × Crit DMG, rather than chance multiplied by full critical damage.": "La información sobre herramientas de clasificación separa otras fuentes, el equipo equipado y el disparo. El denominador de nivel proviene de la curva de juego del nivel del enemigo seleccionado. El panel muestra la suma ilimitada; Los cálculos de resultados esperados y de calificación personal limitan las posibilidades útiles al 100%. DMG crítico es una ventaja: el factor crítico esperado es 1 + c_rating × DMG crítico, en lugar de la probabilidad multiplicada por el daño crítico total.",
    "Resistance and damage reduction": "Resistencia y reducción de daño",
    "r is full RES%, or the known source sum when a full value is unavailable. Universal flat RES contributes to every element; elemental RES contributes only to its own. The shot is added before RES%. K uses character level, while the Crit curve uses enemy level. This reduction is the resistance component, not the product of every damage-reduction effect in combat. Tank EHP = HP × (1 + RES_effective / K).": "r es RES% completo, o la suma de origen conocida cuando un valor completo no está disponible. El plano universal RES contribuye a cada elemento; elemental RES contribuye sólo a lo suyo. La toma se agrega antes de RES%. K usa el nivel del personaje, mientras que la curva Crít. usa el nivel del enemigo. Esta reducción es el componente de resistencia, no el producto de cada efecto de reducción de daño en combate. Tanque EHP = PV × (1 + RES_efectivo / K).",
    "The combat DMG% column": "Columna de DMG% de combate",
    "For captures, this column is derived from the loadout; no full DMG% total is captured. Only generated recognized contributions enter it. Relic A4 is included once for its own element; duo inheritance replaces only gear DMG%, leaving relic and other non-gear bonuses on their own element. Alternative conditional Space Support modes do not stack: the strongest applicable mode per element is used. Imported Altered DMG% is zero in this model. This column is not a complete damage or rotation simulator.": "Para las capturas, esta columna se deriva del equipamiento; no se captura ningún total completo de DMG%. En él sólo ingresan las aportaciones reconocidas generadas. La reliquia A4 se incluye una vez por su propio elemento; La herencia de dúo reemplaza solo el equipo DMG%, dejando las reliquias y otras bonificaciones que no son de equipo en su propio elemento. Los modos condicionales alternativos Apoyo espacial no se acumulan: se utiliza el modo aplicable más fuerte por elemento. Alterado DMG% importado es cero en este modelo. Esta columna no es un simulador completo de daños o rotación.",
    "Enhancement Shot stat gain": "Aumento de estadísticas con la Inyección de mejora",
    "For weapons, the target is the catalog’s maximum weapon level at the weapon’s actual stars. For matrices, it is the maximum level and maximum base-stat advancement. The selected shot adds these four flat gains to the first received stats. HP and RES gains are multiplied by their percentages; native ATK gains are multiplied by native ATK%; Altered inherits once. It does not change captured stars, Up or matrix set-effect ranks. Recalculation replaces the previous applied gain and does not add it again.": "Para las armas, el objetivo es el nivel máximo de arma del catálogo en las estrellas reales del arma. Para matrices, es el nivel máximo y el avance máximo de estadísticas base. El disparo seleccionado suma estas cuatro ganancias fijas a las primeras estadísticas recibidas. Las ganancias PV y RES se multiplican por sus porcentajes; las ganancias nativas de ATQ se multiplican por las nativas ATQ%; Alterado hereda una vez. No cambia las estrellas capturadas, Up o los rangos de efectos de conjuntos de matrices. El recálculo reemplaza la ganancia aplicada anteriormente y no la suma nuevamente.",
    "Selected ATK% consumables": "Consumibles de ATQ% seleccionados",
    "The model applies only generated, recognized unconditional ATK% bonuses of selected consumables. A universal bonus targets the native elements declared by the catalog; it is not applied to Altered a second time. Unknown, conditional and other consumable effects are not inferred from their names. The expiry time describes the captured buff; the card is a saved configuration and does not automatically clear the selected consumable when that clock expires.": "El modelo aplica solo bonificaciones incondicionales ATQ% generadas y reconocidas de consumibles seleccionados. Un bono universal apunta a los elementos nativos declarados por el catálogo; no se aplica a Alterado por segunda vez. Los efectos desconocidos, condicionales y otros efectos consumibles no se deducen de sus nombres. El tiempo de vencimiento describe el beneficio capturado; la tarjeta es una configuración guardada y no borra automáticamente el consumible seleccionado cuando expira ese reloj.",
    "Current CS and Apex CS": "CS actual y CS máximo",
    "Current CS starts from the captured profile score or the manual input. The selected Enhancement Shot adds its modeled flat-stat CS delta once; when a precise captured CS is available, rounding starts from that value. Apex CS remains the recorded historical maximum with its recorded time. The model does not replace current CS with the sum of gear, weapons, matrices and other system estimates, and it does not infer a new complete CS after every manual loadout edit or recompute every other consumable’s CS impact. The displayed integer header difference can differ from the rounded shot subtotal by one because the original captured CS has a fraction.": "El CS actual comienza a partir de la puntuación del perfil capturada o de la entrada manual. El Inyección de mejora seleccionado agrega su delta de estadística plana modelada CS una vez; cuando un CS capturado preciso está disponible, el redondeo comienza a partir de ese valor. CS máximo mantiene el máximo histórico registrado con su tiempo registrado. El modelo no reemplaza el CS actual con la suma de equipo, armas, matrices y otras estimaciones del sistema, y ​​no infiere un nuevo CS completo después de cada edición de equipamiento manual ni recalcula el impacto de cada otro consumible CS. La diferencia del encabezado entero mostrado puede diferir del subtotal de disparo redondeado en uno porque el CS capturado original tiene una fracción.",
    "Weapon CS": "CS del arma",
    "The card’s weapon source label scores the weapon alone. Level gains and star coefficients come from generated game tables. Only the current star’s StarSkillScore is added, not the sum of all earlier stars. Matrix scores and their set AddScore are separate. The reconstruction matches documented server-score samples within floating-point differences; that does not establish every weapon, upgrade field or native rounding case.": "La etiqueta de origen del arma de la tarjeta puntúa solo el arma. Las ganancias de nivel y los coeficientes de estrellas provienen de tablas de juego generadas. Sólo se agrega el StarSkillScore de la estrella actual, no la suma de todas las estrellas anteriores. Las puntuaciones de Matrix y su conjunto AddScore están separados. La reconstrucción coincide con muestras documentadas de puntuación del servidor dentro de diferencias de punto flotante; eso no establece todas las armas, campos de actualización o casos de redondeo nativos.",
    "Matrices and set CS": "CS de matrices y conjuntos",
    "Each matrix uses its own slot profile, level and star multiplier. Use fractional stats for the score; the displayed matrix stat has its own float32 truncation. Set AddScore is counted once per reached piece threshold on one weapon. The model ranks the set by the threshold’s Nth strongest matrix; mixed-star selection has not been separately verified in every case. Enhancement Shot changes base-stat endpoints, not these set ranks.": "Cada matriz utiliza su propio perfil de tragamonedas, nivel y multiplicador de estrellas. Utilice estadísticas fraccionarias para la puntuación; la estadística de matriz mostrada tiene su propio truncamiento float32. El conjunto AddScore se cuenta una vez por cada umbral de pieza alcanzado en un arma. El modelo clasifica el conjunto según la enésima matriz más fuerte del umbral; La selección de estrellas mixtas no se ha verificado por separado en todos los casos. Inyección de mejora cambia los puntos finales de las estadísticas base, no estos rangos establecidos.",
    "Titan property: effect and CS": "Atributo de Titán: efecto y CS",
    "The effect tooltip evaluates the game’s effect curve at the summed level. CS evaluates the separate display curve at each item’s own level and then sums its CS. A nonlinear curve means those two orders are not interchangeable. At level zero the effect is absent; between curve keys the model interpolates linearly and outside the keys it uses the endpoint. Gear CS already includes this property: do not add the Titan CS summary to gear CS again.": "La información sobre herramientas del efecto evalúa la curva de efectos del juego en el nivel sumado. CS evalúa la curva de visualización separada en el nivel de cada elemento y luego suma su CS. Una curva no lineal significa que esos dos órdenes no son intercambiables. En el nivel cero el efecto está ausente; entre las claves de curva, el modelo interpola linealmente y fuera de las claves utiliza el punto final. El engranaje CS ya incluye esta propiedad: no agregue el resumen Titán CS al engranaje CS nuevamente.",
    "Supercomputing, Space Support and suppressor CS": "CS de Supercomputación, Apoyo espacial y supresor",
    "Raw attributes of the current level are weighted with the game attribute weights. Content modules give twice the DMG of a base DMG module and are scored with the same DMG% weight; the game weight of their final-DMG attribute is zero, so this is a model assumption. Supercomputing ATK% / RES%, healing and Shatter are not scored: weighting ATK% / RES% by the build’s bases would exceed the whole unexplained remainder of captured total CS. The game does not report a separate score for these systems, so each value is an estimate shown on hover over current CS; it is not added to the current CS.": "Los atributos sin procesar del nivel actual se ponderan con los pesos de los atributos del juego. Los módulos de contenido dan el doble de DMG de un módulo base DMG y se califican con el mismo peso DMG%; el peso del juego de su atributo final-DMG es cero, por lo que esta es una suposición del modelo. Supercomputación ATQ% / RES%, curación y Fractura no se puntúan: la ponderación ATQ% / RES% por las bases de la construcción excedería todo el resto inexplicable del total capturado CS. El juego no informa una puntuación separada para estos sistemas, por lo que cada valor es una estimación que se muestra al pasar el cursor sobre el CS actual; no se agrega al CS actual.",
    "Enhancement Shot CS": "CS de la Inyección de mejora",
    "This is the weighted sum of the shot’s flat weapon/matrix gains. Universal ATK and RES count once, without combat ATK%/HP%/RES% and without matrix set AddScore or a new weapon StarSkillScore. The current profile model adds this subtotal once. It matches the documented before/after sample; it is not a universal proof of every indirect native CS change. Hovering current CS reveals this gain beside the shot, without a permanent caption.": "Esta es la suma ponderada de las ganancias planas de arma/matriz del disparo. Universal ATQ y RES cuentan una vez, sin combate ATQ%/PV%/RES% y sin conjunto de matrices AddScore o una nueva arma StarSkillScore. El modelo de perfil actual agrega este subtotal una vez. Coincide con la muestra documentada de antes/después; no es una prueba universal de todos los cambios nativos indirectos CS. Al pasar el cursor sobre CS actual se revela esta ganancia junto a la toma, sin un título permanente.",
    "Roll count and quality": "Cantidad y calidad de las tiradas",
    "Roll inference uses values before Titan, not current augmented values. The number of rolls must fit every row and the item’s total stars. If several splits fit, the card selects a likelihood estimate and marks disputed counts with ~; missing or impossible data gives ?. The likelihood model approximates sums of uniform rolls and is not a confirmed game drop distribution. Quality excludes initial values and is undefined for zero rolls or fixed-size rolls.": "El número de tiradas se deduce a partir de los valores anteriores a Titán, no de los valores ya aumentados. Debe ser compatible con cada atributo y con el total de estrellas del objeto. Si hay varias distribuciones posibles, la tarjeta muestra una estimación de probabilidad y marca las cantidades dudosas con ~; si faltan datos o son imposibles, muestra ?. El modelo aproxima sumas de tiradas uniformes; la distribución real del juego no está confirmada. La calidad excluye los valores iniciales y no se define con cero tiradas ni con tiradas de valor fijo.",
    "Titan maximum and pull-up": "Máximo de Titán y tiradas de aumento",
    "The row’s Titan maximum applies generated growth to its actual pre-Titan value; it does not replace its earlier rolls with perfect rolls. Elemental ATK, ATK% and DMG% have separate pull-up families among the native elements. Pull-up can raise a row’s maximum but cannot reduce its independent growth, including when original values are equal. Their ranks use generated factors; an unconfirmed rank leaves the projection unavailable. Tied primary stats are evaluated separately, and an ambiguous ceiling remains unknown. Current GRV/PRV uses actual captured values and does not require this forecast.": "El máximo Titán de la fila aplica el crecimiento generado a su valor real anterior a Titán; no sustituye sus rollos anteriores por rollos perfectos. Los elementales ATQ, ATQ% y DMG% tienen familias pull-up separadas entre los elementos nativos. Pull-up puede aumentar el máximo de una fila pero no puede reducir su crecimiento independiente, incluso cuando los valores originales son iguales. Sus filas utilizan factores generados; una clasificación no confirmada deja la proyección no disponible. Las estadísticas primarias empatadas se evalúan por separado y se desconoce un límite ambiguo. El GRV/PRV actual utiliza valores capturados reales y no requiere este pronóstico.",
    "Titan-added stat forecast": "Pronóstico de estadísticas añadidas por Titán",
    "The primary is the stat with the most equivalent rolls before Titan. Each added stat uses that primary’s generated priority/fallback pool; existing random stats are excluded. Unused priority stats fill the available slots first, and fallback stats fill only the remainder. The added stat does not receive Titan growth again. The share is an observed calibration, not a proven game maximum or drop probability. Current ratings use the actual added value.": "La principal es la estadística con más tiradas equivalentes antes de Titán. Cada estadística agregada utiliza el grupo de prioridad/respaldo generado por ese primario; Se excluyen las estadísticas aleatorias existentes. Las estadísticas de prioridad no utilizadas llenan primero los espacios disponibles y las estadísticas de reserva solo llenan el resto. La estadística agregada no vuelve a recibir crecimiento Titán. La proporción es una calibración observada, no un máximo de juego probado o una probabilidad de caída. Las calificaciones actuales utilizan el valor agregado real."
  },
  "de": {
    "What the capture contains": "Inhalt der Aufzeichnung",
    "The file provides the first received profile stats, equipped items and captured progression. ATK has both a displayed base before ATK% and a native final value. HP and resistance are final values; their full percentage totals are not supplied. Missing fields remain unknown. These are snapshot values, rather than a live reading of the current game screen.": "Die Datei enthält die ersten erhaltenen Profilstatistiken, ausgerüsteten Gegenstände und den erfassten Fortschritt. ANG verfügt sowohl über eine angezeigte Basis vor ANG% als auch über einen nativen Endwert. TP und Widerstand sind Endwerte; Ihre vollständigen prozentualen Gesamtsummen werden nicht angegeben. Fehlende Felder bleiben unbekannt. Dabei handelt es sich um Momentaufnahmewerte und nicht um eine Live-Anzeige des aktuellen Spielbildschirms.",
    "The pair inherits whole gear percentages": "Das Duo übernimmt alle Ausrüstungsprozente",
    "1 is the selected element and 2 its weapon partner. g is total gear ATK%; q is total gear DMG%. Their winners are chosen independently across the equipped set. Other sources stay on their own element. The stronger element keeps its own percentage; the weaker replaces only its gear portion. A standalone item’s GRV can choose its own winners, while Build totals keep one source per percentage for every slot.": "1 ist das gewählte Element, 2 das Element der Partnerwaffe. g bezeichnet den gesamten ANG%-Wert der Ausrüstung, q den gesamten DMG%-Wert. Die Höchstwerte von g und q werden über die gesamte angelegte Ausrüstung unabhängig voneinander bestimmt. Andere Boni bleiben ihrem jeweiligen Element zugeordnet. Das stärkere Element behält seinen eigenen Prozentwert; beim schwächeren wird nur der Ausrüstungsanteil ersetzt. Der GRV eines einzelnen Gegenstands kann eigene Höchstwerte wählen; die Build-Gesamtwerte verwenden dagegen über alle Slots hinweg je Prozentwert nur eine Quelle.",
    "Pair ATK and Space Support": "ANG des Duos und Weltraum-Unterstützung",
    "B is a displayed base, including its own Space Support S. Compare the pair after removing each element’s support, then add only the selected element’s support before ATK%. A selected Enhancement Shot’s universal flat ATK is already in both effective bases and is counted once. Do not add support again after percentages. Flat ATK used by the combat table and the per-item GRV choice are separate calculations.": "B ist eine angezeigte Basis, einschließlich ihres eigenen Weltraum-Unterstützung S. Vergleichen Sie das Paar, nachdem Sie die Unterstützung jedes Elements entfernt haben, und fügen Sie dann nur die Unterstützung des ausgewählten Elements vor ANG% hinzu. Ein ausgewählter Verstärkungsspritze Universal Flat ANG befindet sich bereits in beiden Wirkbasen und wird einmal gezählt. Fügen Sie nach Prozentangaben keine Unterstützung mehr hinzu. Die flache ANG, die von der Kampftabelle verwendet wird, und die pro-Element-GRV-Auswahl sind separate Berechnungen.",
    "Altered combat ATK": "Verändert-Kampfangriff",
    "The combat model copies the strongest native element’s own final ATK, without duo inheritance, and keeps the captured or entered own Altered remainder. Native shot bonuses are inherited after that source’s percentages, once. The card’s imported displayed Altered base already contains the copy, so it is not added to that base again. Altered gear rating uses a different source selection: one gear-only source for GRV, the personal source for PRV.": "Das Kampfmodell kopiert den endgültigen ANG des stärksten nativen Elements ohne Duo-Vererbung und behält den erfassten oder eingegebenen eigenen Verändert-Rest bei. Native Shot-Boni werden einmalig nach den Prozentsätzen dieser Quelle vererbt. Die importierte angezeigte Verändert-Basis der Karte enthält bereits die Kopie, sodass sie dieser Basis nicht erneut hinzugefügt wird. Die Ausrüstungsbewertung von Verändert verwendet eine andere Quellenauswahl: eine reine Ausrüstungsquelle für GRV, die persönliche Quelle für PRV.",
    "Temporary buffs at capture time": "Temporäre Effekte zum Zeitpunkt der Aufzeichnung",
    "Recognized removable constant ATK% buffs are subtracted per element on import, including their stack count. A recognized flat or unknown-magnitude temporary ATK effect can block import. Permitted food and shots remain separate selected consumables. Unrecognized effects are not proof of a clean snapshot; use an out-of-combat capture and the source list when checking a discrepancy.": "Erkannte entfernbare konstante ANG%-Buffs werden beim Import pro Element abgezogen, einschließlich ihrer Stapelanzahl. Ein erkannter vorübergehender ANG-Effekt mit flachem oder unbekanntem Ausmaß kann den Import blockieren. Erlaubte Lebensmittel und Shots bleiben getrennte ausgewählte Verbrauchsmaterialien. Unerkannte Effekte sind kein Beweis für einen sauberen Schnappschuss; Verwenden Sie bei der Überprüfung einer Diskrepanz eine Erfassung außerhalb des Kampfes und die Quellenliste.",
    "Account relic passives": "Passive Relikteffekte des Accounts",
    "Captured account relic passives apply even when those relics are not equipped. Their DMG% and RES% are distinct per-element values. Damage-received reduction is not automatically a resistance-stat multiplier: the capture’s attribute mapping determines which pool a passive affects. Relic A4 DMG% is included once in its own element’s combat DMG% and also shown in the relic summary. Relic RES% joins the known resistance multiplier once; changing the two equipped relics does not reset account passives.": "Passive Relikte des erfassten Kontos gelten auch dann, wenn diese Relikte nicht ausgerüstet sind. Ihre DMG% und RES% sind unterschiedliche Werte pro Element. Die Reduzierung des erlittenen Schadens ist nicht automatisch ein Resistenzwert-Multiplikator: Die Attributzuordnung der Gefangennahme bestimmt, auf welchen Pool ein Passiv wirkt. Relikt A4 DMG% wird einmal in den Kampf seines eigenen Elements DMG% einbezogen und auch in der Reliktzusammenfassung angezeigt. Relikt RES% schließt sich dem bekannten Widerstandsmultiplikator einmal an; Durch das Ändern der beiden ausgerüsteten Relikte werden die Passivwerte des Kontos nicht zurückgesetzt.",
    "Unknown data and rounding": "Unbekannte Daten und Rundung",
    "Calculations retain fractional values; separate displayed rows can differ by a unit after rounding. A blank required base is unknown, rather than zero. Unknown catalog items remain empty and are listed; catalog fitting is not verification of their effects. The badge ≈ denotes a modeled estimate. Up displays the normalized upgrade level stored in the file: the exporter has already converted the raw profile suffix by adding one. The card does not add one again. This model has no separate Up multiplier for weapon stat endpoints or weapon CS.": "Bei Berechnungen werden Bruchwerte beibehalten; Einzelne angezeigte Zeilen können sich nach Rundung um eine Einheit unterscheiden. Eine leere erforderliche Basis ist unbekannt und nicht Null. Unbekannte Katalogelemente bleiben leer und werden aufgelistet; Die Kataloganpassung ist keine Überprüfung ihrer Auswirkungen. Das Abzeichen ≈ kennzeichnet eine modellierte Schätzung. Up zeigt die normalisierte Upgrade-Stufe an, die in der Datei gespeichert ist: Der Exporter hat das Rohprofil-Suffix bereits konvertiert, indem er eines hinzugefügt hat. Die Karte fügt keines mehr hinzu. Dieses Modell verfügt über keinen separaten Up-Multiplikator für Waffenstatistik-Endpunkte oder Waffen-ZZTTERM_6_text_0_MARKERZZZ.",
    "Universal ATK": "Universelle ANG",
    "Universal ATK is inferred, not a separately captured stat. The remainder includes universal gear ATK and external sources. The card shows it only when all four native bases are available and their remainders agree within one ATK. Otherwise it shows —. Its tooltip separates universal gear, the selected shot and remaining sources; it does not apply ATK% to this base.": "Universeller ANG wird abgeleitet, keine separat erfasste Statistik. Der Rest umfasst Universalausrüstung ANG und externe Quellen. Die Karte zeigt es nur an, wenn alle vier nativen Basen verfügbar sind und ihre Reste innerhalb eines ANG übereinstimmen. Ansonsten wird — angezeigt. Sein Tooltip trennt die Universalausrüstung, den ausgewählten Schuss und die übrigen Quellen; ANG% wird nicht auf diese Basis angewendet.",
    "HP and HP%": "TP und TP%",
    "h is full HP% as a fraction. Without an explicitly entered total, only equipped gear HP% is known. The tooltip separates the pre-percentage pool into other sources, gear and the shot, then shows the percentage gain and final HP. Unknown external HP% or another multiplier makes the restored base an estimate. A missing HP snapshot stays missing.": "h ist voll TP% als Bruch. Ohne explizit eingegebene Summe ist nur die ausgerüstete Ausrüstung TP% bekannt. Der Tooltip unterteilt den Vorprozentsatzpool in andere Quellen, Ausrüstung und den Schuss und zeigt dann den prozentualen Gewinn und den endgültigen TP an. Unbekannter externer TP% oder ein anderer Multiplikator macht die wiederhergestellte Basis zu einer Schätzung. Ein fehlender TP-Snapshot bleibt verschwunden.",
    "Crit rating and chance": "Krit-Wert und Krit-Chance",
    "The rating tooltip separates other sources, equipped gear and the shot. The level denominator comes from the game curve for the selected enemy level. The panel shows the uncapped sum; expected-output and personal rating calculations cap useful chance at 100%. Crit DMG is a bonus: the expected critical factor is 1 + c_rating × Crit DMG, rather than chance multiplied by full critical damage.": "Der Bewertungs-Tooltip trennt andere Quellen, ausgerüstete Ausrüstung und den Schuss. Der Levelnenner ergibt sich aus der Spielkurve für das ausgewählte Gegnerlevel. Das Panel zeigt die unbegrenzte Summe; Berechnungen zur erwarteten Leistung und zur persönlichen Bewertung begrenzen die nützliche Chance auf 100 %. Krit-DMG ist ein Bonus: Der erwartete kritische Faktor ist 1 + c_rating × Krit-DMG und nicht Chance multipliziert mit vollem kritischen Schaden.",
    "Resistance and damage reduction": "Widerstand und Schadensreduktion",
    "r is full RES%, or the known source sum when a full value is unavailable. Universal flat RES contributes to every element; elemental RES contributes only to its own. The shot is added before RES%. K uses character level, while the Crit curve uses enemy level. This reduction is the resistance component, not the product of every damage-reduction effect in combat. Tank EHP = HP × (1 + RES_effective / K).": "r ist der volle RES% oder die bekannte Quellsumme, wenn kein vollständiger Wert verfügbar ist. Universal Flat RES trägt zu jedem Element bei; elementar RES trägt nur zu seinem eigenen bei. Die Aufnahme wird vor RES% hinzugefügt. K verwendet die Charakterebene, während die Krit-Kurve die Feindebene verwendet. Diese Reduzierung ist die Widerstandskomponente und nicht das Produkt jedes Schadensreduzierungseffekts im Kampf. Tank EHP = TP × (1 + RES_effektiv / K).",
    "The combat DMG% column": "Kampf-DMG%-Spalte",
    "For captures, this column is derived from the loadout; no full DMG% total is captured. Only generated recognized contributions enter it. Relic A4 is included once for its own element; duo inheritance replaces only gear DMG%, leaving relic and other non-gear bonuses on their own element. Alternative conditional Space Support modes do not stack: the strongest applicable mode per element is used. Imported Altered DMG% is zero in this model. This column is not a complete damage or rotation simulator.": "Bei Captures wird diese Spalte vom Loadout abgeleitet; Es wird keine vollständige DMG%-Gesamtsumme erfasst. Es werden nur generierte anerkannte Beiträge berücksichtigt. Relic A4 ist einmalig für ein eigenes Element enthalten; Die Duo-Vererbung ersetzt nur die Ausrüstung DMG%, Relikte und andere Nicht-Ausrüstungsboni verbleiben in ihrem eigenen Element. Alternative bedingte Weltraum-Unterstützung-Modi sind nicht stapelbar: Der stärkste anwendbare Modus pro Element wird verwendet. Importiert Verändert DMG% ist in diesem Modell Null. Bei dieser Spalte handelt es sich nicht um einen vollständigen Schadens- oder Rotationssimulator.",
    "Enhancement Shot stat gain": "Wertegewinn durch Verstärkungsspritze",
    "For weapons, the target is the catalog’s maximum weapon level at the weapon’s actual stars. For matrices, it is the maximum level and maximum base-stat advancement. The selected shot adds these four flat gains to the first received stats. HP and RES gains are multiplied by their percentages; native ATK gains are multiplied by native ATK%; Altered inherits once. It does not change captured stars, Up or matrix set-effect ranks. Recalculation replaces the previous applied gain and does not add it again.": "Bei Waffen ist das Ziel die maximale Waffenstufe des Katalogs an den tatsächlichen Sternen der Waffe. Bei Matrizen handelt es sich um die maximale Stufe und den maximalen Basiswert-Fortschritt. Der ausgewählte Schuss fügt diese vier Pauschalgewinne zu den ersten erhaltenen Statistiken hinzu. TP- und RES-Gewinne werden mit ihren Prozentsätzen multipliziert; native ANG-Gewinne werden mit nativem ANG% multipliziert; Verändert erbt einmal. Erfasste Sterne, Up oder Matrix-Set-Effekt-Ränge werden nicht geändert. Durch die Neuberechnung wird die zuvor angewendete Verstärkung ersetzt und nicht erneut hinzugefügt.",
    "Selected ATK% consumables": "Ausgewählte ANG%-Verbrauchsmittel",
    "The model applies only generated, recognized unconditional ATK% bonuses of selected consumables. A universal bonus targets the native elements declared by the catalog; it is not applied to Altered a second time. Unknown, conditional and other consumable effects are not inferred from their names. The expiry time describes the captured buff; the card is a saved configuration and does not automatically clear the selected consumable when that clock expires.": "Das Modell wendet nur generierte, anerkannte bedingungslose ANG%-Boni ausgewählter Verbrauchsmaterialien an. Ein universeller Bonus zielt auf die im Katalog deklarierten nativen Elemente ab; es wird kein zweites Mal auf Verändert angewendet. Unbekannte, bedingte und andere verbrauchbare Effekte lassen sich aus ihren Namen nicht ableiten. Die Ablaufzeit beschreibt den erfassten Buff; Die Karte ist eine gespeicherte Konfiguration und löscht das ausgewählte Verbrauchsmaterial nicht automatisch, wenn diese Zeit abläuft.",
    "Current CS and Apex CS": "Aktuelle CS und Spitzen-CS",
    "Current CS starts from the captured profile score or the manual input. The selected Enhancement Shot adds its modeled flat-stat CS delta once; when a precise captured CS is available, rounding starts from that value. Apex CS remains the recorded historical maximum with its recorded time. The model does not replace current CS with the sum of gear, weapons, matrices and other system estimates, and it does not infer a new complete CS after every manual loadout edit or recompute every other consumable’s CS impact. The displayed integer header difference can differ from the rounded shot subtotal by one because the original captured CS has a fraction.": "Der aktuelle CS beginnt mit der erfassten Profilbewertung oder der manuellen Eingabe. Der ausgewählte Verstärkungsspritze fügt sein modelliertes Flat-Stat-Delta CS einmal hinzu; Wenn ein präzise erfasster CS verfügbar ist, beginnt die Rundung bei diesem Wert. Spitzen-CS bleibt mit seiner aufgezeichneten Zeit das aufgezeichnete historische Maximum. Das Modell ersetzt den aktuellen CS nicht durch die Summe von Ausrüstung, Waffen, Matrizen und anderen Systemschätzungen und leitet keinen neuen vollständigen CS nach jeder manuellen Auslastungsbearbeitung ab oder berechnet die CS-Auswirkungen aller anderen Verbrauchsgüter neu. Die angezeigte ganzzahlige Kopfzeilendifferenz kann um eins von der gerundeten Zwischensumme abweichen, da der ursprünglich erfasste CS einen Bruch enthält.",
    "Weapon CS": "Waffen-CS",
    "The card’s weapon source label scores the weapon alone. Level gains and star coefficients come from generated game tables. Only the current star’s StarSkillScore is added, not the sum of all earlier stars. Matrix scores and their set AddScore are separate. The reconstruction matches documented server-score samples within floating-point differences; that does not establish every weapon, upgrade field or native rounding case.": "Das Waffenquellenetikett der Karte wertet nur die Waffe. Levelgewinne und Sternkoeffizienten stammen aus generierten Spieltabellen. Es wird nur der StarSkillScore des aktuellen Sterns hinzugefügt, nicht die Summe aller früheren Sterne. Matrixwerte und ihr Satz AddScore sind getrennt. Die Rekonstruktion gleicht dokumentierte Server-Score-Stichproben innerhalb von Gleitkomma-Differenzen ab; Das gilt nicht für jede Waffe, jedes Upgrade-Feld oder jeden nativen Rundungsfall.",
    "Matrices and set CS": "Matrix- und Set-CS",
    "Each matrix uses its own slot profile, level and star multiplier. Use fractional stats for the score; the displayed matrix stat has its own float32 truncation. Set AddScore is counted once per reached piece threshold on one weapon. The model ranks the set by the threshold’s Nth strongest matrix; mixed-star selection has not been separately verified in every case. Enhancement Shot changes base-stat endpoints, not these set ranks.": "Jede Matrix verwendet ihr eigenes Slot-Profil, Level und Sternmultiplikator. Verwenden Sie Bruchstatistiken für die Punktzahl. Die angezeigte Matrixstatistik hat ihre eigene Kürzung float32. Das Set AddScore wird einmal pro erreichtem Stückschwellenwert einer Waffe gezählt. Das Modell ordnet die Menge nach der N-t-stärksten Matrix des Schwellenwerts; Die Mixed-Star-Auswahl wurde nicht in jedem Fall gesondert überprüft. Verstärkungsspritze ändert Basisstatistik-Endpunkte, nicht diese festgelegten Ränge.",
    "Titan property: effect and CS": "Titan-Attribut: Effekt und CS",
    "The effect tooltip evaluates the game’s effect curve at the summed level. CS evaluates the separate display curve at each item’s own level and then sums its CS. A nonlinear curve means those two orders are not interchangeable. At level zero the effect is absent; between curve keys the model interpolates linearly and outside the keys it uses the endpoint. Gear CS already includes this property: do not add the Titan CS summary to gear CS again.": "Der Effekt-Tooltip wertet die Effektkurve des Spiels auf der summierten Ebene aus. CS wertet die separate Anzeigekurve auf der Ebene jedes Elements aus und summiert dann deren CS. Eine nichtlineare Kurve bedeutet, dass diese beiden Ordnungen nicht austauschbar sind. Auf Stufe Null ist der Effekt nicht vorhanden; Zwischen Kurvenschlüsseln interpoliert das Modell linear und außerhalb der Schlüssel verwendet es den Endpunkt. Ausrüstung CS enthält diese Eigenschaft bereits: Fügen Sie die Zusammenfassung Titan CS nicht erneut zum Ausrüstung CS hinzu.",
    "Supercomputing, Space Support and suppressor CS": "CS von Supercomputing, Weltraum-Unterstützung und Suppressor",
    "Raw attributes of the current level are weighted with the game attribute weights. Content modules give twice the DMG of a base DMG module and are scored with the same DMG% weight; the game weight of their final-DMG attribute is zero, so this is a model assumption. Supercomputing ATK% / RES%, healing and Shatter are not scored: weighting ATK% / RES% by the build’s bases would exceed the whole unexplained remainder of captured total CS. The game does not report a separate score for these systems, so each value is an estimate shown on hover over current CS; it is not added to the current CS.": "Rohattribute des aktuellen Levels werden mit den Spielattributgewichten gewichtet. Inhaltsmodule ergeben das Doppelte des DMG eines Basismoduls DMG und werden mit der gleichen DMG%-Gewichtung bewertet; Die Spielgewichtung ihres final-DMG-Attributs ist Null, es handelt sich also um eine Modellannahme. Supercomputing ANG% / RES%, Heilung und Zerschmettern werden nicht gewertet: Die Gewichtung von ANG% / RES% durch die Basen des Builds würde den gesamten ungeklärten Rest der erfassten Gesamtsumme überschreiten CS. Das Spiel meldet für diese Systeme keinen separaten Punktestand, daher ist jeder Wert eine Schätzung, die angezeigt wird, wenn man mit der Maus über den aktuellen CS fährt; Es wird nicht zum aktuellen CS hinzugefügt.",
    "Enhancement Shot CS": "CS durch Verstärkungsspritze",
    "This is the weighted sum of the shot’s flat weapon/matrix gains. Universal ATK and RES count once, without combat ATK%/HP%/RES% and without matrix set AddScore or a new weapon StarSkillScore. The current profile model adds this subtotal once. It matches the documented before/after sample; it is not a universal proof of every indirect native CS change. Hovering current CS reveals this gain beside the shot, without a permanent caption.": "Dies ist die gewichtete Summe der flachen Waffen-/Matrixgewinne des Schusses. Universal ANG und RES zählen einmal, ohne Kampf ANG%/TP%/RES% und ohne Matrixsatz AddScore oder eine neue Waffe StarSkillScore. Das aktuelle Profilmodell addiert diese Zwischensumme einmalig. Es entspricht dem dokumentierten Vorher/Nachher-Muster; Es ist kein universeller Beweis für jede indirekte native CS-Änderung. Wenn Sie über den aktuellen CS schweben, wird dieser Gewinn neben der Aufnahme angezeigt, ohne permanente Beschriftung.",
    "Roll count and quality": "Anzahl und Qualität der Aufwertungen",
    "Roll inference uses values before Titan, not current augmented values. The number of rolls must fit every row and the item’s total stars. If several splits fit, the card selects a likelihood estimate and marks disputed counts with ~; missing or impossible data gives ?. The likelihood model approximates sums of uniform rolls and is not a confirmed game drop distribution. Quality excludes initial values and is undefined for zero rolls or fixed-size rolls.": "Die Anzahl der Aufwertungen wird aus den Werten vor Titan abgeleitet, nicht aus den aktuell verstärkten Werten. Sie muss zu jeder Zeile und zur Gesamtzahl der Sterne des Gegenstands passen. Sind mehrere Verteilungen möglich, zeigt die Karte eine Wahrscheinlichkeitsschätzung an und kennzeichnet unsichere Anzahlen mit ~; bei fehlenden oder unmöglichen Daten erscheint ?. Das Wahrscheinlichkeitsmodell nähert Summen gleichverteilter Aufwertungswerte an; die tatsächliche Verteilung im Spiel ist nicht bestätigt. Die Qualität berücksichtigt keine Anfangswerte und ist bei null Aufwertungen oder festen Aufwertungswerten nicht definiert.",
    "Titan maximum and pull-up": "Titan-Maximum und Hochziehen",
    "The row’s Titan maximum applies generated growth to its actual pre-Titan value; it does not replace its earlier rolls with perfect rolls. Elemental ATK, ATK% and DMG% have separate pull-up families among the native elements. Pull-up can raise a row’s maximum but cannot reduce its independent growth, including when original values are equal. Their ranks use generated factors; an unconfirmed rank leaves the projection unavailable. Tied primary stats are evaluated separately, and an ambiguous ceiling remains unknown. Current GRV/PRV uses actual captured values and does not require this forecast.": "Das Titan-Maximum der Zeile wendet das generierte Wachstum auf den tatsächlichen Wert vor Titan an; Es ersetzt seine früheren Rollen nicht durch perfekte Rollen. Elemental ANG, ANG% und DMG% verfügen über separate Pull-up-Familien unter den nativen Elementen. Pull-up kann das Maximum einer Zeile erhöhen, ihr unabhängiges Wachstum jedoch nicht verringern, auch wenn die ursprünglichen Werte gleich sind. Ihre Ränge nutzen generierte Faktoren; ein unbestätigter Rang führt dazu, dass die Projektion nicht verfügbar ist. Gleiche Primärstatistiken werden separat ausgewertet und eine unklare Obergrenze bleibt unbekannt. Der aktuelle GRV/PRV verwendet tatsächlich erfasste Werte und erfordert diese Prognose nicht.",
    "Titan-added stat forecast": "Prognose der von Titan hinzugefügten Werte",
    "The primary is the stat with the most equivalent rolls before Titan. Each added stat uses that primary’s generated priority/fallback pool; existing random stats are excluded. Unused priority stats fill the available slots first, and fallback stats fill only the remainder. The added stat does not receive Titan growth again. The share is an observed calibration, not a proven game maximum or drop probability. Current ratings use the actual added value.": "Der primäre Wert ist der Wert mit den meisten gleichwertigen Würfen vor Titan. Jede hinzugefügte Statistik verwendet den generierten Prioritäts-/Fallback-Pool dieser Primärdatenbank. Vorhandene Zufallsstatistiken sind ausgeschlossen. Nicht genutzte Prioritätsstatistiken füllen zuerst die verfügbaren Plätze, und Ersatzstatistiken füllen nur den Rest. Die hinzugefügte Statistik erhält kein erneutes Titan-Wachstum. Der Anteil ist eine beobachtete Kalibrierung, kein nachgewiesenes Spielmaximum oder eine Drop-Wahrscheinlichkeit. Aktuelle Bewertungen nutzen den tatsächlichen Mehrwert."
  },
  "fr": {
    "What the capture contains": "Contenu de la capture",
    "The file provides the first received profile stats, equipped items and captured progression. ATK has both a displayed base before ATK% and a native final value. HP and resistance are final values; their full percentage totals are not supplied. Missing fields remain unknown. These are snapshot values, rather than a live reading of the current game screen.": "Le fichier fournit les premières statistiques de profil reçues, les objets équipés et la progression capturée. ATQ a à la fois une base affichée avant ATQ% et une valeur finale native. PV et la résistance sont des valeurs finales ; leurs totaux complets en pourcentage ne sont pas fournis. Les champs manquants restent inconnus. Il s'agit de valeurs instantanées, plutôt que d'une lecture en direct de l'écran de jeu actuel.",
    "The pair inherits whole gear percentages": "Le duo hérite de tous les pourcentages de l’équipement",
    "1 is the selected element and 2 its weapon partner. g is total gear ATK%; q is total gear DMG%. Their winners are chosen independently across the equipped set. Other sources stay on their own element. The stronger element keeps its own percentage; the weaker replaces only its gear portion. A standalone item’s GRV can choose its own winners, while Build totals keep one source per percentage for every slot.": "1 correspond à l’élément sélectionné et 2 à celui de l’arme partenaire. g désigne l’ATQ% total de l’équipement et q son DMG% total. Les valeurs maximales de g et de q sont choisies séparément sur l’ensemble de l’équipement porté. Les autres bonus restent associés à leur élément. L’élément le plus fort conserve son propre pourcentage ; pour l’autre, seule la part issue de l’équipement est remplacée. Le GRV d’un objet seul peut choisir ses propres valeurs maximales, tandis que les totaux Équipement ne retiennent qu’une source par pourcentage sur l’ensemble des emplacements.",
    "Pair ATK and Space Support": "ATQ du duo et Soutien spatial",
    "B is a displayed base, including its own Space Support S. Compare the pair after removing each element’s support, then add only the selected element’s support before ATK%. A selected Enhancement Shot’s universal flat ATK is already in both effective bases and is counted once. Do not add support again after percentages. Flat ATK used by the combat table and the per-item GRV choice are separate calculations.": "B est une base affichée, comprenant son propre Soutien spatial S. Comparez la paire après avoir supprimé le support de chaque élément, puis ajoutez uniquement le support de l'élément sélectionné avant ATQ%. Le plat universel ATQ d'un Injection de renforcement sélectionné est déjà dans les deux bases effectives et est compté une fois. N'ajoutez plus de support après les pourcentages. Le ATQ plat utilisé par la table de combat et le choix GRV par élément sont des calculs distincts.",
    "Altered combat ATK": "ATQ de combat de l’Altéré",
    "The combat model copies the strongest native element’s own final ATK, without duo inheritance, and keeps the captured or entered own Altered remainder. Native shot bonuses are inherited after that source’s percentages, once. The card’s imported displayed Altered base already contains the copy, so it is not added to that base again. Altered gear rating uses a different source selection: one gear-only source for GRV, the personal source for PRV.": "Le modèle de combat copie le ATQ final de l'élément natif le plus fort, sans héritage duo, et conserve le reste Altéré capturé ou entré. Les bonus de tir natifs sont hérités une fois après les pourcentages de cette source. La base Altéré affichée importée de la carte contient déjà la copie, elle n'est donc pas ajoutée à nouveau à cette base. Altéré gear rating utilise une sélection de source différente : une source d'engrenage uniquement pour GRV, la source personnelle pour PRV.",
    "Temporary buffs at capture time": "Bonus temporaires au moment de la capture",
    "Recognized removable constant ATK% buffs are subtracted per element on import, including their stack count. A recognized flat or unknown-magnitude temporary ATK effect can block import. Permitted food and shots remain separate selected consumables. Unrecognized effects are not proof of a clean snapshot; use an out-of-combat capture and the source list when checking a discrepancy.": "Les buffs ATQ% constants amovibles reconnus sont soustraits par élément lors de l'importation, y compris leur nombre de piles. Un effet ATQ temporaire reconnu, plat ou d'ampleur inconnue, peut bloquer l'importation. La nourriture et les shots autorisés restent des consommables sélectionnés séparés. Les effets non reconnus ne sont pas la preuve d’un instantané propre ; utilisez une capture hors combat et la liste des sources lors de la vérification d'une anomalie.",
    "Account relic passives": "Passifs des reliques du compte",
    "Captured account relic passives apply even when those relics are not equipped. Their DMG% and RES% are distinct per-element values. Damage-received reduction is not automatically a resistance-stat multiplier: the capture’s attribute mapping determines which pool a passive affects. Relic A4 DMG% is included once in its own element’s combat DMG% and also shown in the relic summary. Relic RES% joins the known resistance multiplier once; changing the two equipped relics does not reset account passives.": "Les passifs des reliques de compte capturées s'appliquent même lorsque ces reliques ne sont pas équipées. Leurs DMG% et RÉS% sont des valeurs distinctes par élément. La réduction des dégâts reçus n’est pas automatiquement un multiplicateur de statistiques de résistance : la cartographie des attributs de la capture détermine le pool qu’un passif affecte. La relique A4 DMG% est incluse une fois dans le combat de son propre élément DMG% et également affichée dans le résumé de la relique. La relique RÉS% rejoint une fois le multiplicateur de résistance connu ; changer les deux reliques équipées ne réinitialise pas les passifs du compte.",
    "Unknown data and rounding": "Données inconnues et arrondis",
    "Calculations retain fractional values; separate displayed rows can differ by a unit after rounding. A blank required base is unknown, rather than zero. Unknown catalog items remain empty and are listed; catalog fitting is not verification of their effects. The badge ≈ denotes a modeled estimate. Up displays the normalized upgrade level stored in the file: the exporter has already converted the raw profile suffix by adding one. The card does not add one again. This model has no separate Up multiplier for weapon stat endpoints or weapon CS.": "Les calculs conservent les valeurs fractionnaires ; les lignes affichées séparément peuvent différer d’une unité après arrondi. Une base vierge requise est inconnue, plutôt que nulle. Les éléments de catalogue inconnus restent vides et sont répertoriés ; l’ajustement du catalogue n’est pas une vérification de leurs effets. Le badge ≈ désigne une estimation modélisée. Up affiche le niveau de mise à niveau normalisé stocké dans le fichier : l'exportateur a déjà converti le suffixe brut du profil en en ajoutant un. La carte n’en ajoute plus. Ce modèle n'a pas de multiplicateur Up distinct pour les points finaux de statistiques d'armes ou les armes CS.",
    "Universal ATK": "ATQ universelle",
    "Universal ATK is inferred, not a separately captured stat. The remainder includes universal gear ATK and external sources. The card shows it only when all four native bases are available and their remainders agree within one ATK. Otherwise it shows —. Its tooltip separates universal gear, the selected shot and remaining sources; it does not apply ATK% to this base.": "Universal ATQ est déduit, pas une statistique capturée séparément. Le reste comprend l'engrenage universel ATQ et des sources externes. La carte ne l'affiche que lorsque les quatre bases natives sont disponibles et que leurs restes concordent dans un ATQ. Sinon, cela montre -. Son info-bulle sépare l'équipement universel, le plan sélectionné et les sources restantes ; il n'applique pas ATQ% à cette base.",
    "HP and HP%": "PV et PV%",
    "h is full HP% as a fraction. Without an explicitly entered total, only equipped gear HP% is known. The tooltip separates the pre-percentage pool into other sources, gear and the shot, then shows the percentage gain and final HP. Unknown external HP% or another multiplier makes the restored base an estimate. A missing HP snapshot stays missing.": "h est plein PV% sous forme de fraction. Sans total explicitement saisi, seul l'équipement équipé PV% est connu. L'info-bulle sépare le pool de pré-pourcentage en autres sources, équipement et tir, puis affiche le pourcentage de gain et le PV final. Un PV% externe inconnu ou un autre multiplicateur fait de la base restaurée une estimation. Un instantané PV manquant reste manquant.",
    "Crit rating and chance": "Valeur de critique et taux de critique",
    "The rating tooltip separates other sources, equipped gear and the shot. The level denominator comes from the game curve for the selected enemy level. The panel shows the uncapped sum; expected-output and personal rating calculations cap useful chance at 100%. Crit DMG is a bonus: the expected critical factor is 1 + c_rating × Crit DMG, rather than chance multiplied by full critical damage.": "L'info-bulle de notation sépare les autres sources, l'équipement équipé et le tir. Le dénominateur de niveau provient de la courbe de jeu pour le niveau de l'ennemi sélectionné. Le panneau affiche la somme non plafonnée ; les calculs de rendement attendu et de notation personnelle plafonnent les chances utiles à 100 %. DMG critique est un bonus : le facteur critique attendu est de 1 + c_rating × DMG critique, plutôt que le hasard multiplié par la totalité des dégâts critiques.",
    "Resistance and damage reduction": "Résistance et réduction des dégâts",
    "r is full RES%, or the known source sum when a full value is unavailable. Universal flat RES contributes to every element; elemental RES contributes only to its own. The shot is added before RES%. K uses character level, while the Crit curve uses enemy level. This reduction is the resistance component, not the product of every damage-reduction effect in combat. Tank EHP = HP × (1 + RES_effective / K).": "r est RÉS% complet, ou la somme source connue lorsqu'une valeur complète n'est pas disponible. Le plat universel RÉS contribue à chaque élément ; elemental RÉS ne contribue qu'au sien. Le plan est ajouté avant RÉS%. K utilise le niveau du personnage, tandis que la courbe Crit. utilise le niveau de l'ennemi. Cette réduction est la composante de résistance, et non le produit de chaque effet de réduction des dégâts au combat. Réservoir EHP = PV × (1 + RÉS_effect / K).",
    "The combat DMG% column": "Colonne de DMG% de combat",
    "For captures, this column is derived from the loadout; no full DMG% total is captured. Only generated recognized contributions enter it. Relic A4 is included once for its own element; duo inheritance replaces only gear DMG%, leaving relic and other non-gear bonuses on their own element. Alternative conditional Space Support modes do not stack: the strongest applicable mode per element is used. Imported Altered DMG% is zero in this model. This column is not a complete damage or rotation simulator.": "Pour les captures, cette colonne est dérivée du chargement ; aucun total DMG% complet n'est capturé. Seules les contributions reconnues générées y entrent. La relique A4 est incluse une fois pour son propre élément ; L'héritage duo remplace uniquement l'équipement DMG%, laissant les reliques et autres bonus non-équipement sur leur propre élément. Les modes conditionnels alternatifs Soutien spatial ne s'empilent pas : le mode applicable le plus puissant par élément est utilisé. Altéré importé DMG% est nul dans ce modèle. Cette colonne n'est pas un simulateur complet de dégâts ou de rotation.",
    "Enhancement Shot stat gain": "Gain de statistiques avec l’Injection de renforcement",
    "For weapons, the target is the catalog’s maximum weapon level at the weapon’s actual stars. For matrices, it is the maximum level and maximum base-stat advancement. The selected shot adds these four flat gains to the first received stats. HP and RES gains are multiplied by their percentages; native ATK gains are multiplied by native ATK%; Altered inherits once. It does not change captured stars, Up or matrix set-effect ranks. Recalculation replaces the previous applied gain and does not add it again.": "Pour les armes, la cible est le niveau d’arme maximum du catalogue aux étoiles réelles de l’arme. Pour les matrices, il s’agit du niveau maximum et de l’avancement maximum des statistiques de base. Le tir sélectionné ajoute ces quatre gains plats aux premières statistiques reçues. Les gains de PV et RÉS sont multipliés par leurs pourcentages ; Les gains natifs de ATQ sont multipliés par les gains natifs de ATQ% ; Altéré hérite une fois. Cela ne change pas les étoiles capturées, Up ou les rangs d'effets de matrice. Le recalcul remplace le gain appliqué précédemment et ne l'ajoute pas à nouveau.",
    "Selected ATK% consumables": "Consommables d’ATQ% sélectionnés",
    "The model applies only generated, recognized unconditional ATK% bonuses of selected consumables. A universal bonus targets the native elements declared by the catalog; it is not applied to Altered a second time. Unknown, conditional and other consumable effects are not inferred from their names. The expiry time describes the captured buff; the card is a saved configuration and does not automatically clear the selected consumable when that clock expires.": "Le modèle applique uniquement les bonus ATQ% inconditionnels générés et reconnus des consommables sélectionnés. Un bonus universel cible les éléments natifs déclarés par le catalogue ; il n'est pas appliqué à Altéré une seconde fois. Les effets inconnus, conditionnels et autres consommables ne sont pas déduits de leurs noms. Le délai d'expiration décrit le buff capturé ; la carte est une configuration enregistrée et n'efface pas automatiquement le consommable sélectionné à l'expiration de cette horloge.",
    "Current CS and Apex CS": "CS actuelle et CS maximale",
    "Current CS starts from the captured profile score or the manual input. The selected Enhancement Shot adds its modeled flat-stat CS delta once; when a precise captured CS is available, rounding starts from that value. Apex CS remains the recorded historical maximum with its recorded time. The model does not replace current CS with the sum of gear, weapons, matrices and other system estimates, and it does not infer a new complete CS after every manual loadout edit or recompute every other consumable’s CS impact. The displayed integer header difference can differ from the rounded shot subtotal by one because the original captured CS has a fraction.": "Le CS actuel démarre à partir du score de profil capturé ou de la saisie manuelle. Le Injection de renforcement sélectionné ajoute une fois son delta CS à statut plat modélisé ; lorsqu'un CS capturé précis est disponible, l'arrondi commence à partir de cette valeur. CS maximal reste le maximum historique enregistré avec son heure enregistrée. Le modèle ne remplace pas le CS actuel par la somme des équipements, armes, matrices et autres estimations du système, et il ne déduit pas un nouveau CS complet après chaque modification manuelle du chargement ou ne recalcule pas l'impact CS de chaque autre consommable. La différence d'en-tête entière affichée peut différer d'une unité du sous-total du plan arrondi, car le CS capturé d'origine comporte une fraction.",
    "Weapon CS": "CS de l’arme",
    "The card’s weapon source label scores the weapon alone. Level gains and star coefficients come from generated game tables. Only the current star’s StarSkillScore is added, not the sum of all earlier stars. Matrix scores and their set AddScore are separate. The reconstruction matches documented server-score samples within floating-point differences; that does not establish every weapon, upgrade field or native rounding case.": "L’étiquette de source d’arme de la carte indique seule l’arme. Les gains de niveaux et les coefficients d'étoiles proviennent des tables de jeu générées. Seul le StarSkillScore de l'étoile actuelle est ajouté, pas la somme de toutes les étoiles précédentes. Les scores matriciels et leur ensemble AddScore sont distincts. La reconstruction fait correspondre les échantillons de scores du serveur documentés avec des différences en virgule flottante ; cela n’établit pas chaque arme, champ de mise à niveau ou cas d’arrondi natif.",
    "Matrices and set CS": "CS des matrices et des ensembles",
    "Each matrix uses its own slot profile, level and star multiplier. Use fractional stats for the score; the displayed matrix stat has its own float32 truncation. Set AddScore is counted once per reached piece threshold on one weapon. The model ranks the set by the threshold’s Nth strongest matrix; mixed-star selection has not been separately verified in every case. Enhancement Shot changes base-stat endpoints, not these set ranks.": "Chaque matrice utilise son propre profil d'emplacement, son niveau et son multiplicateur d'étoiles. Utilisez des statistiques fractionnaires pour le score ; la statistique matricielle affichée a sa propre troncature float32. L'ensemble AddScore est compté une fois par seuil de pièce atteint sur une arme. Le modèle classe l’ensemble selon la Nième matrice la plus forte du seuil ; la sélection d’étoiles mixtes n’a pas été vérifiée séparément dans chaque cas. Injection de renforcement modifie les points de terminaison des statistiques de base, pas ces classements définis.",
    "Titan property: effect and CS": "Attribut Titan : effet et CS",
    "The effect tooltip evaluates the game’s effect curve at the summed level. CS evaluates the separate display curve at each item’s own level and then sums its CS. A nonlinear curve means those two orders are not interchangeable. At level zero the effect is absent; between curve keys the model interpolates linearly and outside the keys it uses the endpoint. Gear CS already includes this property: do not add the Titan CS summary to gear CS again.": "L’info-bulle des effets évalue la courbe d’effet du jeu au niveau total. CS évalue la courbe d'affichage séparée au niveau de chaque élément, puis additionne son CS. Une courbe non linéaire signifie que ces deux ordres ne sont pas interchangeables. Au niveau zéro, l'effet est absent ; entre les clés de courbe, le modèle interpole linéairement et en dehors des clés, il utilise le point final. Équipement CS inclut déjà cette propriété : n'ajoutez pas à nouveau le résumé Titan CS à gear CS.",
    "Supercomputing, Space Support and suppressor CS": "CS du Supercalcul, du Soutien spatial et du suppresseur",
    "Raw attributes of the current level are weighted with the game attribute weights. Content modules give twice the DMG of a base DMG module and are scored with the same DMG% weight; the game weight of their final-DMG attribute is zero, so this is a model assumption. Supercomputing ATK% / RES%, healing and Shatter are not scored: weighting ATK% / RES% by the build’s bases would exceed the whole unexplained remainder of captured total CS. The game does not report a separate score for these systems, so each value is an estimate shown on hover over current CS; it is not added to the current CS.": "Les attributs bruts du niveau actuel sont pondérés avec les poids des attributs du jeu. Les modules de contenu donnent deux fois le DMG d'un module de base DMG et sont notés avec le même poids DMG% ; le poids du jeu de leur attribut final-DMG est nul, il s'agit donc d'une hypothèse de modèle. Le calcul intensif ATQ% / RÉS%, la guérison et Fracture ne sont pas notés : la pondération de ATQ% / RÉS% par les bases du build dépasserait tout le reste inexpliqué du total capturé. CS. Le jeu ne rapporte pas de score distinct pour ces systèmes, donc chaque valeur est une estimation affichée en survolant le CS actuel ; il n'est pas ajouté au CS actuel.",
    "Enhancement Shot CS": "CS de l’Injection de renforcement",
    "This is the weighted sum of the shot’s flat weapon/matrix gains. Universal ATK and RES count once, without combat ATK%/HP%/RES% and without matrix set AddScore or a new weapon StarSkillScore. The current profile model adds this subtotal once. It matches the documented before/after sample; it is not a universal proof of every indirect native CS change. Hovering current CS reveals this gain beside the shot, without a permanent caption.": "Il s’agit de la somme pondérée des gains d’arme/matrice à plat du tir. Les ATQ et RÉS universels comptent une fois, sans combat ATQ%/PV%/RÉS% et sans jeu de matrices AddScore ou une nouvelle arme StarSkillScore. Le modèle de profil actuel ajoute ce sous-total une fois. Il correspond à l’échantillon avant/après documenté ; ce n'est pas une preuve universelle de chaque changement natif indirect de CS. Le survol du courant CS révèle ce gain à côté du plan, sans légende permanente.",
    "Roll count and quality": "Nombre et qualité des améliorations",
    "Roll inference uses values before Titan, not current augmented values. The number of rolls must fit every row and the item’s total stars. If several splits fit, the card selects a likelihood estimate and marks disputed counts with ~; missing or impossible data gives ?. The likelihood model approximates sums of uniform rolls and is not a confirmed game drop distribution. Quality excludes initial values and is undefined for zero rolls or fixed-size rolls.": "Le nombre d’améliorations est déduit des valeurs avant Titan, et non des valeurs actuellement augmentées. Il doit correspondre à chaque ligne et au total d’étoiles de l’objet. Si plusieurs répartitions conviennent, la carte affiche une estimation de vraisemblance et signale les nombres incertains avec ~ ; des données manquantes ou impossibles donnent ?. Le modèle approxime la somme d’améliorations uniformes ; la distribution réelle du jeu n’est pas confirmée. La qualité ignore les valeurs initiales et n’est pas définie avec zéro amélioration ou des valeurs fixes.",
    "Titan maximum and pull-up": "Maximum Titan et amélioration des valeurs",
    "The row’s Titan maximum applies generated growth to its actual pre-Titan value; it does not replace its earlier rolls with perfect rolls. Elemental ATK, ATK% and DMG% have separate pull-up families among the native elements. Pull-up can raise a row’s maximum but cannot reduce its independent growth, including when original values are equal. Their ranks use generated factors; an unconfirmed rank leaves the projection unavailable. Tied primary stats are evaluated separately, and an ambiguous ceiling remains unknown. Current GRV/PRV uses actual captured values and does not require this forecast.": "Le maximum Titan de la ligne applique la croissance générée à sa valeur réelle avant Titan ; il ne remplace pas ses rouleaux antérieurs par des rouleaux parfaits. Elemental ATQ, ATQ% et DMG% ont des familles de pull-up distinctes parmi les éléments natifs. Le pull-up peut augmenter le maximum d'une ligne mais ne peut pas réduire sa croissance indépendante, y compris lorsque les valeurs d'origine sont égales. Leurs rangs utilisent des facteurs générés ; un classement non confirmé rend la projection indisponible. Les statistiques primaires liées sont évaluées séparément et un plafond ambigu reste inconnu. Le GRV/PRV actuel utilise les valeurs réelles capturées et ne nécessite pas cette prévision.",
    "Titan-added stat forecast": "Prévision des statistiques ajoutées par Titan",
    "The primary is the stat with the most equivalent rolls before Titan. Each added stat uses that primary’s generated priority/fallback pool; existing random stats are excluded. Unused priority stats fill the available slots first, and fallback stats fill only the remainder. The added stat does not receive Titan growth again. The share is an observed calibration, not a proven game maximum or drop probability. Current ratings use the actual added value.": "La principale est la statistique avec les lancers les plus équivalents avant Titan. Chaque statistique ajoutée utilise le pool de priorité/de repli généré par ce principal ; Les statistiques aléatoires existantes sont exclues. Les statistiques de priorité inutilisées remplissent d'abord les emplacements disponibles, et les statistiques de secours ne remplissent que le reste. La statistique ajoutée ne reçoit plus la croissance Titan. La part est un calibrage observé, et non un maximum de jeu prouvé ou une probabilité de chute. Les notations actuelles utilisent la valeur ajoutée réelle."
  },
  "id": {
    "What the capture contains": "Isi data tangkapan",
    "The file provides the first received profile stats, equipped items and captured progression. ATK has both a displayed base before ATK% and a native final value. HP and resistance are final values; their full percentage totals are not supplied. Missing fields remain unknown. These are snapshot values, rather than a live reading of the current game screen.": "File ini menyediakan statistik profil pertama yang diterima, item yang dilengkapi, dan perkembangan yang diambil. ATK memiliki basis yang ditampilkan sebelum ATK% dan nilai akhir asli. HP dan resistansi adalah nilai akhir; total persentase penuhnya tidak diberikan. Bidang yang hilang masih belum diketahui. Ini adalah nilai snapshot, bukan pembacaan langsung dari layar game saat ini.",
    "The pair inherits whole gear percentages": "Pasangan mewarisi semua persentase perlengkapan",
    "1 is the selected element and 2 its weapon partner. g is total gear ATK%; q is total gear DMG%. Their winners are chosen independently across the equipped set. Other sources stay on their own element. The stronger element keeps its own percentage; the weaker replaces only its gear portion. A standalone item’s GRV can choose its own winners, while Build totals keep one source per percentage for every slot.": "1 adalah elemen yang dipilih, sedangkan 2 adalah elemen dari senjata pasangannya. g adalah total ATK% dari seluruh perlengkapan dan q adalah total DMG%-nya. Nilai maksimum g dan q dipilih secara terpisah dari seluruh perlengkapan yang dikenakan. Bonus dari sumber lain tetap pada elemennya masing-masing. Elemen yang lebih kuat mempertahankan persentasenya sendiri; pada elemen yang lebih lemah, hanya bagian dari perlengkapan yang diganti. GRV untuk satu item dapat memilih nilai maksimum sendiri, sedangkan total Build memakai satu sumber untuk tiap persentase di seluruh slot.",
    "Pair ATK and Space Support": "ATK pasangan dan Dukungan luar angkasa",
    "B is a displayed base, including its own Space Support S. Compare the pair after removing each element’s support, then add only the selected element’s support before ATK%. A selected Enhancement Shot’s universal flat ATK is already in both effective bases and is counted once. Do not add support again after percentages. Flat ATK used by the combat table and the per-item GRV choice are separate calculations.": "B adalah basis yang ditampilkan, termasuk Dukungan luar angkasa S miliknya sendiri. Bandingkan pasangan setelah menghapus dukungan setiap elemen, lalu tambahkan hanya dukungan elemen yang dipilih sebelum ATK%. Flat universal Suntikan Penguat yang dipilih ATK sudah berada di kedua basis efektif dan dihitung satu kali. Jangan menambahkan dukungan lagi setelah persentase. ATK datar yang digunakan oleh tabel pertarungan dan pilihan GRV per item merupakan penghitungan terpisah.",
    "Altered combat ATK": "ATK tempur Altered",
    "The combat model copies the strongest native element’s own final ATK, without duo inheritance, and keeps the captured or entered own Altered remainder. Native shot bonuses are inherited after that source’s percentages, once. The card’s imported displayed Altered base already contains the copy, so it is not added to that base again. Altered gear rating uses a different source selection: one gear-only source for GRV, the personal source for PRV.": "Model tempur menyalin ATK akhir milik elemen asli terkuat, tanpa pewarisan duo, dan mempertahankan sisa Altered yang ditangkap atau dimasukkan. Bonus tembakan asli diwarisi setelah persentase sumber tersebut, satu kali. Basis Altered yang diimpor dari kartu sudah berisi salinannya, sehingga tidak ditambahkan ke basis itu lagi. Peringkat roda gigi Altered menggunakan pilihan sumber yang berbeda: satu sumber khusus roda gigi untuk GRV, sumber pribadi untuk PRV.",
    "Temporary buffs at capture time": "Buff sementara saat pengambilan data",
    "Recognized removable constant ATK% buffs are subtracted per element on import, including their stack count. A recognized flat or unknown-magnitude temporary ATK effect can block import. Permitted food and shots remain separate selected consumables. Unrecognized effects are not proof of a clean snapshot; use an out-of-combat capture and the source list when checking a discrepancy.": "Buff ATK% konstan yang dapat dilepas dan dikenali dikurangi per elemen saat diimpor, termasuk jumlah tumpukannya. Efek ATK sementara yang dikenali datar atau besarnya tidak diketahui dapat memblokir impor. Makanan dan suntikan yang diizinkan tetap merupakan bahan habis pakai yang dipilih secara terpisah. Efek yang tidak dikenali bukanlah bukti dari gambaran yang bersih; gunakan tangkapan di luar pertempuran dan daftar sumber saat memeriksa perbedaan.",
    "Account relic passives": "Pasif relik akun",
    "Captured account relic passives apply even when those relics are not equipped. Their DMG% and RES% are distinct per-element values. Damage-received reduction is not automatically a resistance-stat multiplier: the capture’s attribute mapping determines which pool a passive affects. Relic A4 DMG% is included once in its own element’s combat DMG% and also shown in the relic summary. Relic RES% joins the known resistance multiplier once; changing the two equipped relics does not reset account passives.": "Pasif relik akun yang diambil berlaku bahkan ketika relik tersebut tidak dilengkapi. DMG% dan RES% merupakan nilai per elemen yang berbeda. Pengurangan kerusakan yang diterima tidak secara otomatis merupakan pengganda status resistensi: pemetaan atribut penangkapan menentukan kelompok mana yang terkena dampak pasif. Relik A4 DMG% disertakan satu kali dalam pertarungan elemennya sendiri DMG% dan juga ditampilkan dalam ringkasan relik. Relik RES% bergabung dengan pengganda resistensi yang diketahui satu kali; mengganti dua relik yang dilengkapi tidak akan mengatur ulang pasif akun.",
    "Unknown data and rounding": "Data yang tidak diketahui dan pembulatan",
    "Calculations retain fractional values; separate displayed rows can differ by a unit after rounding. A blank required base is unknown, rather than zero. Unknown catalog items remain empty and are listed; catalog fitting is not verification of their effects. The badge ≈ denotes a modeled estimate. Up displays the normalized upgrade level stored in the file: the exporter has already converted the raw profile suffix by adding one. The card does not add one again. This model has no separate Up multiplier for weapon stat endpoints or weapon CS.": "Perhitungan mempertahankan nilai pecahan; baris terpisah yang ditampilkan dapat berbeda satu unit setelah pembulatan. Basis kosong yang diperlukan tidak diketahui, bukan nol. Item katalog yang tidak diketahui tetap kosong dan terdaftar; penyesuaian katalog bukanlah verifikasi dampaknya. Lencana ≈ menunjukkan perkiraan model. Up menampilkan tingkat pemutakhiran yang dinormalisasi yang disimpan dalam file: eksportir telah mengonversi akhiran profil mentah dengan menambahkan satu. Kartu tidak menambahkannya lagi. Model ini tidak memiliki pengganda Up terpisah untuk titik akhir status senjata atau CS senjata.",
    "Universal ATK": "ATK universal",
    "Universal ATK is inferred, not a separately captured stat. The remainder includes universal gear ATK and external sources. The card shows it only when all four native bases are available and their remainders agree within one ATK. Otherwise it shows —. Its tooltip separates universal gear, the selected shot and remaining sources; it does not apply ATK% to this base.": "ATK universal disimpulkan, bukan statistik yang diambil secara terpisah. Sisanya mencakup perlengkapan universal ATK dan sumber eksternal. Kartu menampilkannya hanya ketika keempat basis asli tersedia dan sisanya setuju dalam satu ATK. Kalau tidak, itu akan menunjukkan —. Tooltipnya memisahkan perlengkapan universal, bidikan yang dipilih, dan sumber yang tersisa; itu tidak berlaku ATK% pada basis ini.",
    "HP and HP%": "HP dan HP%",
    "h is full HP% as a fraction. Without an explicitly entered total, only equipped gear HP% is known. The tooltip separates the pre-percentage pool into other sources, gear and the shot, then shows the percentage gain and final HP. Unknown external HP% or another multiplier makes the restored base an estimate. A missing HP snapshot stays missing.": "h penuh HP% sebagai pecahan. Tanpa total yang dimasukkan secara eksplisit, hanya perlengkapan HP% yang diketahui. Tooltip memisahkan kumpulan pra-persentase menjadi sumber lain, perlengkapan dan bidikan, lalu menampilkan persentase perolehan dan HP akhir. HP% eksternal yang tidak diketahui atau pengganda lainnya menjadikan basis yang dipulihkan sebagai perkiraan. Cuplikan HP yang hilang tetap hilang.",
    "Crit rating and chance": "Nilai Krit dan peluang Krit",
    "The rating tooltip separates other sources, equipped gear and the shot. The level denominator comes from the game curve for the selected enemy level. The panel shows the uncapped sum; expected-output and personal rating calculations cap useful chance at 100%. Crit DMG is a bonus: the expected critical factor is 1 + c_rating × Crit DMG, rather than chance multiplied by full critical damage.": "Tooltip pemeringkatan memisahkan sumber lain, perlengkapan yang dilengkapi, dan pengambilan gambar. Penyebut level berasal dari kurva permainan untuk level musuh yang dipilih. Panel menunjukkan jumlah yang belum dibatasi; perhitungan hasil yang diharapkan dan peringkat pribadi membatasi peluang berguna sebesar 100%. DMG krit adalah bonus: faktor kritis yang diharapkan adalah 1 + c_rating × DMG krit, bukan peluang dikalikan dengan kerusakan kritis penuh.",
    "Resistance and damage reduction": "Resistansi dan pengurangan damage",
    "r is full RES%, or the known source sum when a full value is unavailable. Universal flat RES contributes to every element; elemental RES contributes only to its own. The shot is added before RES%. K uses character level, while the Crit curve uses enemy level. This reduction is the resistance component, not the product of every damage-reduction effect in combat. Tank EHP = HP × (1 + RES_effective / K).": "r penuh RES%, atau jumlah sumber yang diketahui ketika nilai penuh tidak tersedia. Flat universal RES berkontribusi pada setiap elemen; elemen RES hanya berkontribusi pada elemennya sendiri. Bidikan ditambahkan sebelum RES%. K menggunakan level karakter, sedangkan kurva Krit menggunakan level musuh. Pengurangan ini merupakan komponen resistensi, bukan produk dari setiap efek pengurangan kerusakan dalam pertempuran. Tangki EHP = HP × (1 + RES_efektif / K).",
    "The combat DMG% column": "Kolom DMG% pertempuran",
    "For captures, this column is derived from the loadout; no full DMG% total is captured. Only generated recognized contributions enter it. Relic A4 is included once for its own element; duo inheritance replaces only gear DMG%, leaving relic and other non-gear bonuses on their own element. Alternative conditional Space Support modes do not stack: the strongest applicable mode per element is used. Imported Altered DMG% is zero in this model. This column is not a complete damage or rotation simulator.": "Untuk pengambilan, kolom ini berasal dari pemuatan; tidak ada total DMG% lengkap yang diambil. Hanya kontribusi diakui yang dihasilkan yang masuk ke dalamnya. Relik A4 disertakan satu kali untuk elemennya sendiri; warisan duo hanya menggantikan perlengkapan DMG%, meninggalkan relik dan bonus non-peralatan lainnya pada elemennya sendiri. Mode Dukungan luar angkasa bersyarat alternatif tidak ditumpuk: mode terkuat yang berlaku per elemen akan digunakan. Altered DMG% yang diimpor adalah nol dalam model ini. Kolom ini bukanlah simulator kerusakan atau rotasi yang lengkap.",
    "Enhancement Shot stat gain": "Peningkatan stat dari Suntikan Penguat",
    "For weapons, the target is the catalog’s maximum weapon level at the weapon’s actual stars. For matrices, it is the maximum level and maximum base-stat advancement. The selected shot adds these four flat gains to the first received stats. HP and RES gains are multiplied by their percentages; native ATK gains are multiplied by native ATK%; Altered inherits once. It does not change captured stars, Up or matrix set-effect ranks. Recalculation replaces the previous applied gain and does not add it again.": "Untuk senjata, targetnya adalah level maksimum senjata dalam katalog pada bintang senjata sebenarnya. Untuk matriks, ini adalah level maksimum dan kemajuan status dasar maksimum. Tembakan yang dipilih menambahkan empat perolehan datar ini ke statistik pertama yang diterima. HP dan RES keuntungan dikalikan dengan persentasenya; perolehan ATK asli dikalikan dengan ATK% asli; Altered mewarisi satu kali. Itu tidak mengubah bintang yang diambil, Up atau peringkat efek set matriks. Penghitungan ulang menggantikan penguatan yang diterapkan sebelumnya dan tidak menambahkannya lagi.",
    "Selected ATK% consumables": "Konsumsi ATK% yang dipilih",
    "The model applies only generated, recognized unconditional ATK% bonuses of selected consumables. A universal bonus targets the native elements declared by the catalog; it is not applied to Altered a second time. Unknown, conditional and other consumable effects are not inferred from their names. The expiry time describes the captured buff; the card is a saved configuration and does not automatically clear the selected consumable when that clock expires.": "Model ini hanya menerapkan bonus ATK% tanpa syarat yang dihasilkan dan diakui dari bahan habis pakai terpilih. Bonus universal menargetkan elemen asli yang dinyatakan dalam katalog; itu tidak diterapkan pada Altered untuk kedua kalinya. Efek yang tidak diketahui, bersyarat, dan efek konsumsi lainnya tidak dapat disimpulkan dari namanya. Waktu kedaluwarsa menggambarkan buff yang ditangkap; kartu tersebut merupakan konfigurasi yang disimpan dan tidak secara otomatis menghapus bahan habis pakai yang dipilih ketika jam tersebut habis masa berlakunya.",
    "Current CS and Apex CS": "CS saat ini dan CS tertinggi",
    "Current CS starts from the captured profile score or the manual input. The selected Enhancement Shot adds its modeled flat-stat CS delta once; when a precise captured CS is available, rounding starts from that value. Apex CS remains the recorded historical maximum with its recorded time. The model does not replace current CS with the sum of gear, weapons, matrices and other system estimates, and it does not infer a new complete CS after every manual loadout edit or recompute every other consumable’s CS impact. The displayed integer header difference can differ from the rounded shot subtotal by one because the original captured CS has a fraction.": "CS saat ini dimulai dari skor profil yang diambil atau input manual. Suntikan Penguat yang dipilih menambahkan delta CS status datar yang dimodelkan satu kali; ketika CS yang ditangkap dengan tepat tersedia, pembulatan dimulai dari nilai tersebut. Puncak CS tetap menjadi rekor maksimum dalam sejarah dengan waktu yang tercatat. Model ini tidak menggantikan CS saat ini dengan jumlah perlengkapan, senjata, matriks, dan perkiraan sistem lainnya, dan tidak menyimpulkan CS baru yang lengkap setelah setiap pengeditan pemuatan manual atau menghitung ulang dampak CS setiap bahan habis pakai lainnya. Perbedaan header bilangan bulat yang ditampilkan dapat berbeda satu dengan subtotal bidikan yang dibulatkan karena CS asli yang diambil memiliki pecahan.",
    "Weapon CS": "CS senjata",
    "The card’s weapon source label scores the weapon alone. Level gains and star coefficients come from generated game tables. Only the current star’s StarSkillScore is added, not the sum of all earlier stars. Matrix scores and their set AddScore are separate. The reconstruction matches documented server-score samples within floating-point differences; that does not establish every weapon, upgrade field or native rounding case.": "Label sumber senjata pada kartu memberi skor pada senjata itu sendiri. Peningkatan level dan koefisien bintang berasal dari tabel permainan yang dihasilkan. Hanya StarSkillScore bintang saat ini yang ditambahkan, bukan jumlah semua bintang sebelumnya. Skor matriks dan himpunan AddScore terpisah. Rekonstruksi mencocokkan sampel skor server yang terdokumentasi dalam perbedaan floating-point; yang tidak menetapkan setiap senjata, bidang peningkatan, atau kotak pembulatan asli.",
    "Matrices and set CS": "CS matriks dan set",
    "Each matrix uses its own slot profile, level and star multiplier. Use fractional stats for the score; the displayed matrix stat has its own float32 truncation. Set AddScore is counted once per reached piece threshold on one weapon. The model ranks the set by the threshold’s Nth strongest matrix; mixed-star selection has not been separately verified in every case. Enhancement Shot changes base-stat endpoints, not these set ranks.": "Setiap matriks menggunakan profil slot, level, dan pengganda bintangnya sendiri. Gunakan statistik pecahan untuk skor; statistik matriks yang ditampilkan memiliki pemotongan float32 sendiri. Set AddScore dihitung satu kali per ambang bidak yang tercapai pada satu senjata. Model ini memberi peringkat pada himpunan berdasarkan matriks terkuat ke-N pada ambang batas; pemilihan bintang campuran belum diverifikasi secara terpisah di setiap kasus. Suntikan Penguat mengubah titik akhir status dasar, bukan peringkat yang ditetapkan ini.",
    "Titan property: effect and CS": "Atribut Titan: efek dan CS",
    "The effect tooltip evaluates the game’s effect curve at the summed level. CS evaluates the separate display curve at each item’s own level and then sums its CS. A nonlinear curve means those two orders are not interchangeable. At level zero the effect is absent; between curve keys the model interpolates linearly and outside the keys it uses the endpoint. Gear CS already includes this property: do not add the Titan CS summary to gear CS again.": "Keterangan alat efek mengevaluasi kurva efek permainan pada tingkat penjumlahan. CS mengevaluasi kurva tampilan terpisah pada tingkat masing-masing item dan kemudian menjumlahkan CS-nya. Kurva nonlinier berarti kedua tatanan tersebut tidak dapat dipertukarkan. Pada level nol, efeknya tidak ada; antara kunci kurva, model melakukan interpolasi secara linier dan di luar kunci, model menggunakan titik akhir. Perlengkapan CS sudah menyertakan properti ini: jangan tambahkan ringkasan Titan CS ke gear CS lagi.",
    "Supercomputing, Space Support and suppressor CS": "CS Supercomputing, Dukungan luar angkasa, dan suppressor",
    "Raw attributes of the current level are weighted with the game attribute weights. Content modules give twice the DMG of a base DMG module and are scored with the same DMG% weight; the game weight of their final-DMG attribute is zero, so this is a model assumption. Supercomputing ATK% / RES%, healing and Shatter are not scored: weighting ATK% / RES% by the build’s bases would exceed the whole unexplained remainder of captured total CS. The game does not report a separate score for these systems, so each value is an estimate shown on hover over current CS; it is not added to the current CS.": "Atribut mentah pada level saat ini diberi bobot dengan bobot atribut game. Modul konten memberikan DMG dua kali lipat dari modul DMG dasar dan diberi skor dengan bobot DMG% yang sama; bobot game dari atribut final-DMG adalah nol, jadi ini adalah asumsi model. Superkomputer ATK% / RES%, penyembuhan dan Shatter tidak diberi skor: pembobotan ATK% / RES% oleh basis pembangunan akan melebihi keseluruhan sisa yang tidak dapat dijelaskan dari total CS. Game ini tidak melaporkan skor terpisah untuk sistem ini, sehingga setiap nilai merupakan perkiraan yang ditampilkan saat mengarahkan kursor ke CS saat ini; itu tidak ditambahkan ke CS saat ini.",
    "Enhancement Shot CS": "CS Suntikan Penguat",
    "This is the weighted sum of the shot’s flat weapon/matrix gains. Universal ATK and RES count once, without combat ATK%/HP%/RES% and without matrix set AddScore or a new weapon StarSkillScore. The current profile model adds this subtotal once. It matches the documented before/after sample; it is not a universal proof of every indirect native CS change. Hovering current CS reveals this gain beside the shot, without a permanent caption.": "Ini adalah jumlah tertimbang dari perolehan senjata datar/matriks tembakan. ATK dan RES dihitung satu kali, tanpa pertarungan ATK%/HP%/RES% dan tanpa kumpulan matriks AddScore atau senjata baru StarSkillScore. Model profil saat ini menambahkan subtotal ini satu kali. Cocok dengan sampel sebelum/sesudah yang didokumentasikan; ini bukan bukti universal dari setiap perubahan CS asli tidak langsung. Mengarahkan kursor ke CS menunjukkan peningkatan ini di samping gambar, tanpa teks permanen.",
    "Roll count and quality": "Jumlah dan kualitas roll",
    "Roll inference uses values before Titan, not current augmented values. The number of rolls must fit every row and the item’s total stars. If several splits fit, the card selects a likelihood estimate and marks disputed counts with ~; missing or impossible data gives ?. The likelihood model approximates sums of uniform rolls and is not a confirmed game drop distribution. Quality excludes initial values and is undefined for zero rolls or fixed-size rolls.": "Jumlah roll disimpulkan dari nilai sebelum Titan, bukan nilai yang sudah ditingkatkan. Jumlahnya harus sesuai dengan setiap baris atribut dan total bintang item. Jika beberapa pembagian cocok, kartu menampilkan perkiraan kemungkinan dan menandai jumlah yang belum pasti dengan ~; data yang hilang atau tidak mungkin menghasilkan ?. Model kemungkinan ini memperkirakan jumlah roll yang seragam dan bukan distribusi drop game yang sudah dikonfirmasi. Kualitas tidak memasukkan nilai awal dan tidak terdefinisi jika jumlah roll nol atau ukuran roll tetap.",
    "Titan maximum and pull-up": "Batas maksimum Titan dan peningkatan roll",
    "The row’s Titan maximum applies generated growth to its actual pre-Titan value; it does not replace its earlier rolls with perfect rolls. Elemental ATK, ATK% and DMG% have separate pull-up families among the native elements. Pull-up can raise a row’s maximum but cannot reduce its independent growth, including when original values are equal. Their ranks use generated factors; an unconfirmed rank leaves the projection unavailable. Tied primary stats are evaluated separately, and an ambiguous ceiling remains unknown. Current GRV/PRV uses actual captured values and does not require this forecast.": "Titan maksimum baris menerapkan pertumbuhan yang dihasilkan ke nilai aktual sebelum Titan; itu tidak menggantikan gulungan sebelumnya dengan gulungan sempurna. Elemen ATK, ATK% dan DMG% memiliki keluarga pull-up terpisah di antara elemen asli. Pull-up dapat menaikkan maksimum suatu baris tetapi tidak dapat mengurangi pertumbuhan independennya, termasuk ketika nilai aslinya sama. Peringkat mereka menggunakan faktor-faktor yang dihasilkan; peringkat yang belum dikonfirmasi membuat proyeksi tidak tersedia. Statistik utama yang terikat dievaluasi secara terpisah, dan batas atas yang ambigu masih belum diketahui. GRV/PRV saat ini menggunakan nilai aktual yang diambil dan tidak memerlukan perkiraan ini.",
    "Titan-added stat forecast": "Prediksi stat tambahan Titan",
    "The primary is the stat with the most equivalent rolls before Titan. Each added stat uses that primary’s generated priority/fallback pool; existing random stats are excluded. Unused priority stats fill the available slots first, and fallback stats fill only the remainder. The added stat does not receive Titan growth again. The share is an observed calibration, not a proven game maximum or drop probability. Current ratings use the actual added value.": "Yang utama adalah stat dengan gulungan paling setara sebelum Titan. Setiap statistik yang ditambahkan menggunakan kumpulan prioritas/penggantian utama yang dihasilkan; statistik acak yang ada dikecualikan. Statistik prioritas yang tidak digunakan mengisi slot yang tersedia terlebih dahulu, dan statistik cadangan hanya mengisi sisanya. Statistik yang ditambahkan tidak menerima pertumbuhan Titan lagi. Bagiannya adalah kalibrasi yang diamati, bukan probabilitas maksimum atau penurunan permainan yang terbukti. Pemeringkatan saat ini menggunakan nilai tambah yang sebenarnya."
  },
  "ja": {
    "What the capture contains": "キャプチャに含まれる内容",
    "The file provides the first received profile stats, equipped items and captured progression. ATK has both a displayed base before ATK% and a native final value. HP and resistance are final values; their full percentage totals are not supplied. Missing fields remain unknown. These are snapshot values, rather than a live reading of the current game screen.": "このファイルには、最初に受け取ったプロファイル統計、装備されているアイテム、およびキャプチャされた進行状況が含まれています。 攻撃力 には、攻撃力% の前に表示されるベースとネイティブの最終値の両方があります。 HP と抵抗は最終値です。それらの完全な割合の合計は提供されません。欠落しているフィールドは不明のままです。これらは、現在のゲーム画面のライブ読み取り値ではなく、スナップショット値です。",
    "The pair inherits whole gear percentages": "デュオは装備の割合補正をすべて引き継ぐ",
    "1 is the selected element and 2 its weapon partner. g is total gear ATK%; q is total gear DMG%. Their winners are chosen independently across the equipped set. Other sources stay on their own element. The stronger element keeps its own percentage; the weaker replaces only its gear portion. A standalone item’s GRV can choose its own winners, while Build totals keep one source per percentage for every slot.": "1 は選択中の属性、2 はペアとなる武器の属性です。g は装備全体の攻撃力%、q は装備全体のDMG%を表します。g と q の最大値は、装備中の全アイテムから個別に選びます。他のボーナスは元の属性に残ります。強い方の属性は自身の割合値を維持し、弱い方は装備由来の割合分だけ置き換えます。単体アイテムのGRVでは個別に最大値を選べますが、ビルド全体では各割合につき全スロットで1つのソースだけを採用します。",
    "Pair ATK and Space Support": "デュオの攻撃力と宇宙支援",
    "B is a displayed base, including its own Space Support S. Compare the pair after removing each element’s support, then add only the selected element’s support before ATK%. A selected Enhancement Shot’s universal flat ATK is already in both effective bases and is counted once. Do not add support again after percentages. Flat ATK used by the combat table and the per-item GRV choice are separate calculations.": "B は、独自の 宇宙支援 S を含む、表示されたベースです。各要素のサポートを削除した後でペアを比較し、選択した要素のサポートのみを 攻撃力% の前に追加します。選択された 強化注射剤 のユニバーサル フラット 攻撃力 はすでに両方の有効なベースにあり、1 回カウントされます。パーセンテージの後にサポートを再度追加しないでください。戦闘テーブルで使用されるフラット 攻撃力 とアイテムごとの GRV の選択は別個の計算です。",
    "Altered combat ATK": "オルタードの戦闘攻撃力",
    "The combat model copies the strongest native element’s own final ATK, without duo inheritance, and keeps the captured or entered own Altered remainder. Native shot bonuses are inherited after that source’s percentages, once. The card’s imported displayed Altered base already contains the copy, so it is not added to that base again. Altered gear rating uses a different source selection: one gear-only source for GRV, the personal source for PRV.": "戦闘モデルは、最強のネイティブ要素自体の最終 攻撃力 をデュオ継承なしでコピーし、キャプチャまたは入力された独自の オルタード の残りを保持します。ネイティブショットボーナスは、そのソースのパーセンテージを一度継承した後に継承されます。インポートされたカードの表示 オルタード ベースには既にコピーが含まれているため、そのベースに再度追加されることはありません。 オルタード ギア レーティングでは、別のソース選択が使用されます。GRV にはギアのみのソースが 1 つ、PRV には個人ソースが使用されます。",
    "Temporary buffs at capture time": "キャプチャ時の一時バフ",
    "Recognized removable constant ATK% buffs are subtracted per element on import, including their stack count. A recognized flat or unknown-magnitude temporary ATK effect can block import. Permitted food and shots remain separate selected consumables. Unrecognized effects are not proof of a clean snapshot; use an out-of-combat capture and the source list when checking a discrepancy.": "認識された取り外し可能な定数 攻撃力% バフは、スタック数を含め、インポート時に要素ごとに減算されます。認識された平坦な効果または大きさが不明な一時的な 攻撃力 効果により、インポートがブロックされる可能性があります。許可された食料とショットは、選択された個別の消耗品のままです。認識されない効果は、クリーンなスナップショットの証拠にはなりません。不一致をチェックするときは、戦闘外のキャプチャとソース リストを使用します。",
    "Account relic passives": "アカウント遺物のパッシブ効果",
    "Captured account relic passives apply even when those relics are not equipped. Their DMG% and RES% are distinct per-element values. Damage-received reduction is not automatically a resistance-stat multiplier: the capture’s attribute mapping determines which pool a passive affects. Relic A4 DMG% is included once in its own element’s combat DMG% and also shown in the relic summary. Relic RES% joins the known resistance multiplier once; changing the two equipped relics does not reset account passives.": "キャプチャされたアカウントのレリック パッシブは、それらのレリックが装備されていない場合でも適用されます。 DMG% と 耐性% は要素ごとに異なる値です。被ダメージの軽減は自動的に耐性ステータスの乗数になるわけではありません。キャプチャーの属性マッピングによってパッシブがどのプールに影響するかが決まります。レリック A4 DMG% は、独自の要素の戦闘 DMG% に 1 回含まれ、レリックの概要にも表示されます。レリック 耐性% は既知の抵抗乗数に 1 回追加されます。装備されている 2 つのレリックを変更しても、アカウントのパッシブはリセットされません。",
    "Unknown data and rounding": "不明なデータと丸め処理",
    "Calculations retain fractional values; separate displayed rows can differ by a unit after rounding. A blank required base is unknown, rather than zero. Unknown catalog items remain empty and are listed; catalog fitting is not verification of their effects. The badge ≈ denotes a modeled estimate. Up displays the normalized upgrade level stored in the file: the exporter has already converted the raw profile suffix by adding one. The card does not add one again. This model has no separate Up multiplier for weapon stat endpoints or weapon CS.": "計算では小数値が保持されます。表示される個別の行は、四捨五入後の単位によって異なる場合があります。空白の必須塩基はゼロではなく不明です。不明なカタログ項目は空のままでリストされます。カタログフィッティングは効果を検証するものではありません。バッジ ≈ はモデル化された推定値を示します。 Up は、ファイルに保存されている正規化されたアップグレード レベルを表示します。エクスポータは、生のプロファイル サフィックスを追加してすでに変換しています。カードが再度追加されることはありません。このモデルには、武器統計エンドポイントまたは武器 CS 用の個別の Up 乗数がありません。",
    "Universal ATK": "汎用攻撃力",
    "Universal ATK is inferred, not a separately captured stat. The remainder includes universal gear ATK and external sources. The card shows it only when all four native bases are available and their remainders agree within one ATK. Otherwise it shows —. Its tooltip separates universal gear, the selected shot and remaining sources; it does not apply ATK% to this base.": "ユニバーサル 攻撃力 は、個別に取得された統計ではなく、推定されます。残りには、ユニバーサル ギア 攻撃力 と外部ソースが含まれます。カードには、4 つのネイティブ ベースがすべて利用可能で、それらの残りが 1 つの 攻撃力 内で一致する場合にのみ表示されます。それ以外の場合は—と表示されます。そのツールチップは、ユニバーサルギア、選択したショット、残りのソースを分離します。このベースには 攻撃力% は適用されません。",
    "HP and HP%": "HPとHP%",
    "h is full HP% as a fraction. Without an explicitly entered total, only equipped gear HP% is known. The tooltip separates the pre-percentage pool into other sources, gear and the shot, then shows the percentage gain and final HP. Unknown external HP% or another multiplier makes the restored base an estimate. A missing HP snapshot stays missing.": "h は分数として完全 HP% です。合計を明示的に入力しないと、装備されているギア HP% のみがわかります。ツールチップは、プレパーセンテージプールを他のソース、ギア、ショットに分割し、パーセンテージゲインと最終的な HP を表示します。不明な外部 HP% または別の乗数により、復元されたベースが推定値となります。欠落している HP スナップショットは欠落したままになります。",
    "Crit rating and chance": "会心値と会心率",
    "The rating tooltip separates other sources, equipped gear and the shot. The level denominator comes from the game curve for the selected enemy level. The panel shows the uncapped sum; expected-output and personal rating calculations cap useful chance at 100%. Crit DMG is a bonus: the expected critical factor is 1 + c_rating × Crit DMG, rather than chance multiplied by full critical damage.": "評価ツールチップは、他のソース、装備されているギア、ショットを分離します。レベルの分母は、選択した敵レベルのゲーム カーブから取得されます。パネルには上限なしの合計が表示されます。期待される生産量と個人の評価の計算では、有用な可能性は 100% に制限されます。 会心DMG はボーナスです。期待されるクリティカル係数は、完全なクリティカル ダメージに確率を乗算するのではなく、1 + c_rated × 会心DMG です。",
    "Resistance and damage reduction": "耐性とダメージ軽減",
    "r is full RES%, or the known source sum when a full value is unavailable. Universal flat RES contributes to every element; elemental RES contributes only to its own. The shot is added before RES%. K uses character level, while the Crit curve uses enemy level. This reduction is the resistance component, not the product of every damage-reduction effect in combat. Tank EHP = HP × (1 + RES_effective / K).": "r は完全 耐性%、または完全な値が利用できない場合の既知のソース合計です。ユニバーサル フラット 耐性 はすべての要素に寄与します。要素 耐性 は、それ自体にのみ貢献します。ショットは 耐性% の前に追加されます。 K はキャラクター レベルを使用しますが、会心 カーブは敵のレベルを使用します。この減少は抵抗力の要素であり、戦闘中のあらゆるダメージ軽減効果の産物ではありません。タンク EHP = HP × (1 + 耐性_効果 / K)。",
    "The combat DMG% column": "戦闘DMG%の列",
    "For captures, this column is derived from the loadout; no full DMG% total is captured. Only generated recognized contributions enter it. Relic A4 is included once for its own element; duo inheritance replaces only gear DMG%, leaving relic and other non-gear bonuses on their own element. Alternative conditional Space Support modes do not stack: the strongest applicable mode per element is used. Imported Altered DMG% is zero in this model. This column is not a complete damage or rotation simulator.": "キャプチャの場合、この列はロードアウトから派生します。 DMG% の完全な合計は取得されません。生成された認識された貢献のみがそこに入ります。 Relic A4 は、独自の要素として 1 回インクルードされます。デュオの継承はギア DMG% のみを置き換え、レリックとその他のギア以外のボーナスは独自の要素に残ります。代替の条件付き 宇宙支援 モードはスタックされません。要素ごとに最も適用可能なモードが使用されます。インポートされた オルタード DMG% は、このモデルではゼロです。このコラムは完全なダメージや回転のシミュレーターではありません。",
    "Enhancement Shot stat gain": "強化注射剤によるステータス上昇",
    "For weapons, the target is the catalog’s maximum weapon level at the weapon’s actual stars. For matrices, it is the maximum level and maximum base-stat advancement. The selected shot adds these four flat gains to the first received stats. HP and RES gains are multiplied by their percentages; native ATK gains are multiplied by native ATK%; Altered inherits once. It does not change captured stars, Up or matrix set-effect ranks. Recalculation replaces the previous applied gain and does not add it again.": "武器の場合、ターゲットは武器の実際の星におけるカタログの最大武器レベルです。マトリックスの場合、それは最大レベルと最大の基本ステータスの進歩です。選択したショットは、最初に受け取った統計にこれら 4 つのフラット ゲインを追加します。 HP および 耐性 のゲインにはパーセンテージが乗算されます。ネイティブ 攻撃力 ゲインはネイティブ 攻撃力% で乗算されます。 オルタード は 1 回継承します。捕捉された星、Up、またはマトリックス セット効果のランクは変更されません。再計算では、以前に適用されたゲインが置き換えられ、再度追加されることはありません。",
    "Selected ATK% consumables": "選択中の攻撃力%消耗品",
    "The model applies only generated, recognized unconditional ATK% bonuses of selected consumables. A universal bonus targets the native elements declared by the catalog; it is not applied to Altered a second time. Unknown, conditional and other consumable effects are not inferred from their names. The expiry time describes the captured buff; the card is a saved configuration and does not automatically clear the selected consumable when that clock expires.": "このモデルは、選択された消耗品の生成され認識された無条件 攻撃力% ボーナスのみを適用します。ユニバーサル ボーナスは、カタログによって宣言されたネイティブ要素を対象としています。 オルタード には再度適用されません。未知の条件付き効果やその他の消費可能な効果は、名前から推測されません。有効期限は、獲得されたバフを表します。カードは保存された構成であり、クロックの期限が切れても、選択した消耗品は自動的にクリアされません。",
    "Current CS and Apex CS": "現在CSと最高CS",
    "Current CS starts from the captured profile score or the manual input. The selected Enhancement Shot adds its modeled flat-stat CS delta once; when a precise captured CS is available, rounding starts from that value. Apex CS remains the recorded historical maximum with its recorded time. The model does not replace current CS with the sum of gear, weapons, matrices and other system estimates, and it does not infer a new complete CS after every manual loadout edit or recompute every other consumable’s CS impact. The displayed integer header difference can differ from the rounded shot subtotal by one because the original captured CS has a fraction.": "現在の CS は、キャプチャされたプロファイル スコアまたは手動入力から始まります。選択された 強化注射剤 は、モデル化されたフラット統計 CS デルタを 1 回追加します。正確にキャプチャされた CS が利用可能な場合、その値から丸めが開始されます。 最高CS は、記録された時間とともに記録された過去最大値のままです。このモデルは、現在の CS をギア、武器、マトリックス、その他のシステム推定値の合計に置き換えることはありません。また、手動ロードアウトの編集後、または他のすべての消耗品の CS の影響を再計算した後に、新しい完全な CS を推測することもありません。元のキャプチャされた CS には小数点があるため、表示される整数のヘッダーの差は、四捨五入されたショットの小計と 1 だけ異なる場合があります。",
    "Weapon CS": "武器CS",
    "The card’s weapon source label scores the weapon alone. Level gains and star coefficients come from generated game tables. Only the current star’s StarSkillScore is added, not the sum of all earlier stars. Matrix scores and their set AddScore are separate. The reconstruction matches documented server-score samples within floating-point differences; that does not establish every weapon, upgrade field or native rounding case.": "カードの武器ソース ラベルは武器のみをスコアします。レベルゲインとスター係数は、生成されたゲームテーブルから取得されます。以前のすべてのスターの合計ではなく、現在のスターの StarSkillScore のみが追加されます。マトリックス スコアとそのセット AddScore は別のものです。再構築では、浮動小数点差内で文書化されたサーバー スコア サンプルと一致します。すべての武器、アップグレード フィールド、またはネイティブの丸めケースを確立するわけではありません。",
    "Matrices and set CS": "マトリクスとセットのCS",
    "Each matrix uses its own slot profile, level and star multiplier. Use fractional stats for the score; the displayed matrix stat has its own float32 truncation. Set AddScore is counted once per reached piece threshold on one weapon. The model ranks the set by the threshold’s Nth strongest matrix; mixed-star selection has not been separately verified in every case. Enhancement Shot changes base-stat endpoints, not these set ranks.": "各マトリックスは、独自のスロット プロファイル、レベル、スター乗数を使用します。スコアには小数統計を使用します。表示される行列統計には、独自の float32 切り捨てがあります。セット AddScore は、1 つの武器のピースしきい値に達するごとに 1 回カウントされます。モデルは、しきい値の N 番目に強い行列によってセットをランク付けします。混合スターの選択は、すべてのケースで個別に検証されたわけではありません。 強化注射剤 は、これらの設定されたランクではなく、基本統計エンドポイントを変更します。",
    "Titan property: effect and CS": "タイタン特性：効果とCS",
    "The effect tooltip evaluates the game’s effect curve at the summed level. CS evaluates the separate display curve at each item’s own level and then sums its CS. A nonlinear curve means those two orders are not interchangeable. At level zero the effect is absent; between curve keys the model interpolates linearly and outside the keys it uses the endpoint. Gear CS already includes this property: do not add the Titan CS summary to gear CS again.": "エフェクト ツールチップは、ゲームのエフェクト カーブを合計レベルで評価します。 CS は、各項目独自のレベルで個別の表示曲線を評価し、その CS を合計します。非線形曲線は、これら 2 つの次数が互換性がないことを意味します。レベル 0 では効果はありません。カーブ キー間ではモデルは線形補間を行い、キーの外側ではエンドポイントを使用します。ギア CS にはこのプロパティが既に含まれています。タイタン CS の概要をギア CS に再度追加しないでください。",
    "Supercomputing, Space Support and suppressor CS": "スーパーコンピューティング、宇宙支援、サプレッサーのCS",
    "Raw attributes of the current level are weighted with the game attribute weights. Content modules give twice the DMG of a base DMG module and are scored with the same DMG% weight; the game weight of their final-DMG attribute is zero, so this is a model assumption. Supercomputing ATK% / RES%, healing and Shatter are not scored: weighting ATK% / RES% by the build’s bases would exceed the whole unexplained remainder of captured total CS. The game does not report a separate score for these systems, so each value is an estimate shown on hover over current CS; it is not added to the current CS.": "現在のレベルの生の属性は、ゲーム属性の重みで重み付けされます。コンテンツ モジュールは、基本 DMG モジュールの 2 倍の DMG を与え、同じ DMG% の重みでスコア付けされます。 Final-DMG 属性のゲームの重みはゼロであるため、これはモデルの仮定です。スーパーコンピューティング 攻撃力% / 耐性%、治癒および シャター はスコアリングされません。ビルドのベースによる 攻撃力% / 耐性% の重み付けは、説明されていない全体の値を超えます。キャプチャされた合計 CS の残り。ゲームはこれらのシステムの個別のスコアを報告しないため、各値は現在の CS にカーソルを合わせると表示される推定値です。現在の CS には追加されません。",
    "Enhancement Shot CS": "強化注射剤のCS",
    "This is the weighted sum of the shot’s flat weapon/matrix gains. Universal ATK and RES count once, without combat ATK%/HP%/RES% and without matrix set AddScore or a new weapon StarSkillScore. The current profile model adds this subtotal once. It matches the documented before/after sample; it is not a universal proof of every indirect native CS change. Hovering current CS reveals this gain beside the shot, without a permanent caption.": "これは、ショットのフラット ウェポン/マトリックス ゲインの加重合計です。ユニバーサル 攻撃力 および 耐性 は 1 回カウントされます。戦闘 攻撃力%/HP%/耐性% およびマトリックス セット AddScore なし、または新しい武器 StarSkillScore。現在のプロファイル モデルは、この小計を 1 回追加します。これは、文書化された前後のサンプルと一致します。これは、間接的なネイティブ CS のすべての変更を普遍的に証明するものではありません。現在の CS をホバリングすると、永続的なキャプションなしでショットの横にこのゲインが表示されます。",
    "Roll count and quality": "ロール数と品質",
    "Roll inference uses values before Titan, not current augmented values. The number of rolls must fit every row and the item’s total stars. If several splits fit, the card selects a likelihood estimate and marks disputed counts with ~; missing or impossible data gives ?. The likelihood model approximates sums of uniform rolls and is not a confirmed game drop distribution. Quality excludes initial values and is undefined for zero rolls or fixed-size rolls.": "ロール数は現在の強化後の値ではなく、タイタン適用前の値から推定します。各行の範囲とアイテムの星数合計に合う必要があります。複数の配分が成立する場合、カードは尤度の推定値を採用し、判定が確定しない個数に~を付けます。データが不足または不可能な場合は?を表示します。この尤度モデルは一様なロール値の合計を近似するもので、ゲーム内の実際のドロップ分布は確認されていません。品質は初期値を除いて計算し、ロール数が0の場合や値幅が固定の場合は定義されません。",
    "Titan maximum and pull-up": "タイタン最大値とロールの引き上げ",
    "The row’s Titan maximum applies generated growth to its actual pre-Titan value; it does not replace its earlier rolls with perfect rolls. Elemental ATK, ATK% and DMG% have separate pull-up families among the native elements. Pull-up can raise a row’s maximum but cannot reduce its independent growth, including when original values are equal. Their ranks use generated factors; an unconfirmed rank leaves the projection unavailable. Tied primary stats are evaluated separately, and an ambiguous ceiling remains unknown. Current GRV/PRV uses actual captured values and does not require this forecast.": "行の タイタン の最大値は、生成された増加分を タイタン より前の実際の値に適用します。以前のロールを完全なロールに置き換えることはありません。要素 攻撃力、攻撃力%、および DMG% には、ネイティブ要素間で個別のプルアップ ファミリがあります。プルアップは行の最大値を上げることができますが、元の値が等しい場合を含め、行の独立した増加を減らすことはできません。彼らのランクは生成された要素を使用します。ランクが未確認の場合、投影は利用できなくなります。同点の主要統計は個別に評価され、曖昧な上限は不明のままです。現在の GRV/PRV は実際に取得された値を使用するため、この予測は必要ありません。",
    "Titan-added stat forecast": "タイタン追加ステータスの予測",
    "The primary is the stat with the most equivalent rolls before Titan. Each added stat uses that primary’s generated priority/fallback pool; existing random stats are excluded. Unused priority stats fill the available slots first, and fallback stats fill only the remainder. The added stat does not receive Titan growth again. The share is an observed calibration, not a proven game maximum or drop probability. Current ratings use the actual added value.": "プライマリは、タイタン より前の最も同等のロールを持つ統計です。追加された各統計は、そのプライマリで生成された優先順位/フォールバック プールを使用します。既存のランダム統計は除外されます。未使用の優先統計が最初に使用可能なスロットを埋め、フォールバック統計が残りのみを埋めます。追加された統計は タイタン の増加を再び受け取りません。シェアは観察された調整値であり、証明されたゲームの最大値やドロップ確率ではありません。現在の定格は実際の付加価値を使用しています。"
  },
  "ko": {
    "What the capture contains": "캡처에 포함된 정보",
    "The file provides the first received profile stats, equipped items and captured progression. ATK has both a displayed base before ATK% and a native final value. HP and resistance are final values; their full percentage totals are not supplied. Missing fields remain unknown. These are snapshot values, rather than a live reading of the current game screen.": "파일은 처음 수신된 프로필 통계, 장착된 아이템 및 캡처된 진행 상황을 제공합니다. 공격력에는 공격력% 앞에 표시된 기준과 기본 최종 값이 모두 있습니다. HP 및 저항은 최종 값입니다. 전체 백분율 합계는 제공되지 않습니다. 누락된 필드는 알 수 없는 상태로 남아 있습니다. 이는 현재 게임 화면을 실시간으로 읽는 것이 아니라 스냅샷 값입니다.",
    "The pair inherits whole gear percentages": "듀오는 장비의 모든 비율을 계승합니다",
    "1 is the selected element and 2 its weapon partner. g is total gear ATK%; q is total gear DMG%. Their winners are chosen independently across the equipped set. Other sources stay on their own element. The stronger element keeps its own percentage; the weaker replaces only its gear portion. A standalone item’s GRV can choose its own winners, while Build totals keep one source per percentage for every slot.": "1은 선택한 속성이고 2는 짝이 되는 무기의 속성입니다. g는 장비 전체의 공격력%, q는 장비 전체의 DMG%입니다. g와 q의 최댓값은 착용 중인 모든 장비를 기준으로 각각 따로 선택합니다. 다른 보너스는 원래 속성에 남습니다. 더 강한 속성은 자신의 비율을 유지하고, 약한 속성은 장비에서 얻은 부분만 대체합니다. 개별 아이템의 GRV는 자체 최댓값을 선택할 수 있지만, 빌드 합계는 모든 슬롯을 통틀어 각 비율마다 하나의 출처만 사용합니다.",
    "Pair ATK and Space Support": "듀오 공격력과 우주 지원",
    "B is a displayed base, including its own Space Support S. Compare the pair after removing each element’s support, then add only the selected element’s support before ATK%. A selected Enhancement Shot’s universal flat ATK is already in both effective bases and is counted once. Do not add support again after percentages. Flat ATK used by the combat table and the per-item GRV choice are separate calculations.": "B는 자체 우주 지원 S를 포함하여 표시된 베이스입니다. 각 요소의 지지대를 제거한 후 쌍을 비교한 다음 공격력% 앞에 선택한 요소의 지지대만 추가합니다. 선택한 강화 주사제의 유니버설 플랫 공격력는 이미 두 유효 베이스에 모두 있으며 한 번 계산됩니다. 백분율 뒤에 지원을 다시 추가하지 마십시오. 전투 테이블에서 사용되는 플랫 공격력와 항목별 GRV 선택은 별도의 계산입니다.",
    "Altered combat ATK": "변이 전투 공격력",
    "The combat model copies the strongest native element’s own final ATK, without duo inheritance, and keeps the captured or entered own Altered remainder. Native shot bonuses are inherited after that source’s percentages, once. The card’s imported displayed Altered base already contains the copy, so it is not added to that base again. Altered gear rating uses a different source selection: one gear-only source for GRV, the personal source for PRV.": "전투 모델은 듀오 상속 없이 가장 강력한 기본 요소의 자체 최종 공격력를 복사하고 캡처하거나 입력한 자체 변이 나머지를 유지합니다. 네이티브 샷 보너스는 해당 소스의 백분율 이후에 한 번 상속됩니다. 가져온 카드의 표시된 변이 베이스에는 이미 복사본이 포함되어 있으므로 해당 베이스에 다시 추가되지 않습니다. 변이 기어 등급은 다른 소스 선택을 사용합니다. 즉, GRV에 대한 하나의 기어 전용 소스, PRV에 대한 개인 소스입니다.",
    "Temporary buffs at capture time": "캡처 시점의 임시 버프",
    "Recognized removable constant ATK% buffs are subtracted per element on import, including their stack count. A recognized flat or unknown-magnitude temporary ATK effect can block import. Permitted food and shots remain separate selected consumables. Unrecognized effects are not proof of a clean snapshot; use an out-of-combat capture and the source list when checking a discrepancy.": "인식된 제거 가능한 상수 공격력% 버프는 스택 수를 포함하여 가져올 때 요소당 차감됩니다. 인식된 평면 또는 크기를 알 수 없는 임시 공격력 효과로 인해 가져오기가 차단될 수 있습니다. 허용된 음식과 주사는 별도의 선택된 소모품으로 유지됩니다. 인식할 수 없는 효과는 깨끗한 스냅샷의 증거가 아닙니다. 불일치를 확인할 때 전투 외 캡처와 소스 목록을 사용하십시오.",
    "Account relic passives": "계정 유물 패시브",
    "Captured account relic passives apply even when those relics are not equipped. Their DMG% and RES% are distinct per-element values. Damage-received reduction is not automatically a resistance-stat multiplier: the capture’s attribute mapping determines which pool a passive affects. Relic A4 DMG% is included once in its own element’s combat DMG% and also shown in the relic summary. Relic RES% joins the known resistance multiplier once; changing the two equipped relics does not reset account passives.": "포획된 계정 유물 패시브는 해당 유물을 장착하지 않은 경우에도 적용됩니다. DMG% 및 저항%는 고유한 요소별 값입니다. 받는 피해 감소는 자동으로 저항 능력치 배수가 아닙니다. 캡처의 속성 매핑에 따라 패시브가 영향을 미치는 풀이 결정됩니다. 유물 A4 DMG%는 자체 요소의 전투 DMG%에 한 번 포함되며 유물 요약에도 표시됩니다. 유물 저항%는 알려진 저항 배수에 한 번 합류합니다. 장착된 두 개의 유물을 변경해도 계정 패시브가 재설정되지 않습니다.",
    "Unknown data and rounding": "알 수 없는 데이터와 반올림",
    "Calculations retain fractional values; separate displayed rows can differ by a unit after rounding. A blank required base is unknown, rather than zero. Unknown catalog items remain empty and are listed; catalog fitting is not verification of their effects. The badge ≈ denotes a modeled estimate. Up displays the normalized upgrade level stored in the file: the exporter has already converted the raw profile suffix by adding one. The card does not add one again. This model has no separate Up multiplier for weapon stat endpoints or weapon CS.": "계산은 분수 값을 유지합니다. 별도의 표시 행은 반올림 후 단위별로 다를 수 있습니다. 0이 아닌 빈 필수 베이스를 알 수 없습니다. 알 수 없는 카탈로그 항목은 비어 있고 나열됩니다. 카탈로그 피팅은 그 효과를 검증하는 것이 아닙니다. 배지 ≒은 모델링된 추정치를 나타냅니다. Up는 파일에 저장된 정규화된 업그레이드 수준을 표시합니다. 내보내기는 이미 원시 프로필 접미사를 추가하여 변환했습니다. 카드는 다시 추가되지 않습니다. 이 모델에는 무기 통계 끝점 또는 무기 CS에 대한 별도의 Up 승수가 없습니다.",
    "Universal ATK": "범용 공격력",
    "Universal ATK is inferred, not a separately captured stat. The remainder includes universal gear ATK and external sources. The card shows it only when all four native bases are available and their remainders agree within one ATK. Otherwise it shows —. Its tooltip separates universal gear, the selected shot and remaining sources; it does not apply ATK% to this base.": "별도로 캡처된 통계가 아닌 범용 공격력가 추론됩니다. 나머지에는 범용 기어 공격력 및 외부 소스가 포함됩니다. 카드에는 4개의 기본 기지가 모두 사용 가능하고 나머지가 하나의 공격력 내에서 일치하는 경우에만 표시됩니다. 그렇지 않으면 —가 표시됩니다. 툴팁은 범용 장비, 선택한 샷 및 나머지 소스를 구분합니다. 이 베이스에는 공격력%가 적용되지 않습니다.",
    "HP and HP%": "HP와 HP%",
    "h is full HP% as a fraction. Without an explicitly entered total, only equipped gear HP% is known. The tooltip separates the pre-percentage pool into other sources, gear and the shot, then shows the percentage gain and final HP. Unknown external HP% or another multiplier makes the restored base an estimate. A missing HP snapshot stays missing.": "h는 분수로 가득 찬 HP%입니다. 총계를 명시적으로 입력하지 않으면 장착된 장비 HP%만 알 수 있습니다. 툴팁은 사전 백분율 풀을 다른 소스, 장비 및 샷으로 분리한 다음 백분율 이득과 최종 HP를 표시합니다. 알 수 없는 외부 HP% 또는 다른 승수는 복원된 베이스를 추정치로 만듭니다. 누락된 HP 스냅샷은 누락된 상태로 유지됩니다.",
    "Crit rating and chance": "치명타 수치와 치명타 확률",
    "The rating tooltip separates other sources, equipped gear and the shot. The level denominator comes from the game curve for the selected enemy level. The panel shows the uncapped sum; expected-output and personal rating calculations cap useful chance at 100%. Crit DMG is a bonus: the expected critical factor is 1 + c_rating × Crit DMG, rather than chance multiplied by full critical damage.": "등급 툴팁은 다른 소스, 장착된 장비 및 샷을 구분합니다. 레벨 분모는 선택한 적 레벨의 게임 곡선에서 나옵니다. 패널에는 제한되지 않은 합계가 표시됩니다. 예상 출력 및 개인 평가 계산은 유용한 기회를 100%로 제한합니다. 치명타 DMG는 보너스입니다. 예상되는 치명타 계수는 전체 치명타 피해에 우연을 곱하는 것이 아니라 1 + c_rated × 치명타 DMG입니다.",
    "Resistance and damage reduction": "저항과 피해 감소",
    "r is full RES%, or the known source sum when a full value is unavailable. Universal flat RES contributes to every element; elemental RES contributes only to its own. The shot is added before RES%. K uses character level, while the Crit curve uses enemy level. This reduction is the resistance component, not the product of every damage-reduction effect in combat. Tank EHP = HP × (1 + RES_effective / K).": "r은 전체 저항%이거나 전체 값을 사용할 수 없는 경우 알려진 소스 합계입니다. 유니버설 플랫 저항는 모든 요소에 기여합니다. elemental 저항는 자체에만 기여합니다. 샷은 저항% 앞에 추가됩니다. K는 캐릭터 레벨을 사용하고 치명타 곡선은 적 레벨을 사용합니다. 이 감소는 저항 요소이지 전투 중 모든 피해 감소 효과의 산물은 아닙니다. 탱크 EHP = HP × (1 + 저항_유효 / K).",
    "The combat DMG% column": "전투 DMG% 열",
    "For captures, this column is derived from the loadout; no full DMG% total is captured. Only generated recognized contributions enter it. Relic A4 is included once for its own element; duo inheritance replaces only gear DMG%, leaving relic and other non-gear bonuses on their own element. Alternative conditional Space Support modes do not stack: the strongest applicable mode per element is used. Imported Altered DMG% is zero in this model. This column is not a complete damage or rotation simulator.": "캡처의 경우 이 열은 로드아웃에서 파생됩니다. 전체 DMG% 합계가 캡처되지 않습니다. 생성된 인정된 기여만 입력합니다. Relic A4는 자체 요소에 대해 한 번 포함됩니다. 듀오 상속은 장비 DMG%만 대체하며 유물 및 기타 장비가 아닌 보너스는 자체 요소에 남겨 둡니다. 대체 조건부 우주 지원 모드는 스택되지 않습니다. 요소당 가장 강력한 적용 가능한 모드가 사용됩니다. 가져온 변이 DMG%는 이 모델에서 0입니다. 이 칼럼은 완전한 손상이나 회전 시뮬레이터가 아닙니다.",
    "Enhancement Shot stat gain": "강화 주사제 능력치 증가",
    "For weapons, the target is the catalog’s maximum weapon level at the weapon’s actual stars. For matrices, it is the maximum level and maximum base-stat advancement. The selected shot adds these four flat gains to the first received stats. HP and RES gains are multiplied by their percentages; native ATK gains are multiplied by native ATK%; Altered inherits once. It does not change captured stars, Up or matrix set-effect ranks. Recalculation replaces the previous applied gain and does not add it again.": "무기의 경우 대상은 무기의 실제 별에서 카탈로그의 최대 무기 레벨입니다. 매트릭스의 경우 최대 레벨 및 최대 기본 능력치 향상입니다. 선택한 샷은 처음 받은 통계에 이 4가지 균일 이득을 추가합니다. HP 및 저항 이득에 해당 백분율을 곱합니다. 네이티브 공격력 이득에 네이티브 공격력%를 곱합니다. 변이는 한 번 상속됩니다. 캡처된 별, Up 또는 매트릭스 세트 효과 순위는 변경되지 않습니다. 재계산은 이전에 적용된 게인을 대체하며 다시 추가하지 않습니다.",
    "Selected ATK% consumables": "선택한 공격력% 소모품",
    "The model applies only generated, recognized unconditional ATK% bonuses of selected consumables. A universal bonus targets the native elements declared by the catalog; it is not applied to Altered a second time. Unknown, conditional and other consumable effects are not inferred from their names. The expiry time describes the captured buff; the card is a saved configuration and does not automatically clear the selected consumable when that clock expires.": "이 모델은 선택된 소모품의 생성되고 인식된 무조건 공격력% 보너스만 적용합니다. 범용 보너스는 카탈로그에 선언된 기본 요소를 대상으로 합니다. 변이에는 두 번째로 적용되지 않습니다. 알 수 없음, 조건부 효과 및 기타 소모성 효과는 이름에서 추론되지 않습니다. 만료 시간은 캡처된 버프를 설명합니다. 카드는 저장된 구성이며 해당 시계가 만료될 때 선택한 소모품을 자동으로 지우지 않습니다.",
    "Current CS and Apex CS": "현재 CS와 최고 CS",
    "Current CS starts from the captured profile score or the manual input. The selected Enhancement Shot adds its modeled flat-stat CS delta once; when a precise captured CS is available, rounding starts from that value. Apex CS remains the recorded historical maximum with its recorded time. The model does not replace current CS with the sum of gear, weapons, matrices and other system estimates, and it does not infer a new complete CS after every manual loadout edit or recompute every other consumable’s CS impact. The displayed integer header difference can differ from the rounded shot subtotal by one because the original captured CS has a fraction.": "현재 CS는 캡처된 프로필 점수 또는 수동 입력에서 시작됩니다. 선택한 강화 주사제는 모델링된 플랫 통계 CS 델타를 한 번 추가합니다. 정확하게 캡처된 CS를 사용할 수 있는 경우 해당 값에서 반올림이 시작됩니다. 최고 CS는 기록된 시간과 함께 기록된 최대 기록으로 유지됩니다. 모델은 현재 CS를 장비, 무기, 매트릭스 및 기타 시스템 추정치의 합으로 대체하지 않으며 모든 수동 로드아웃 편집 후 새로운 완전한 CS를 추론하거나 다른 모든 소모품의 CS 영향을 다시 계산하지 않습니다. 표시된 정수 헤더 차이는 캡처된 원본 CS에 분수가 있기 때문에 반올림된 샷 소계와 1만큼 다를 수 있습니다.",
    "Weapon CS": "무기 CS",
    "The card’s weapon source label scores the weapon alone. Level gains and star coefficients come from generated game tables. Only the current star’s StarSkillScore is added, not the sum of all earlier stars. Matrix scores and their set AddScore are separate. The reconstruction matches documented server-score samples within floating-point differences; that does not establish every weapon, upgrade field or native rounding case.": "카드의 무기 소스 라벨은 무기에만 점수를 매깁니다. 레벨 이득과 별 계수는 생성된 게임 테이블에서 나옵니다. 모든 이전 별의 합이 아닌 현재 별의 StarSkillScore만 추가됩니다. 매트릭스 점수와 해당 세트 AddScore는 별개입니다. 재구성은 부동 소수점 차이 내에서 문서화된 서버 점수 샘플과 일치합니다. 모든 무기, 업그레이드 필드 또는 기본 반올림 사례를 설정하지는 않습니다.",
    "Matrices and set CS": "매트릭스 및 세트 CS",
    "Each matrix uses its own slot profile, level and star multiplier. Use fractional stats for the score; the displayed matrix stat has its own float32 truncation. Set AddScore is counted once per reached piece threshold on one weapon. The model ranks the set by the threshold’s Nth strongest matrix; mixed-star selection has not been separately verified in every case. Enhancement Shot changes base-stat endpoints, not these set ranks.": "각 매트릭스는 자체 슬롯 프로필, 레벨 및 별 승수를 사용합니다. 점수에 대해 분수 통계를 사용하십시오. 표시된 매트릭스 통계에는 자체 float32 잘림이 있습니다. 세트 AddScore는 하나의 무기에서 도달한 조각 임계값당 한 번씩 계산됩니다. 모델은 임계값의 N번째로 강한 행렬을 기준으로 집합의 순위를 매깁니다. 혼합성 선택은 모든 경우에 대해 별도로 검증되지 않았습니다. 강화 주사제는 설정된 순위가 아닌 기본 통계 끝점을 변경합니다.",
    "Titan property: effect and CS": "타이탄 능력치: 효과와 CS",
    "The effect tooltip evaluates the game’s effect curve at the summed level. CS evaluates the separate display curve at each item’s own level and then sums its CS. A nonlinear curve means those two orders are not interchangeable. At level zero the effect is absent; between curve keys the model interpolates linearly and outside the keys it uses the endpoint. Gear CS already includes this property: do not add the Titan CS summary to gear CS again.": "효과 도구 설명은 합산된 수준에서 게임의 효과 곡선을 평가합니다. CS는 각 항목의 자체 수준에서 별도의 표시 곡선을 평가한 다음 해당 CS의 합계를 냅니다. 비선형 곡선은 두 순서가 상호 교환 가능하지 않음을 의미합니다. 레벨 0에서는 효과가 없습니다. 곡선 키 사이에서 모델은 선형으로 보간하고 키 외부에서는 끝점을 사용합니다. 장비 CS에는 이미 이 속성이 포함되어 있습니다. 타이탄 CS 요약을 gear CS에 다시 추가하지 마세요.",
    "Supercomputing, Space Support and suppressor CS": "슈퍼컴퓨팅, 우주 지원, 억제기 CS",
    "Raw attributes of the current level are weighted with the game attribute weights. Content modules give twice the DMG of a base DMG module and are scored with the same DMG% weight; the game weight of their final-DMG attribute is zero, so this is a model assumption. Supercomputing ATK% / RES%, healing and Shatter are not scored: weighting ATK% / RES% by the build’s bases would exceed the whole unexplained remainder of captured total CS. The game does not report a separate score for these systems, so each value is an estimate shown on hover over current CS; it is not added to the current CS.": "현재 레벨의 원시 속성에는 게임 속성 가중치가 적용됩니다. 콘텐츠 모듈은 기본 DMG 모듈의 DMG의 두 배를 제공하며 동일한 DMG% 가중치로 점수가 매겨집니다. 최종 DMG 속성의 게임 가중치는 0이므로 이는 모델 가정입니다. 슈퍼컴퓨팅 공격력% / 저항%, 치유 및 파쇄는 점수가 매겨지지 않습니다. 빌드 기반의 공격력% / 저항% 가중치는 전체를 초과합니다. 캡처된 총 CS의 설명되지 않은 나머지. 게임은 이러한 시스템에 대해 별도의 점수를 보고하지 않으므로 각 값은 현재 CS 위로 마우스를 가져가면 표시되는 추정치입니다. 현재 CS에 추가되지 않습니다.",
    "Enhancement Shot CS": "강화 주사제 CS",
    "This is the weighted sum of the shot’s flat weapon/matrix gains. Universal ATK and RES count once, without combat ATK%/HP%/RES% and without matrix set AddScore or a new weapon StarSkillScore. The current profile model adds this subtotal once. It matches the documented before/after sample; it is not a universal proof of every indirect native CS change. Hovering current CS reveals this gain beside the shot, without a permanent caption.": "이는 사격의 균일한 무기/매트릭스 이득의 가중치 합계입니다. 범용 공격력 및 저항는 전투 없이 한 번 계산됩니다. 공격력%/HP%/저항% 및 매트릭스 세트 없이 AddScore 또는 새로운 무기 StarSkillScore. 현재 프로필 모델은 이 소계를 한 번 추가합니다. 이는 문서화된 이전/이후 샘플과 일치합니다. 모든 간접 기본 CS 변경에 대한 보편적인 증거는 아닙니다. 현재 CS를 가리키면 영구 캡션 없이 샷 옆에 이 이득이 표시됩니다.",
    "Roll count and quality": "롤 횟수와 품질",
    "Roll inference uses values before Titan, not current augmented values. The number of rolls must fit every row and the item’s total stars. If several splits fit, the card selects a likelihood estimate and marks disputed counts with ~; missing or impossible data gives ?. The likelihood model approximates sums of uniform rolls and is not a confirmed game drop distribution. Quality excludes initial values and is undefined for zero rolls or fixed-size rolls.": "롤 수는 현재 증폭된 값이 아니라 타이탄 적용 전 값으로 추정합니다. 각 능력치 행과 아이템의 총 별 수에 맞아야 합니다. 가능한 분배가 여러 개면 카드가 가능도 추정치를 선택하고 불확실한 개수에 ~를 표시하며, 데이터가 없거나 성립하지 않으면 ?를 표시합니다. 이 가능도 모델은 균등한 롤 값의 합을 근사하며, 실제 게임의 드롭 분포로 확인된 값은 아닙니다. 품질은 초기값을 제외하며 롤이 0개이거나 롤 값이 고정된 경우에는 정의되지 않습니다.",
    "Titan maximum and pull-up": "타이탄 최대치와 추가 상승",
    "The row’s Titan maximum applies generated growth to its actual pre-Titan value; it does not replace its earlier rolls with perfect rolls. Elemental ATK, ATK% and DMG% have separate pull-up families among the native elements. Pull-up can raise a row’s maximum but cannot reduce its independent growth, including when original values are equal. Their ranks use generated factors; an unconfirmed rank leaves the projection unavailable. Tied primary stats are evaluated separately, and an ambiguous ceiling remains unknown. Current GRV/PRV uses actual captured values and does not require this forecast.": "행의 타이탄 최대값은 생성된 증가를 실제 타이탄 이전 값에 적용합니다. 이전 롤을 완벽한 롤로 대체하지 않습니다. Elemental 공격력, 공격력% 및 DMG%에는 기본 요소 간에 별도의 풀업 패밀리가 있습니다. 풀업은 행의 최대값을 늘릴 수 있지만 원래 값이 동일한 경우를 포함하여 행의 독립적인 증가를 줄일 수는 없습니다. 이들의 순위는 생성된 요소를 사용합니다. 확인되지 않은 순위는 예측을 사용할 수 없게 만듭니다. 동점 기본 통계는 별도로 평가되며 모호한 한도는 아직 알려지지 않았습니다. 현재 GRV/PRV는 실제 캡처된 값을 사용하며 이 예측이 필요하지 않습니다.",
    "Titan-added stat forecast": "타이탄 추가 능력치 예측",
    "The primary is the stat with the most equivalent rolls before Titan. Each added stat uses that primary’s generated priority/fallback pool; existing random stats are excluded. Unused priority stats fill the available slots first, and fallback stats fill only the remainder. The added stat does not receive Titan growth again. The share is an observed calibration, not a proven game maximum or drop probability. Current ratings use the actual added value.": "기본은 타이탄 이전에 가장 동등한 굴림이 있는 통계입니다. 추가된 각 통계는 기본에서 생성된 우선순위/대체 풀을 사용합니다. 기존 무작위 통계는 제외됩니다. 사용되지 않은 우선순위 통계는 사용 가능한 슬롯을 먼저 채우고 대체 통계는 나머지만 채웁니다. 추가된 능력치는 타이탄 성장을 다시 받지 않습니다. 점유율은 입증된 게임 최대치나 드롭 확률이 아닌 관찰된 보정입니다. 현재 등급은 실제 부가가치를 사용합니다."
  },
  "pt": {
    "What the capture contains": "Conteúdo da captura",
    "The file provides the first received profile stats, equipped items and captured progression. ATK has both a displayed base before ATK% and a native final value. HP and resistance are final values; their full percentage totals are not supplied. Missing fields remain unknown. These are snapshot values, rather than a live reading of the current game screen.": "O arquivo fornece as primeiras estatísticas de perfil recebidas, itens equipados e progressão capturada. ATQ possui uma base exibida antes de ATQ% e um valor final nativo. PV e resistência são valores finais; seus totais percentuais completos não são fornecidos. Os campos ausentes permanecem desconhecidos. Estes são valores instantâneos, em vez de uma leitura ao vivo da tela atual do jogo.",
    "The pair inherits whole gear percentages": "O par herda todos os percentuais dos equipamentos",
    "1 is the selected element and 2 its weapon partner. g is total gear ATK%; q is total gear DMG%. Their winners are chosen independently across the equipped set. Other sources stay on their own element. The stronger element keeps its own percentage; the weaker replaces only its gear portion. A standalone item’s GRV can choose its own winners, while Build totals keep one source per percentage for every slot.": "1 é o elemento selecionado e 2 é o elemento da arma parceira. g representa o ATQ% total dos equipamentos; q, o DMG% total. Os valores máximos de g e q são escolhidos separadamente considerando todos os equipamentos equipados. As outras fontes continuam vinculadas ao próprio elemento. O elemento mais forte mantém seu percentual; no elemento mais fraco, somente a parcela vinda dos equipamentos é substituída. O GRV de um item isolado pode escolher seus próprios máximos, enquanto o total de Build usa uma única fonte para cada percentual em todos os espaços.",
    "Pair ATK and Space Support": "ATQ do par e Apoio espacial",
    "B is a displayed base, including its own Space Support S. Compare the pair after removing each element’s support, then add only the selected element’s support before ATK%. A selected Enhancement Shot’s universal flat ATK is already in both effective bases and is counted once. Do not add support again after percentages. Flat ATK used by the combat table and the per-item GRV choice are separate calculations.": "B é uma base exibida, incluindo seu próprio Apoio espacial S. Compare o par após remover o suporte de cada elemento e adicione apenas o suporte do elemento selecionado antes de ATQ%. O plano universal ATQ de um Injeção de aprimoramento selecionado já está em ambas as bases efetivas e é contado uma vez. Não adicione suporte novamente após porcentagens. O plano ATQ usado pela mesa de combate e a escolha GRV por item são cálculos separados.",
    "Altered combat ATK": "ATQ de combate de Alterado",
    "The combat model copies the strongest native element’s own final ATK, without duo inheritance, and keeps the captured or entered own Altered remainder. Native shot bonuses are inherited after that source’s percentages, once. The card’s imported displayed Altered base already contains the copy, so it is not added to that base again. Altered gear rating uses a different source selection: one gear-only source for GRV, the personal source for PRV.": "O modelo de combate copia o próprio ATQ final do elemento nativo mais forte, sem herança dupla, e mantém o restante do próprio Alterado capturado ou inserido. Os bônus de tiro nativos são herdados após as porcentagens dessa fonte, uma vez. A base Alterado exibida importada do cartão já contém a cópia, portanto ela não é adicionada a essa base novamente. A classificação de equipamento Alterado usa uma seleção de fonte diferente: uma fonte somente de equipamento para GRV, a fonte pessoal para PRV.",
    "Temporary buffs at capture time": "Bônus temporários no momento da captura",
    "Recognized removable constant ATK% buffs are subtracted per element on import, including their stack count. A recognized flat or unknown-magnitude temporary ATK effect can block import. Permitted food and shots remain separate selected consumables. Unrecognized effects are not proof of a clean snapshot; use an out-of-combat capture and the source list when checking a discrepancy.": "Os buffs ATQ% constantes removíveis reconhecidos são subtraídos por elemento na importação, incluindo sua contagem de pilha. Um efeito ATQ temporário reconhecido ou de magnitude desconhecida pode bloquear a importação. Alimentos e shots permitidos permanecem como consumíveis selecionados separadamente. Efeitos não reconhecidos não são prova de um instantâneo limpo; use uma captura fora de combate e a lista de fontes ao verificar uma discrepância.",
    "Account relic passives": "Passivos das relíquias da conta",
    "Captured account relic passives apply even when those relics are not equipped. Their DMG% and RES% are distinct per-element values. Damage-received reduction is not automatically a resistance-stat multiplier: the capture’s attribute mapping determines which pool a passive affects. Relic A4 DMG% is included once in its own element’s combat DMG% and also shown in the relic summary. Relic RES% joins the known resistance multiplier once; changing the two equipped relics does not reset account passives.": "As passivas das relíquias da conta capturada se aplicam mesmo quando essas relíquias não estão equipadas. Seus DMG% e RES% são valores distintos por elemento. A redução de dano recebido não é automaticamente um multiplicador de estatísticas de resistência: o mapeamento de atributos da captura determina qual grupo um passivo afeta. A relíquia A4 DMG% é incluída uma vez no combate do seu próprio elemento DMG% e também é mostrada no resumo da relíquia. Relic RES% junta-se ao multiplicador de resistência conhecido uma vez; alterar as duas relíquias equipadas não zera as passivas da conta.",
    "Unknown data and rounding": "Dados desconhecidos e arredondamento",
    "Calculations retain fractional values; separate displayed rows can differ by a unit after rounding. A blank required base is unknown, rather than zero. Unknown catalog items remain empty and are listed; catalog fitting is not verification of their effects. The badge ≈ denotes a modeled estimate. Up displays the normalized upgrade level stored in the file: the exporter has already converted the raw profile suffix by adding one. The card does not add one again. This model has no separate Up multiplier for weapon stat endpoints or weapon CS.": "Os cálculos retêm valores fracionários; linhas exibidas separadas podem diferir em uma unidade após o arredondamento. Uma base obrigatória em branco é desconhecida, em vez de zero. Os itens de catálogo desconhecidos permanecem vazios e são listados; A adequação ao catálogo não é a verificação de seus efeitos. O emblema ≈ denota uma estimativa modelada. Up exibe o nível de atualização normalizado armazenado no arquivo: o exportador já converteu o sufixo do perfil bruto adicionando um. O cartão não adiciona um novamente. Este modelo não tem multiplicador Up separado para pontos finais de estatísticas de armas ou armas PC.",
    "Universal ATK": "ATQ universal",
    "Universal ATK is inferred, not a separately captured stat. The remainder includes universal gear ATK and external sources. The card shows it only when all four native bases are available and their remainders agree within one ATK. Otherwise it shows —. Its tooltip separates universal gear, the selected shot and remaining sources; it does not apply ATK% to this base.": "Universal ATQ é inferido, não uma estatística capturada separadamente. O restante inclui equipamento universal ATQ e fontes externas. O cartão mostra isso apenas quando todas as quatro bases nativas estão disponíveis e seus remanescentes concordam dentro de um ATQ. Caso contrário, mostra -. Sua dica separa o equipamento universal, o tiro selecionado e as fontes restantes; não se aplica ATQ% a esta base.",
    "HP and HP%": "PV e PV%",
    "h is full HP% as a fraction. Without an explicitly entered total, only equipped gear HP% is known. The tooltip separates the pre-percentage pool into other sources, gear and the shot, then shows the percentage gain and final HP. Unknown external HP% or another multiplier makes the restored base an estimate. A missing HP snapshot stays missing.": "h está completo PV% como uma fração. Sem um total inserido explicitamente, apenas o equipamento equipado PV% é conhecido. A dica de ferramenta separa o conjunto de pré-porcentagem em outras fontes, equipamento e tiro, depois mostra o ganho percentual e o PV final. PV% externo desconhecido ou outro multiplicador torna a base restaurada uma estimativa. Um instantâneo PV ausente permanece ausente.",
    "Crit rating and chance": "Valor de crítico e chance de crítico",
    "The rating tooltip separates other sources, equipped gear and the shot. The level denominator comes from the game curve for the selected enemy level. The panel shows the uncapped sum; expected-output and personal rating calculations cap useful chance at 100%. Crit DMG is a bonus: the expected critical factor is 1 + c_rating × Crit DMG, rather than chance multiplied by full critical damage.": "A dica de classificação separa outras fontes, equipamento equipado e tiro. O denominador de nível vem da curva do jogo para o nível do inimigo selecionado. O painel mostra a soma ilimitada; os cálculos de resultados esperados e de classificação pessoal limitam a chance útil a 100%. DMG crítico é um bônus: o fator crítico esperado é 1 + c_rating × DMG crítico, em vez do acaso multiplicado pelo dano crítico total.",
    "Resistance and damage reduction": "Resistência e redução de dano",
    "r is full RES%, or the known source sum when a full value is unavailable. Universal flat RES contributes to every element; elemental RES contributes only to its own. The shot is added before RES%. K uses character level, while the Crit curve uses enemy level. This reduction is the resistance component, not the product of every damage-reduction effect in combat. Tank EHP = HP × (1 + RES_effective / K).": "r é RES% completo ou a soma da fonte conhecida quando um valor completo não está disponível. Plano universal RES contribui para cada elemento; elementar RES contribui apenas para o seu próprio. A cena é adicionada antes de RES%. K usa o nível do personagem, enquanto a curva Crít. usa o nível do inimigo. Esta redução é o componente de resistência, não o produto de todos os efeitos de redução de danos em combate. Tanque EHP = PV × (1 + RES_efetivo / K).",
    "The combat DMG% column": "Coluna de DMG% de combate",
    "For captures, this column is derived from the loadout; no full DMG% total is captured. Only generated recognized contributions enter it. Relic A4 is included once for its own element; duo inheritance replaces only gear DMG%, leaving relic and other non-gear bonuses on their own element. Alternative conditional Space Support modes do not stack: the strongest applicable mode per element is used. Imported Altered DMG% is zero in this model. This column is not a complete damage or rotation simulator.": "Para capturas, esta coluna é derivada do carregamento; nenhum total DMG% completo é capturado. Somente contribuições reconhecidas geradas entram nele. A Relíquia A4 é incluída uma vez para seu próprio elemento; a herança dupla substitui apenas o equipamento DMG%, deixando relíquias e outros bônus não relacionados ao equipamento em seu próprio elemento. Os modos Apoio espacial condicionais alternativos não se acumulam: o modo aplicável mais forte por elemento é usado. Alterado importado DMG% é zero neste modelo. Esta coluna não é um simulador completo de dano ou rotação.",
    "Enhancement Shot stat gain": "Aumento de atributos com a Injeção de aprimoramento",
    "For weapons, the target is the catalog’s maximum weapon level at the weapon’s actual stars. For matrices, it is the maximum level and maximum base-stat advancement. The selected shot adds these four flat gains to the first received stats. HP and RES gains are multiplied by their percentages; native ATK gains are multiplied by native ATK%; Altered inherits once. It does not change captured stars, Up or matrix set-effect ranks. Recalculation replaces the previous applied gain and does not add it again.": "Para armas, o alvo é o nível máximo de arma do catálogo nas estrelas reais da arma. Para matrizes, é o nível máximo e o avanço máximo das estatísticas básicas. A tacada selecionada adiciona esses quatro ganhos fixos às primeiras estatísticas recebidas. Os ganhos PV e RES são multiplicados por seus percentuais; os ganhos do ATQ nativo são multiplicados pelos ATQ% nativos; Alterado herda uma vez. Não altera estrelas capturadas, Up ou classificações de efeito de conjunto de matriz. O recálculo substitui o ganho aplicado anteriormente e não o adiciona novamente.",
    "Selected ATK% consumables": "Consumíveis de ATQ% selecionados",
    "The model applies only generated, recognized unconditional ATK% bonuses of selected consumables. A universal bonus targets the native elements declared by the catalog; it is not applied to Altered a second time. Unknown, conditional and other consumable effects are not inferred from their names. The expiry time describes the captured buff; the card is a saved configuration and does not automatically clear the selected consumable when that clock expires.": "O modelo aplica apenas bônus ATQ% incondicionais gerados e reconhecidos de consumíveis selecionados. Um bônus universal visa os elementos nativos declarados no catálogo; não é aplicado a Alterado uma segunda vez. Efeitos desconhecidos, condicionais e outros efeitos consumíveis não são inferidos de seus nomes. O tempo de expiração descreve o buff capturado; o cartão é uma configuração salva e não limpa automaticamente o consumível selecionado quando o relógio expira.",
    "Current CS and Apex CS": "PC atual e PC máximo",
    "Current CS starts from the captured profile score or the manual input. The selected Enhancement Shot adds its modeled flat-stat CS delta once; when a precise captured CS is available, rounding starts from that value. Apex CS remains the recorded historical maximum with its recorded time. The model does not replace current CS with the sum of gear, weapons, matrices and other system estimates, and it does not infer a new complete CS after every manual loadout edit or recompute every other consumable’s CS impact. The displayed integer header difference can differ from the rounded shot subtotal by one because the original captured CS has a fraction.": "O PC atual começa a partir da pontuação do perfil capturada ou da entrada manual. O Injeção de aprimoramento selecionado adiciona seu delta PC de estatística plana modelado uma vez; quando um PC capturado com precisão estiver disponível, o arredondamento começa a partir desse valor. PC máximo permanece o máximo histórico registrado com seu tempo registrado. O modelo não substitui o PC atual pela soma de equipamentos, armas, matrizes e outras estimativas do sistema, e não infere um novo PC completo após cada edição manual de carregamento ou recalcula o impacto PC de todos os outros consumíveis. A diferença do cabeçalho inteiro exibido pode diferir do subtotal arredondado em um porque o PC original capturado tem uma fração.",
    "Weapon CS": "PC da arma",
    "The card’s weapon source label scores the weapon alone. Level gains and star coefficients come from generated game tables. Only the current star’s StarSkillScore is added, not the sum of all earlier stars. Matrix scores and their set AddScore are separate. The reconstruction matches documented server-score samples within floating-point differences; that does not establish every weapon, upgrade field or native rounding case.": "O rótulo da fonte da arma da carta pontua apenas a arma. Os ganhos de nível e os coeficientes de estrelas vêm das mesas de jogo geradas. Apenas o StarSkillScore da estrela atual é adicionado, não a soma de todas as estrelas anteriores. As pontuações da matriz e seu conjunto AddScore são separados. A reconstrução corresponde a amostras documentadas de pontuação do servidor dentro de diferenças de ponto flutuante; isso não estabelece todas as armas, campos de atualização ou casos de arredondamento nativos.",
    "Matrices and set CS": "PC de matrizes e conjuntos",
    "Each matrix uses its own slot profile, level and star multiplier. Use fractional stats for the score; the displayed matrix stat has its own float32 truncation. Set AddScore is counted once per reached piece threshold on one weapon. The model ranks the set by the threshold’s Nth strongest matrix; mixed-star selection has not been separately verified in every case. Enhancement Shot changes base-stat endpoints, not these set ranks.": "Cada matriz usa seu próprio perfil de slot, nível e multiplicador de estrelas. Use estatísticas fracionárias para a pontuação; a estatística da matriz exibida tem seu próprio truncamento float32. O conjunto AddScore é contado uma vez por limite de peça alcançado em uma arma. O modelo classifica o conjunto pela enésima matriz mais forte do limite; a seleção de estrelas mistas não foi verificada separadamente em todos os casos. Injeção de aprimoramento altera os pontos finais das estatísticas básicas, não essas classificações definidas.",
    "Titan property: effect and CS": "Atributo Titã: efeito e PC",
    "The effect tooltip evaluates the game’s effect curve at the summed level. CS evaluates the separate display curve at each item’s own level and then sums its CS. A nonlinear curve means those two orders are not interchangeable. At level zero the effect is absent; between curve keys the model interpolates linearly and outside the keys it uses the endpoint. Gear CS already includes this property: do not add the Titan CS summary to gear CS again.": "A dica de efeito avalia a curva de efeito do jogo no nível somado. PC avalia a curva de exibição separada no nível de cada item e depois soma seu PC. Uma curva não linear significa que essas duas ordens não são intercambiáveis. No nível zero o efeito está ausente; entre as chaves da curva o modelo interpola linearmente e fora das chaves ele usa o ponto final. O equipamento PC já inclui esta propriedade: não adicione o resumo Titã PC ao equipamento PC novamente.",
    "Supercomputing, Space Support and suppressor CS": "PC da Supercomputação, do Apoio espacial e do supressor",
    "Raw attributes of the current level are weighted with the game attribute weights. Content modules give twice the DMG of a base DMG module and are scored with the same DMG% weight; the game weight of their final-DMG attribute is zero, so this is a model assumption. Supercomputing ATK% / RES%, healing and Shatter are not scored: weighting ATK% / RES% by the build’s bases would exceed the whole unexplained remainder of captured total CS. The game does not report a separate score for these systems, so each value is an estimate shown on hover over current CS; it is not added to the current CS.": "Os atributos brutos do nível atual são ponderados com os pesos dos atributos do jogo. Os módulos de conteúdo fornecem o dobro do DMG de um módulo DMG base e são pontuados com o mesmo peso DMG%; o peso do jogo de seu atributo final-DMG é zero, então esta é uma suposição do modelo. Supercomputação ATQ% / RES%, cura e Estilhaço não são pontuados: a ponderação ATQ% / RES% pelas bases da construção excederia todo o restante inexplicável de total capturado PC. O jogo não informa uma pontuação separada para esses sistemas, então cada valor é uma estimativa mostrada ao passar o mouse sobre o PC atual; ele não é adicionado ao PC atual.",
    "Enhancement Shot CS": "PC da Injeção de aprimoramento",
    "This is the weighted sum of the shot’s flat weapon/matrix gains. Universal ATK and RES count once, without combat ATK%/HP%/RES% and without matrix set AddScore or a new weapon StarSkillScore. The current profile model adds this subtotal once. It matches the documented before/after sample; it is not a universal proof of every indirect native CS change. Hovering current CS reveals this gain beside the shot, without a permanent caption.": "Esta é a soma ponderada dos ganhos de arma/matriz plana do tiro. Universal ATQ e RES contam uma vez, sem combate ATQ%/PV%/RES% e sem conjunto de matriz AddScore ou um nova arma StarSkillScore. O modelo de perfil atual adiciona esse subtotal uma vez. Corresponde à amostra documentada antes/depois; não é uma prova universal de todas as alterações nativas indiretas de PC. Passar o mouse sobre o atual PC revela esse ganho ao lado da foto, sem legenda permanente.",
    "Roll count and quality": "Quantidade e qualidade das rolagens",
    "Roll inference uses values before Titan, not current augmented values. The number of rolls must fit every row and the item’s total stars. If several splits fit, the card selects a likelihood estimate and marks disputed counts with ~; missing or impossible data gives ?. The likelihood model approximates sums of uniform rolls and is not a confirmed game drop distribution. Quality excludes initial values and is undefined for zero rolls or fixed-size rolls.": "O número de rolagens é inferido a partir dos valores anteriores ao Titã, não dos valores já aprimorados. Ele precisa corresponder a cada linha e ao total de estrelas do item. Se houver várias distribuições possíveis, o cartão seleciona uma estimativa de probabilidade e marca as quantidades incertas com ~; dados ausentes ou impossíveis são indicados com ?. O modelo aproxima a soma de rolagens uniformes; a distribuição real de obtenção no jogo não foi confirmada. A qualidade desconsidera os valores iniciais e não é definida para zero rolagens ou rolagens de valor fixo.",
    "Titan maximum and pull-up": "Máximo do Titã e aumento das rolagens",
    "The row’s Titan maximum applies generated growth to its actual pre-Titan value; it does not replace its earlier rolls with perfect rolls. Elemental ATK, ATK% and DMG% have separate pull-up families among the native elements. Pull-up can raise a row’s maximum but cannot reduce its independent growth, including when original values are equal. Their ranks use generated factors; an unconfirmed rank leaves the projection unavailable. Tied primary stats are evaluated separately, and an ambiguous ceiling remains unknown. Current GRV/PRV uses actual captured values and does not require this forecast.": "O máximo Titã da linha aplica o crescimento gerado ao seu valor real pré-Titã; ele não substitui seus rolos anteriores por rolos perfeitos. Elementais ATQ, ATQ% e DMG% possuem famílias pull-up separadas entre os elementos nativos. O pull-up pode aumentar o máximo de uma linha, mas não pode reduzir seu crescimento independente, inclusive quando os valores originais são iguais. Suas classificações utilizam fatores gerados; uma classificação não confirmada deixa a projeção indisponível. As estatísticas primárias vinculadas são avaliadas separadamente e um teto ambíguo permanece desconhecido. O GRV/PRV atual usa valores reais capturados e não requer esta previsão.",
    "Titan-added stat forecast": "Previsão dos atributos adicionados pelo Titã",
    "The primary is the stat with the most equivalent rolls before Titan. Each added stat uses that primary’s generated priority/fallback pool; existing random stats are excluded. Unused priority stats fill the available slots first, and fallback stats fill only the remainder. The added stat does not receive Titan growth again. The share is an observed calibration, not a proven game maximum or drop probability. Current ratings use the actual added value.": "A principal é a estatística com os lançamentos mais equivalentes antes de Titã. Cada estatística adicionada usa o pool de prioridade/substituição gerado pelo primário; estatísticas aleatórias existentes são excluídas. As estatísticas de prioridade não utilizadas preenchem primeiro os espaços disponíveis e as estatísticas de reserva preenchem apenas o restante. A estatística adicionada não recebe crescimento Titã novamente. A parcela é uma calibração observada, não um máximo comprovado de jogo ou probabilidade de queda. As classificações atuais utilizam o valor agregado real."
  },
  "th": {
    "What the capture contains": "ข้อมูลที่รวมอยู่ในการจับข้อมูล",
    "The file provides the first received profile stats, equipped items and captured progression. ATK has both a displayed base before ATK% and a native final value. HP and resistance are final values; their full percentage totals are not supplied. Missing fields remain unknown. These are snapshot values, rather than a live reading of the current game screen.": "ไฟล์นี้จะให้ข้อมูลสถิติโปรไฟล์ที่ได้รับครั้งแรก ไอเทมที่สวมใส่ และความก้าวหน้าที่บันทึกไว้ ATK มีทั้งฐานที่แสดงก่อน ATK% และค่าสุดท้ายดั้งเดิม HP และแนวต้านเป็นค่าสุดท้าย ไม่ได้ระบุผลรวมเปอร์เซ็นต์เต็ม ยังไม่ทราบช่องที่หายไป ค่าเหล่านี้เป็นค่าสแน็ปช็อต แทนที่จะเป็นการอ่านสดของหน้าจอเกมปัจจุบัน",
    "The pair inherits whole gear percentages": "คู่ธาตุรับโบนัสเปอร์เซ็นต์จากอุปกรณ์ทั้งหมด",
    "1 is the selected element and 2 its weapon partner. g is total gear ATK%; q is total gear DMG%. Their winners are chosen independently across the equipped set. Other sources stay on their own element. The stronger element keeps its own percentage; the weaker replaces only its gear portion. A standalone item’s GRV can choose its own winners, while Build totals keep one source per percentage for every slot.": "1 คือธาตุที่เลือก และ 2 คือธาตุของอาวุธคู่กัน g คือค่า ATK% รวมจากอุปกรณ์ทั้งหมด ส่วน q คือค่า DMG% รวม ค่าสูงสุดของ g และ q จะเลือกแยกกันโดยพิจารณาอุปกรณ์ที่สวมใส่ทั้งหมด แหล่งโบนัสอื่นยังคงอยู่กับธาตุเดิม ธาตุที่แข็งแกร่งกว่าจะใช้เปอร์เซ็นต์ของตัวเอง ส่วนธาตุที่อ่อนกว่าจะเปลี่ยนเฉพาะส่วนที่มาจากอุปกรณ์ GRV ของไอเทมชิ้นเดียวเลือกค่าสูงสุดของตัวเองได้ แต่ยอดรวม บิลด์ ใช้แหล่งเดียวต่อเปอร์เซ็นต์จากทุกช่อง",
    "Pair ATK and Space Support": "ATK ของคู่ธาตุและการสนับสนุนจากอวกาศ",
    "B is a displayed base, including its own Space Support S. Compare the pair after removing each element’s support, then add only the selected element’s support before ATK%. A selected Enhancement Shot’s universal flat ATK is already in both effective bases and is counted once. Do not add support again after percentages. Flat ATK used by the combat table and the per-item GRV choice are separate calculations.": "B คือฐานที่แสดง รวมถึง การสนับสนุนจากอวกาศ S ของตัวเองด้วย เปรียบเทียบคู่หลังจากลบส่วนรองรับของแต่ละองค์ประกอบออก แล้วเพิ่มเฉพาะส่วนรองรับขององค์ประกอบที่เลือกก่อน ATK% ATK แบบเรียบอเนกประสงค์ของ ยาฉีดเสริมพลัง ที่เลือกไว้มีอยู่แล้วในฐานที่มีประสิทธิภาพทั้งสองและจะถูกนับหนึ่งครั้ง อย่าเพิ่มการสนับสนุนอีกหลังจากเปอร์เซ็นต์ ATK แบบเรียบที่ใช้โดยโต๊ะต่อสู้และตัวเลือก GRV ต่อรายการเป็นการคำนวณแยกกัน",
    "Altered combat ATK": "ATK ต่อสู้ของ Altered",
    "The combat model copies the strongest native element’s own final ATK, without duo inheritance, and keeps the captured or entered own Altered remainder. Native shot bonuses are inherited after that source’s percentages, once. The card’s imported displayed Altered base already contains the copy, so it is not added to that base again. Altered gear rating uses a different source selection: one gear-only source for GRV, the personal source for PRV.": "โมเดลการต่อสู้จะคัดลอก ATK สุดท้ายจากองค์ประกอบดั้งเดิมที่แข็งแกร่งที่สุดของตัวเอง โดยไม่มีมรดกแบบคู่ และเก็บส่วนที่เหลือของ Altered ที่ยึดมาหรือป้อนเองไว้ โบนัสช็อตดั้งเดิมจะสืบทอดหลังจากเปอร์เซ็นต์ของแหล่งนั้นหนึ่งครั้ง ฐาน Altered ที่แสดงที่นำเข้าของการ์ดมีสำเนาอยู่แล้ว ดังนั้นจึงไม่ถูกเพิ่มลงในฐานนั้นอีก พิกัดเกียร์ Altered ใช้การเลือกแหล่งสัญญาณที่แตกต่างกัน: แหล่งเกียร์อย่างเดียวสำหรับ GRV แหล่งเดียวสำหรับ PRV",
    "Temporary buffs at capture time": "บัฟชั่วคราวขณะจับข้อมูล",
    "Recognized removable constant ATK% buffs are subtracted per element on import, including their stack count. A recognized flat or unknown-magnitude temporary ATK effect can block import. Permitted food and shots remain separate selected consumables. Unrecognized effects are not proof of a clean snapshot; use an out-of-combat capture and the source list when checking a discrepancy.": "บัฟ ATK% คงที่ที่ถอดออกได้ที่รู้จักจะถูกหักออกตามองค์ประกอบในการนำเข้า รวมถึงจำนวนสแต็กด้วย เอฟเฟกต์ ATK ชั่วคราวแบบคงที่หรือไม่ทราบขนาดที่รู้จักสามารถบล็อกการนำเข้าได้ อาหารและช็อตที่ได้รับอนุญาตยังคงเป็นวัสดุสิ้นเปลืองที่เลือกแยกจากกัน เอฟเฟกต์ที่ไม่รู้จักไม่ใช่ข้อพิสูจน์ถึงสแน็ปช็อตที่สะอาด ใช้การจับภาพนอกการต่อสู้และรายการแหล่งที่มาเมื่อตรวจสอบความคลาดเคลื่อน",
    "Account relic passives": "พาสซีฟรีลิกของบัญชี",
    "Captured account relic passives apply even when those relics are not equipped. Their DMG% and RES% are distinct per-element values. Damage-received reduction is not automatically a resistance-stat multiplier: the capture’s attribute mapping determines which pool a passive affects. Relic A4 DMG% is included once in its own element’s combat DMG% and also shown in the relic summary. Relic RES% joins the known resistance multiplier once; changing the two equipped relics does not reset account passives.": "พาสซีฟโบราณวัตถุบัญชีที่ยึดไว้จะมีผลแม้ในขณะที่ไม่ได้ติดตั้งโบราณวัตถุเหล่านั้น DMG% และ ต้านทาน% เป็นค่าต่อองค์ประกอบที่แตกต่างกัน การลดความเสียหายที่ได้รับไม่ได้เป็นตัวคูณสถิติความต้านทานโดยอัตโนมัติ: การแมปคุณลักษณะของการยึดจะกำหนดว่าพูลใดที่ส่งผลแบบพาสซีฟ Relic A4 DMG% จะถูกรวมไว้ครั้งหนึ่งในการรบ DMG% ขององค์ประกอบของตัวเอง และยังแสดงไว้ในบทสรุปของ Relic ด้วย Relic ต้านทาน% เข้าร่วมตัวคูณความต้านทานที่รู้จักหนึ่งครั้ง การเปลี่ยนโบราณวัตถุทั้งสองที่ติดตั้งไว้จะไม่รีเซ็ตพาสซีฟของบัญชี",
    "Unknown data and rounding": "ข้อมูลที่ไม่ทราบและการปัดเศษ",
    "Calculations retain fractional values; separate displayed rows can differ by a unit after rounding. A blank required base is unknown, rather than zero. Unknown catalog items remain empty and are listed; catalog fitting is not verification of their effects. The badge ≈ denotes a modeled estimate. Up displays the normalized upgrade level stored in the file: the exporter has already converted the raw profile suffix by adding one. The card does not add one again. This model has no separate Up multiplier for weapon stat endpoints or weapon CS.": "การคำนวณจะคงค่าเศษส่วนไว้ แถวที่แสดงแยกกันอาจแตกต่างกันไปตามหน่วยหลังจากการปัดเศษ ไม่ทราบฐานที่ต้องการว่าง แทนที่จะเป็นศูนย์ รายการแค็ตตาล็อกที่ไม่รู้จักยังคงว่างเปล่าและแสดงอยู่ในรายการ การติดตั้งแค็ตตาล็อกไม่ใช่การตรวจสอบผลกระทบ ป้ายกำกับ µ แสดงถึงการประมาณค่าตามแบบจำลอง Up แสดงระดับการอัพเกรดปกติที่จัดเก็บไว้ในไฟล์: ผู้ส่งออกได้แปลงส่วนต่อท้ายโปรไฟล์ดิบแล้วโดยการเพิ่มระดับหนึ่ง การ์ดจะไม่เพิ่มอีกครั้ง โมเดลนี้ไม่มีตัวคูณ Up แยกต่างหากสำหรับจุดสิ้นสุดสถานะของอาวุธหรือ CS ของอาวุธ",
    "Universal ATK": "ATK ทั่วไป",
    "Universal ATK is inferred, not a separately captured stat. The remainder includes universal gear ATK and external sources. The card shows it only when all four native bases are available and their remainders agree within one ATK. Otherwise it shows —. Its tooltip separates universal gear, the selected shot and remaining sources; it does not apply ATK% to this base.": "Universal ATK ได้รับการอนุมาน ไม่ใช่สถิติที่บันทึกแยกกัน ส่วนที่เหลือรวมถึงเกียร์สากล ATK และแหล่งภายนอก การ์ดจะแสดงเฉพาะเมื่อมีฐานดั้งเดิมทั้งสี่ฐานเท่านั้น และส่วนที่เหลือเห็นด้วยภายใน ATK เดียว ไม่งั้นก็แสดงว่า—. คำแนะนำเครื่องมือจะแยกเกียร์สากล ช็อตที่เลือก และแหล่งสัญญาณที่เหลือ มันไม่ได้ใช้ ATK% กับฐานนี้",
    "HP and HP%": "HP และ HP%",
    "h is full HP% as a fraction. Without an explicitly entered total, only equipped gear HP% is known. The tooltip separates the pre-percentage pool into other sources, gear and the shot, then shows the percentage gain and final HP. Unknown external HP% or another multiplier makes the restored base an estimate. A missing HP snapshot stays missing.": "h เต็ม HP% เป็นเศษส่วน หากไม่มีการป้อนผลรวมอย่างชัดเจน จะทราบเฉพาะเกียร์ที่ติดตั้ง HP% เท่านั้น คำแนะนำเครื่องมือจะแยกพูลเปอร์เซ็นต์ล่วงหน้าออกเป็นแหล่งที่มา อุปกรณ์ และช็อตอื่นๆ จากนั้นจะแสดงเปอร์เซ็นต์ที่เพิ่มขึ้นและ HP สุดท้าย HP% ภายนอกที่ไม่รู้จักหรือตัวคูณอื่นทำให้ฐานที่กู้คืนเป็นการประมาณค่า สแน็ปช็อต HP ที่หายไปยังคงหายไป",
    "Crit rating and chance": "ค่าสถิติคริติคอลและอัตราคริติคอล",
    "The rating tooltip separates other sources, equipped gear and the shot. The level denominator comes from the game curve for the selected enemy level. The panel shows the uncapped sum; expected-output and personal rating calculations cap useful chance at 100%. Crit DMG is a bonus: the expected critical factor is 1 + c_rating × Crit DMG, rather than chance multiplied by full critical damage.": "คำแนะนำเครื่องมือการให้คะแนนจะแยกแหล่งอื่นๆ อุปกรณ์ที่ติดตั้ง และการยิง ตัวส่วนระดับมาจากเส้นโค้งของเกมสำหรับระดับศัตรูที่เลือก แผงจะแสดงผลรวมที่ยังไม่ได้จำกัด การคำนวณผลลัพธ์ที่คาดหวังและคะแนนส่วนบุคคลจะจำกัดโอกาสที่เป็นประโยชน์ที่ 100% DMG คริติคอล เป็นโบนัส: ปัจจัยคริติคอลที่คาดหวังคือ 1 + c_rating × DMG คริติคอล แทนที่จะเป็นโอกาสคูณด้วยความเสียหายคริติคอลเต็มจำนวน",
    "Resistance and damage reduction": "ค่าต้านทานและการลดความเสียหาย",
    "r is full RES%, or the known source sum when a full value is unavailable. Universal flat RES contributes to every element; elemental RES contributes only to its own. The shot is added before RES%. K uses character level, while the Crit curve uses enemy level. This reduction is the resistance component, not the product of every damage-reduction effect in combat. Tank EHP = HP × (1 + RES_effective / K).": "r คือ ต้านทาน% เต็ม หรือผลรวมแหล่งที่มาที่ทราบเมื่อค่าเต็มไม่พร้อมใช้งาน Universal flat ต้านทาน มีส่วนช่วยในทุกองค์ประกอบ องค์ประกอบ ต้านทาน มีส่วนช่วยในตัวมันเองเท่านั้น เพิ่มช็อตก่อน ต้านทาน% K ใช้ระดับตัวละคร ในขณะที่เส้นโค้ง คริ ใช้ระดับศัตรู การลดลงนี้เป็นส่วนประกอบของความต้านทาน ไม่ใช่ผลจากการลดความเสียหายในการต่อสู้ รถถัง EHP = HP × (1 + ต้านทาน_efficient / K)",
    "The combat DMG% column": "คอลัมน์ DMG% ในการต่อสู้",
    "For captures, this column is derived from the loadout; no full DMG% total is captured. Only generated recognized contributions enter it. Relic A4 is included once for its own element; duo inheritance replaces only gear DMG%, leaving relic and other non-gear bonuses on their own element. Alternative conditional Space Support modes do not stack: the strongest applicable mode per element is used. Imported Altered DMG% is zero in this model. This column is not a complete damage or rotation simulator.": "สำหรับการจับ คอลัมน์นี้ได้มาจากชุดปรับแต่ง ไม่มีการบันทึกผลรวม DMG% เต็ม เฉพาะการมีส่วนร่วมที่ได้รับการยอมรับที่สร้างขึ้นเท่านั้นที่เข้ามา Relic A4 ถูกรวมไว้หนึ่งครั้งสำหรับองค์ประกอบของตัวเอง การสืบทอดคู่จะแทนที่เฉพาะเกียร์ DMG% โดยเหลือโบนัสของที่ระลึกและโบนัสที่ไม่ใช่เกียร์อื่น ๆ ไว้ในองค์ประกอบของตัวเอง โหมด การสนับสนุนจากอวกาศ แบบมีเงื่อนไขทางเลือกจะไม่ซ้อนกัน: มีการใช้โหมดที่ใช้งานได้ดีที่สุดต่อองค์ประกอบ Altered DMG% ที่นำเข้าเป็นศูนย์ในรุ่นนี้ คอลัมน์นี้ไม่ใช่เครื่องจำลองความเสียหายหรือการหมุนที่สมบูรณ์",
    "Enhancement Shot stat gain": "การเพิ่มค่าสถานะจากยาฉีดเสริมพลัง",
    "For weapons, the target is the catalog’s maximum weapon level at the weapon’s actual stars. For matrices, it is the maximum level and maximum base-stat advancement. The selected shot adds these four flat gains to the first received stats. HP and RES gains are multiplied by their percentages; native ATK gains are multiplied by native ATK%; Altered inherits once. It does not change captured stars, Up or matrix set-effect ranks. Recalculation replaces the previous applied gain and does not add it again.": "สำหรับอาวุธ เป้าหมายคือระดับอาวุธสูงสุดของแคตตาล็อกตามดาวที่แท้จริงของอาวุธ สำหรับเมทริกซ์ มันคือระดับสูงสุดและความก้าวหน้าพื้นฐานสูงสุด ช็อตที่เลือกจะเพิ่มกำไรแบบคงที่ทั้งสี่นี้ให้กับสถิติที่ได้รับครั้งแรก กำไรของ HP และ ต้านทาน จะถูกคูณด้วยเปอร์เซ็นต์ กำไรดั้งเดิมของ ATK จะถูกคูณด้วย ATK% ดั้งเดิม Altered สืบทอดหนึ่งครั้ง มันไม่เปลี่ยนดาวที่จับได้, Up หรืออันดับเซ็ตเอฟเฟกต์เมทริกซ์ การคำนวณใหม่จะแทนที่กำไรที่ใช้ก่อนหน้านี้และจะไม่บวกอีกครั้ง",
    "Selected ATK% consumables": "ไอเทม ATK% ที่เลือกใช้",
    "The model applies only generated, recognized unconditional ATK% bonuses of selected consumables. A universal bonus targets the native elements declared by the catalog; it is not applied to Altered a second time. Unknown, conditional and other consumable effects are not inferred from their names. The expiry time describes the captured buff; the card is a saved configuration and does not automatically clear the selected consumable when that clock expires.": "โมเดลนี้ใช้เฉพาะโบนัส ATK% ที่สร้างขึ้นและได้รับการยอมรับแบบไม่มีเงื่อนไขของยุทธปัจจัยที่เลือก โบนัสสากลกำหนดเป้าหมายองค์ประกอบดั้งเดิมที่ประกาศโดยแค็ตตาล็อก ไม่ได้ใช้กับ Altered เป็นครั้งที่สอง ผลกระทบที่ไม่ทราบ มีเงื่อนไข และผลกระทบสิ้นเปลืองอื่น ๆ จะไม่อนุมานจากชื่อของมัน เวลาหมดอายุจะอธิบายบัฟที่ยึดได้ การ์ดนี้เป็นการกำหนดค่าที่บันทึกไว้และจะไม่ล้างวัสดุสิ้นเปลืองที่เลือกโดยอัตโนมัติเมื่อนาฬิกานั้นหมดอายุ",
    "Current CS and Apex CS": "CS ปัจจุบันและ CS สูงสุด",
    "Current CS starts from the captured profile score or the manual input. The selected Enhancement Shot adds its modeled flat-stat CS delta once; when a precise captured CS is available, rounding starts from that value. Apex CS remains the recorded historical maximum with its recorded time. The model does not replace current CS with the sum of gear, weapons, matrices and other system estimates, and it does not infer a new complete CS after every manual loadout edit or recompute every other consumable’s CS impact. The displayed integer header difference can differ from the rounded shot subtotal by one because the original captured CS has a fraction.": "CS ปัจจุบันเริ่มต้นจากคะแนนโปรไฟล์ที่บันทึกไว้หรือการป้อนข้อมูลด้วยตนเอง ยาฉีดเสริมพลัง ที่เลือกจะเพิ่มเดลต้า CS แบบแฟลตสเตตที่จำลองไว้หนึ่งครั้ง เมื่อมี CS ที่จับภาพได้อย่างแม่นยำ การปัดเศษจะเริ่มต้นจากค่านั้น CS สูงสุด ยังคงเป็นค่าสูงสุดในอดีตที่บันทึกไว้พร้อมกับเวลาที่บันทึกไว้ โมเดลไม่ได้แทนที่ CS ปัจจุบันด้วยผลรวมของเกียร์ อาวุธ เมทริกซ์ และการประมาณค่าระบบอื่นๆ และไม่ได้อนุมาน CS ใหม่ที่สมบูรณ์หลังจากแก้ไขชุดปรับแต่งด้วยตนเองทุกครั้ง หรือคำนวณผลกระทบของ CS ของยุทโธปกรณ์อื่นๆ ใหม่ทั้งหมด ผลต่างส่วนหัวของจำนวนเต็มที่แสดงอาจแตกต่างจากผลรวมย่อยของช็อตที่ปัดเศษทีละหนึ่ง เนื่องจาก CS ต้นฉบับที่บันทึกไว้มีเศษส่วน",
    "Weapon CS": "CS ของอาวุธ",
    "The card’s weapon source label scores the weapon alone. Level gains and star coefficients come from generated game tables. Only the current star’s StarSkillScore is added, not the sum of all earlier stars. Matrix scores and their set AddScore are separate. The reconstruction matches documented server-score samples within floating-point differences; that does not establish every weapon, upgrade field or native rounding case.": "ป้ายกำกับแหล่งที่มาของอาวุธของการ์ดจะให้คะแนนอาวุธเพียงอย่างเดียว ระดับที่เพิ่มขึ้นและค่าสัมประสิทธิ์ดาวมาจากตารางเกมที่สร้างขึ้น มีการเพิ่มเฉพาะ StarSkillScore ของดาวปัจจุบันเท่านั้น ไม่ใช่ผลรวมของดาวฤกษ์ก่อนหน้านี้ทั้งหมด คะแนนเมทริกซ์และชุด AddScore แยกจากกัน การสร้างใหม่จะตรงกับตัวอย่างคะแนนเซิร์ฟเวอร์ที่บันทึกไว้ภายในผลต่างจุดลอยตัว ที่ไม่ได้สร้างอาวุธทุกอัน อัพเกรดสนาม หรือปัดเศษแบบเนทีฟ",
    "Matrices and set CS": "CS ของเมทริกซ์และเซ็ต",
    "Each matrix uses its own slot profile, level and star multiplier. Use fractional stats for the score; the displayed matrix stat has its own float32 truncation. Set AddScore is counted once per reached piece threshold on one weapon. The model ranks the set by the threshold’s Nth strongest matrix; mixed-star selection has not been separately verified in every case. Enhancement Shot changes base-stat endpoints, not these set ranks.": "แต่ละเมทริกซ์ใช้โปรไฟล์สล็อต ระดับ และตัวคูณดาวของตัวเอง ใช้สถิติเศษส่วนสำหรับคะแนน สถิติเมทริกซ์ที่แสดงมีการตัดทอน float32 ของตัวเอง ชุด AddScore จะถูกนับหนึ่งครั้งต่อจำนวนชิ้นที่ถึงขีดจำกัดของอาวุธหนึ่งชิ้น โมเดลจัดอันดับชุดตามเมทริกซ์ที่แข็งแกร่งที่สุดลำดับที่ N ของเกณฑ์ การคัดเลือกดาวผสมไม่ได้รับการตรวจสอบแยกกันในทุกกรณี ยาฉีดเสริมพลัง เปลี่ยนจุดสิ้นสุดสถิติพื้นฐาน ไม่ใช่อันดับที่ตั้งไว้เหล่านี้",
    "Titan property: effect and CS": "คุณสมบัติ ไททัน: เอฟเฟกต์และ CS",
    "The effect tooltip evaluates the game’s effect curve at the summed level. CS evaluates the separate display curve at each item’s own level and then sums its CS. A nonlinear curve means those two orders are not interchangeable. At level zero the effect is absent; between curve keys the model interpolates linearly and outside the keys it uses the endpoint. Gear CS already includes this property: do not add the Titan CS summary to gear CS again.": "คำแนะนำเครื่องมือเอฟเฟกต์จะประเมินเส้นโค้งเอฟเฟกต์ของเกมในระดับสรุป CS ประเมินเส้นโค้งการแสดงผลแยกกันในระดับของแต่ละรายการ จากนั้นจึงรวม CS เข้าด้วยกัน เส้นโค้งแบบไม่เชิงเส้นหมายความว่าทั้งสองคำสั่งไม่สามารถใช้แทนกันได้ ที่ระดับศูนย์ เอฟเฟกต์จะหายไป ระหว่างคีย์เส้นโค้ง โมเดลจะประมาณค่าเชิงเส้นและนอกคีย์ที่ใช้จุดสิ้นสุด อุปกรณ์ CS มีคุณสมบัตินี้อยู่แล้ว: อย่าเพิ่มข้อมูลสรุป ไททัน CS ให้กับ gear CS อีกครั้ง",
    "Supercomputing, Space Support and suppressor CS": "CS จากซูเปอร์คอมพิวติง การสนับสนุนจากอวกาศ และเครื่องยับยั้ง",
    "Raw attributes of the current level are weighted with the game attribute weights. Content modules give twice the DMG of a base DMG module and are scored with the same DMG% weight; the game weight of their final-DMG attribute is zero, so this is a model assumption. Supercomputing ATK% / RES%, healing and Shatter are not scored: weighting ATK% / RES% by the build’s bases would exceed the whole unexplained remainder of captured total CS. The game does not report a separate score for these systems, so each value is an estimate shown on hover over current CS; it is not added to the current CS.": "คุณลักษณะดิบของระดับปัจจุบันจะถ่วงน้ำหนักด้วยน้ำหนักคุณลักษณะของเกม โมดูลเนื้อหาให้ DMG สองเท่าของโมดูล DMG พื้นฐาน และให้คะแนนด้วยน้ำหนัก DMG% ที่เท่ากัน น้ำหนักเกมของแอตทริบิวต์ DMG สุดท้ายคือศูนย์ ดังนั้นนี่คือสมมติฐานของโมเดล ซูเปอร์คอมพิวเตอร์ ATK% / ต้านทาน%, การรักษาและ ทำลายโล่ จะไม่ถูกให้คะแนน: การถ่วงน้ำหนัก ATK% / ต้านทาน% ด้วยฐานของโครงสร้างจะเกินส่วนที่เหลือที่ไม่สามารถอธิบายได้ทั้งหมดของ CS ที่บันทึกไว้ทั้งหมด เกมไม่ได้รายงานคะแนนแยกต่างหากสำหรับระบบเหล่านี้ ดังนั้นแต่ละค่าจึงเป็นค่าประมาณที่แสดงเมื่อวางเมาส์เหนือ CS ปัจจุบัน มันไม่ได้ถูกเพิ่มเข้าไปใน CS ปัจจุบัน",
    "Enhancement Shot CS": "CS จากยาฉีดเสริมพลัง",
    "This is the weighted sum of the shot’s flat weapon/matrix gains. Universal ATK and RES count once, without combat ATK%/HP%/RES% and without matrix set AddScore or a new weapon StarSkillScore. The current profile model adds this subtotal once. It matches the documented before/after sample; it is not a universal proof of every indirect native CS change. Hovering current CS reveals this gain beside the shot, without a permanent caption.": "นี่คือผลรวมถ่วงน้ำหนักของการเพิ่มอาวุธ/เมทริกซ์ของกระสุน Universal ATK และ ต้านทาน นับหนึ่งครั้ง โดยไม่มีการต่อสู้ ATK%/HP%/ต้านทาน% และไม่มีชุดเมทริกซ์ AddScore หรืออาวุธใหม่ StarSkillScore รูปแบบโปรไฟล์ปัจจุบันจะเพิ่มผลรวมย่อยนี้หนึ่งครั้ง ซึ่งตรงกับเอกสารก่อน/หลังตัวอย่าง มันไม่ใช่ข้อพิสูจน์ที่เป็นสากลของการเปลี่ยนแปลง CS โดยอ้อมทุกรายการ การวางเมาส์เหนือ CS ปัจจุบันเผยให้เห็นข้อดีนี้นอกเหนือจากช็อต โดยไม่มีคำอธิบายภาพถาวร",
    "Roll count and quality": "จำนวนและคุณภาพของการสุ่มค่าสถานะ",
    "Roll inference uses values before Titan, not current augmented values. The number of rolls must fit every row and the item’s total stars. If several splits fit, the card selects a likelihood estimate and marks disputed counts with ~; missing or impossible data gives ?. The likelihood model approximates sums of uniform rolls and is not a confirmed game drop distribution. Quality excludes initial values and is undefined for zero rolls or fixed-size rolls.": "ระบบประมาณจำนวนค่าสุ่มจากค่าก่อนใช้ ไททัน ไม่ใช่ค่าที่เพิ่มพลังแล้ว จำนวนต้องสอดคล้องกับแต่ละแถวและจำนวนดาวรวมของไอเทม หากมีหลายชุดค่าที่เป็นไปได้ การ์ดจะแสดงค่าประมาณความเป็นไปได้และใส่ ~ กำกับจำนวนที่ยังไม่แน่ชัด หากข้อมูลขาดหรือเป็นไปไม่ได้จะแสดง ? โมเดลนี้ประมาณผลรวมของค่าสุ่มแบบช่วงสม่ำเสมอ และยังไม่มีการยืนยันว่าเป็นการกระจายดรอปจริงของเกม คุณภาพไม่รวมค่าเริ่มต้น และไม่มีการกำหนดเมื่อจำนวนค่าสุ่มเป็นศูนย์หรือค่าสุ่มมีขนาดคงที่",
    "Titan maximum and pull-up": "ค่าสูงสุดของ ไททัน และการเพิ่มค่าสถานะ",
    "The row’s Titan maximum applies generated growth to its actual pre-Titan value; it does not replace its earlier rolls with perfect rolls. Elemental ATK, ATK% and DMG% have separate pull-up families among the native elements. Pull-up can raise a row’s maximum but cannot reduce its independent growth, including when original values are equal. Their ranks use generated factors; an unconfirmed rank leaves the projection unavailable. Tied primary stats are evaluated separately, and an ambiguous ceiling remains unknown. Current GRV/PRV uses actual captured values and does not require this forecast.": "ค่าสูงสุดของ ไททัน ของแถวจะใช้การเติบโตที่สร้างขึ้นกับค่าก่อน ไททัน จริง มันไม่ได้แทนที่ม้วนก่อนหน้านี้ด้วยม้วนที่สมบูรณ์แบบ Elemental ATK, ATK% และ DMG% มีตระกูล pull-up แยกกันระหว่างองค์ประกอบดั้งเดิม การดึงขึ้นสามารถเพิ่มค่าสูงสุดของแถวได้แต่ไม่สามารถลดการเติบโตแบบอิสระได้ รวมถึงเมื่อค่าดั้งเดิมเท่ากัน อันดับของพวกเขาใช้ปัจจัยที่สร้างขึ้น อันดับที่ไม่ได้รับการยืนยันทำให้ไม่สามารถฉายภาพได้ สถิติหลักที่เชื่อมโยงกันจะได้รับการประเมินแยกกัน และยังไม่ทราบเพดานที่คลุมเครือ GRV/PRV ปัจจุบันใช้ค่าที่บันทึกไว้จริงและไม่จำเป็นต้องมีการคาดการณ์นี้",
    "Titan-added stat forecast": "คาดการณ์ค่าสถานะที่เพิ่มโดย ไททัน",
    "The primary is the stat with the most equivalent rolls before Titan. Each added stat uses that primary’s generated priority/fallback pool; existing random stats are excluded. Unused priority stats fill the available slots first, and fallback stats fill only the remainder. The added stat does not receive Titan growth again. The share is an observed calibration, not a proven game maximum or drop probability. Current ratings use the actual added value.": "หลักคือสถิติที่มีการทอยเท่ากันมากที่สุดก่อน ไททัน สถิติที่เพิ่มแต่ละรายการจะใช้ลำดับความสำคัญ/พูลแบ็คที่สร้างขึ้นหลักนั้น ไม่รวมสถิติสุ่มที่มีอยู่ สถิติลำดับความสำคัญที่ไม่ได้ใช้จะเติมช่องที่มีอยู่ก่อน และสถิติสำรองจะเติมเฉพาะส่วนที่เหลือ สถิติที่เพิ่มเข้ามาไม่ได้รับการเติบโตของ ไททัน อีกต่อไป ส่วนแบ่งนี้เป็นการปรับเทียบที่สังเกตได้ ไม่ใช่ความน่าจะเป็นสูงสุดหรือดรอปของเกมที่ได้รับการพิสูจน์แล้ว การให้คะแนนในปัจจุบันใช้มูลค่าเพิ่มตามจริง"
  },
  "zh-CN": {
    "What the capture contains": "捕获内容",
    "The file provides the first received profile stats, equipped items and captured progression. ATK has both a displayed base before ATK% and a native final value. HP and resistance are final values; their full percentage totals are not supplied. Missing fields remain unknown. These are snapshot values, rather than a live reading of the current game screen.": "该文件提供第一个收到的个人资料统计信息、装备的物品和捕获的进度。 攻击 既有 攻击力% 之前的显示基数，也有本机最终值。 生命和电阻为最终值；未提供其全部百分比总数。缺失的字段仍然未知。这些是快照值，而不是当前游戏屏幕的实时读数。",
    "The pair inherits whole gear percentages": "双武器组继承全部装备百分比",
    "1 is the selected element and 2 its weapon partner. g is total gear ATK%; q is total gear DMG%. Their winners are chosen independently across the equipped set. Other sources stay on their own element. The stronger element keeps its own percentage; the weaker replaces only its gear portion. A standalone item’s GRV can choose its own winners, while Build totals keep one source per percentage for every slot.": "1 表示选中的元素，2 表示配对武器的元素。g 是所有装备提供的 攻击力% 总值，q 是所有装备提供的 伤害% 总值。g 和 q 的最大值分别从当前装备中选取。其他来源的加成仍归属于各自元素。较强元素保留自身的百分比；较弱元素只替换装备提供的部分。单件装备的 GRV 可以单独选择最大值，而 配装 总计在所有槽位中每种百分比只采用一个来源。",
    "Pair ATK and Space Support": "双元素攻击力与太空支援",
    "B is a displayed base, including its own Space Support S. Compare the pair after removing each element’s support, then add only the selected element’s support before ATK%. A selected Enhancement Shot’s universal flat ATK is already in both effective bases and is counted once. Do not add support again after percentages. Flat ATK used by the combat table and the per-item GRV choice are separate calculations.": "B 为显示底座，包括其自身的 太空支援 S。删除每个单元的支撑后比较这对，然后仅在 攻击力% 之前添加所选单元的支撑。所选 强化注射剂 的通用扁平 攻击 已位于两个有效底座中，并且被计数一次。不要在百分比之后再次添加支持。战斗表使用的平面 攻击 和每个项目的 GRV 选择是单独计算的。",
    "Altered combat ATK": "异能战斗攻击力",
    "The combat model copies the strongest native element’s own final ATK, without duo inheritance, and keeps the captured or entered own Altered remainder. Native shot bonuses are inherited after that source’s percentages, once. The card’s imported displayed Altered base already contains the copy, so it is not added to that base again. Altered gear rating uses a different source selection: one gear-only source for GRV, the personal source for PRV.": "战斗模型复制最强的原生元素自己的最终攻击，没有双重继承，并保留捕获或输入的自己的异能剩余部分。原生射击奖励会在该来源的百分比之后继承一次。该卡导入的显示 异能 基础已包含副本，因此不会再次添加到该基础。 异能 齿轮额定值使用不同的源选择：GRV 为单一齿轮源，PRV 为个人源。",
    "Temporary buffs at capture time": "捕获时的临时增益",
    "Recognized removable constant ATK% buffs are subtracted per element on import, including their stack count. A recognized flat or unknown-magnitude temporary ATK effect can block import. Permitted food and shots remain separate selected consumables. Unrecognized effects are not proof of a clean snapshot; use an out-of-combat capture and the source list when checking a discrepancy.": "导入时会减去已识别的可移动常量 攻击力% 增益，包括其堆栈计数。已识别的平坦或未知幅度的临时 攻击 效应可能会阻止导入。允许的食物和镜头仍然是单独选定的消耗品。无法识别的效果并不能证明快照是干净的；检查差异时使用非战斗捕获和源列表。",
    "Account relic passives": "账号源器被动效果",
    "Captured account relic passives apply even when those relics are not equipped. Their DMG% and RES% are distinct per-element values. Damage-received reduction is not automatically a resistance-stat multiplier: the capture’s attribute mapping determines which pool a passive affects. Relic A4 DMG% is included once in its own element’s combat DMG% and also shown in the relic summary. Relic RES% joins the known resistance multiplier once; changing the two equipped relics does not reset account passives.": "即使未装备这些遗物，捕获的帐户遗物被动技能也适用。它们的 伤害% 和 抗性% 是不同的每个元素值。受到的伤害减少不会自动成为抵抗统计乘数：捕获的属性映射决定被动影响哪个池。遗物 A4 伤害% 曾包含在其自身元素的战斗 伤害% 中，并且也显示在遗物摘要中。 Relic 抗性% 加入已知电阻倍增器一次；更改两个装备的遗物不会重置帐户被动。",
    "Unknown data and rounding": "未知数据与取整",
    "Calculations retain fractional values; separate displayed rows can differ by a unit after rounding. A blank required base is unknown, rather than zero. Unknown catalog items remain empty and are listed; catalog fitting is not verification of their effects. The badge ≈ denotes a modeled estimate. Up displays the normalized upgrade level stored in the file: the exporter has already converted the raw profile suffix by adding one. The card does not add one again. This model has no separate Up multiplier for weapon stat endpoints or weapon CS.": "计算保留小数值；舍入后，单独显示的行可能会相差一个单位。空白所需的碱基是未知的，而不是零。未知的目录项保留为空并列出；目录拟合并不是对其效果的验证。徽章 ≈ 表示建模估计。 Up 显示文件中存储的标准化升级级别：导出器已通过添加 1 来转换原始配置文件后缀。该卡不再添加一张。该模型没有用于武器统计端点或武器 CS 的单独 Up 乘数。",
    "Universal ATK": "通用攻击力",
    "Universal ATK is inferred, not a separately captured stat. The remainder includes universal gear ATK and external sources. The card shows it only when all four native bases are available and their remainders agree within one ATK. Otherwise it shows —. Its tooltip separates universal gear, the selected shot and remaining sources; it does not apply ATK% to this base.": "通用 攻击 是推断出来的，而不是单独捕获的统计数据。其余部分包括通用齿轮 攻击 和外部源。仅当所有四个本机碱基均可用且其余数在一个 攻击 内一致时，该卡才会显示它。否则显示——。它的工具提示将通用齿轮、选定的镜头和剩余的源分开；它不适用于该底座 攻击力%。",
    "HP and HP%": "生命值与生命值%",
    "h is full HP% as a fraction. Without an explicitly entered total, only equipped gear HP% is known. The tooltip separates the pre-percentage pool into other sources, gear and the shot, then shows the percentage gain and final HP. Unknown external HP% or another multiplier makes the restored base an estimate. A missing HP snapshot stays missing.": "h 是完整的 生命% 的分数。如果没有明确输入总数，则仅已知配备的齿轮 生命%。工具提示将预百分比池分为其他来源、装备和镜头，然后显示百分比增益和最终 生命。未知的外部 生命% 或另一个乘法器使恢复的基数成为估计值。丢失的 生命 快照仍然丢失。",
    "Crit rating and chance": "暴击值与暴击率",
    "The rating tooltip separates other sources, equipped gear and the shot. The level denominator comes from the game curve for the selected enemy level. The panel shows the uncapped sum; expected-output and personal rating calculations cap useful chance at 100%. Crit DMG is a bonus: the expected critical factor is 1 + c_rating × Crit DMG, rather than chance multiplied by full critical damage.": "评级工具提示将其他来源、装备和镜头分开。等级分母来自所选敌人等级的游戏曲线。面板显示无上限金额；预期产出和个人评级计算将有用机会限制在 100%。 暴击伤害 是一个奖励：预期的暴击系数是 1 + c_ rating × 暴击伤害，而不是几率乘以全部暴击伤害。",
    "Resistance and damage reduction": "抗性与伤害减免",
    "r is full RES%, or the known source sum when a full value is unavailable. Universal flat RES contributes to every element; elemental RES contributes only to its own. The shot is added before RES%. K uses character level, while the Crit curve uses enemy level. This reduction is the resistance component, not the product of every damage-reduction effect in combat. Tank EHP = HP × (1 + RES_effective / K).": "r 是完整的 抗性%，或者当完整值不可用时的已知源总和。通用扁平抗性为每一个元素做出贡献；元素 抗性 仅贡献其自身。该镜头添加在 抗性% 之前。 K 使用角色等级，而 暴击 曲线使用敌人等级。这种减少是抗性成分，而不是战斗中每种伤害减少效果的产物。罐体EHP=生命×(1+抗性_有效/K)。",
    "The combat DMG% column": "战斗伤害%栏",
    "For captures, this column is derived from the loadout; no full DMG% total is captured. Only generated recognized contributions enter it. Relic A4 is included once for its own element; duo inheritance replaces only gear DMG%, leaving relic and other non-gear bonuses on their own element. Alternative conditional Space Support modes do not stack: the strongest applicable mode per element is used. Imported Altered DMG% is zero in this model. This column is not a complete damage or rotation simulator.": "对于捕获，此列源自装载；未捕获完整的 伤害% 总数。只有产生的认可贡献才可以进入。 Relic A4 因其自身元素而包含一次；二重奏继承仅替换了装备 伤害%，将遗物和其他非装备奖励保留在其自己的元素上。替代条件 太空支援 模式不堆叠：使用每个元素最强的适用模式。进口异能 伤害%在该型号中为零。本专栏不是完整的损坏或旋转模拟器。",
    "Enhancement Shot stat gain": "强化注射剂带来的属性提升",
    "For weapons, the target is the catalog’s maximum weapon level at the weapon’s actual stars. For matrices, it is the maximum level and maximum base-stat advancement. The selected shot adds these four flat gains to the first received stats. HP and RES gains are multiplied by their percentages; native ATK gains are multiplied by native ATK%; Altered inherits once. It does not change captured stars, Up or matrix set-effect ranks. Recalculation replaces the previous applied gain and does not add it again.": "对于武器，目标是武器实际星星处的目录最大武器等级。对于矩阵来说，它是最大级别和最大基础统计进步。所选镜头将这四个平坦增益添加到第一个收到的统计数据中。 生命 和 抗性 增益乘以它们的百分比；原生攻击增益乘以原生攻击力%； 异能继承一次。它不会改变捕获的星星、Up 或矩阵设定效果等级。重新计算会替换之前应用的增益，并且不会再次添加。",
    "Selected ATK% consumables": "已选攻击力%消耗品",
    "The model applies only generated, recognized unconditional ATK% bonuses of selected consumables. A universal bonus targets the native elements declared by the catalog; it is not applied to Altered a second time. Unknown, conditional and other consumable effects are not inferred from their names. The expiry time describes the captured buff; the card is a saved configuration and does not automatically clear the selected consumable when that clock expires.": "该模型仅适用于所选消耗品生成的、认可的无条件 攻击力% 奖励。通用奖励针对的是目录中声明的原生元素；它不会再次应用于 异能。未知的、有条件的和其他消耗性效果不能从它们的名称中推断出来。过期时间描述了捕获的buff；该卡是已保存的配置，并且在该时钟到期时不会自动清除所选耗材。",
    "Current CS and Apex CS": "当前战力与最高战力",
    "Current CS starts from the captured profile score or the manual input. The selected Enhancement Shot adds its modeled flat-stat CS delta once; when a precise captured CS is available, rounding starts from that value. Apex CS remains the recorded historical maximum with its recorded time. The model does not replace current CS with the sum of gear, weapons, matrices and other system estimates, and it does not infer a new complete CS after every manual loadout edit or recompute every other consumable’s CS impact. The displayed integer header difference can differ from the rounded shot subtotal by one because the original captured CS has a fraction.": "当前CS从捕获的轮廓分数或手动输入开始。所选的 强化注射剂 添加其建模的平面 CS 增量一次；当精确捕获的 CS 可用时，从该值开始舍入。 最高战力 以其记录的时间保持了记录的历史最大值。该模型不会用装备、武器、矩阵和其他系统估计的总和来取代当前的 CS，并且在每次手动装载编辑或重新计算所有其他消耗品的 CS 影响后，它不会推断出新的完整 CS。显示的整数标头差异可能与四舍五入的镜头小计相差一，因为原始捕获的 CS 有分数。",
    "Weapon CS": "武器战力",
    "The card’s weapon source label scores the weapon alone. Level gains and star coefficients come from generated game tables. Only the current star’s StarSkillScore is added, not the sum of all earlier stars. Matrix scores and their set AddScore are separate. The reconstruction matches documented server-score samples within floating-point differences; that does not establish every weapon, upgrade field or native rounding case.": "该卡的武器来源标签仅对武器进行评分。等级增益和星级系数来自生成的游戏表。仅添加当前恒星的 StarSkillScore，而不是所有早期恒星的总和。矩阵分数及其集合 AddScore 是分开的。重建在浮点差异内匹配记录的服务器分数样本；这并没有建立所有武器、升级字段或本地舍入情况。",
    "Matrices and set CS": "意志与套装战力",
    "Each matrix uses its own slot profile, level and star multiplier. Use fractional stats for the score; the displayed matrix stat has its own float32 truncation. Set AddScore is counted once per reached piece threshold on one weapon. The model ranks the set by the threshold’s Nth strongest matrix; mixed-star selection has not been separately verified in every case. Enhancement Shot changes base-stat endpoints, not these set ranks.": "每个矩阵都使用自己的插槽配置文件、级别和星乘数。使用分数统计数据；显示的矩阵统计数据有其自己的 float32 截断。设置 AddScore 会在一件武器上每达到一件阈值时计数一次。模型通过阈值的第 N 个最强矩阵对集合进行排序；混合明星的选择并未在每种情况下都经过单独验证。 强化注射剂 更改基本统计端点，而不是这些设置的等级。",
    "Titan property: effect and CS": "泰坦属性：效果与战力",
    "The effect tooltip evaluates the game’s effect curve at the summed level. CS evaluates the separate display curve at each item’s own level and then sums its CS. A nonlinear curve means those two orders are not interchangeable. At level zero the effect is absent; between curve keys the model interpolates linearly and outside the keys it uses the endpoint. Gear CS already includes this property: do not add the Titan CS summary to gear CS again.": "效果工具提示在总水平上评估游戏的效果曲线。 CS 评估每个项目自身级别的单独显示曲线，然后对其 CS 求和。非线性曲线意味着这两个阶数不可互换。在零级时，效果不存在；在曲线关键点之间，模型进行线性插值，并在关键点之外使用端点。 装备 CS 已包含此属性：请勿再次将 泰坦 CS 摘要添加到 gear CS。",
    "Supercomputing, Space Support and suppressor CS": "超算、太空支援与抑制器战力",
    "Raw attributes of the current level are weighted with the game attribute weights. Content modules give twice the DMG of a base DMG module and are scored with the same DMG% weight; the game weight of their final-DMG attribute is zero, so this is a model assumption. Supercomputing ATK% / RES%, healing and Shatter are not scored: weighting ATK% / RES% by the build’s bases would exceed the whole unexplained remainder of captured total CS. The game does not report a separate score for these systems, so each value is an estimate shown on hover over current CS; it is not added to the current CS.": "当前级别的原始属性使用游戏属性权重进行加权。内容模块的 伤害 是基本 伤害 模块的两倍，并且以相同的 伤害% 权重进行评分；他们最终的 伤害 属性的游戏权重为零，因此这是一个模型假设。超级计算 攻击力% / 抗性%、治疗和 破甲 不计分：按构建基础对 攻击力% / 抗性% 进行加权将超过捕获的总 CS 的全部无法解释的剩余部分。游戏不会报告这些系统的单独分数，因此每个值都是悬停在当前 CS 上时显示的估计值；目前的 CS 中未添加此功能。",
    "Enhancement Shot CS": "强化注射剂战力",
    "This is the weighted sum of the shot’s flat weapon/matrix gains. Universal ATK and RES count once, without combat ATK%/HP%/RES% and without matrix set AddScore or a new weapon StarSkillScore. The current profile model adds this subtotal once. It matches the documented before/after sample; it is not a universal proof of every indirect native CS change. Hovering current CS reveals this gain beside the shot, without a permanent caption.": "这是射击的平坦武器/矩阵增益的加权和。通用攻击和抗性算一次，没有战斗攻击力%/生命%/抗性%并且没有矩阵组AddScore或新武器StarSkillScore。当前的配置文件模型会添加一次此小计。它与记录的前后样本相匹配；它不是每个间接原生 CS 更改的通用证明。将鼠标悬停在当前的 CS 上会在镜头旁边显示此增益，但没有永久标题。",
    "Roll count and quality": "词条数量与质量",
    "Roll inference uses values before Titan, not current augmented values. The number of rolls must fit every row and the item’s total stars. If several splits fit, the card selects a likelihood estimate and marks disputed counts with ~; missing or impossible data gives ?. The likelihood model approximates sums of uniform rolls and is not a confirmed game drop distribution. Quality excludes initial values and is undefined for zero rolls or fixed-size rolls.": "词条次数根据泰坦强化前的数值推算，而不是当前强化后的数值。推算结果必须同时符合每条属性的范围和装备的总星级。若存在多种可能的分配，卡片会显示概率估算，并用 ~ 标记有争议的次数；数据缺失或无法成立时显示 ?。该概率模型近似均匀随机词条的总和，并非已确认的游戏掉落分布。词条质量不计入初始数值；词条次数为零或词条数值固定时不定义质量。",
    "Titan maximum and pull-up": "泰坦最大值与词条提升",
    "The row’s Titan maximum applies generated growth to its actual pre-Titan value; it does not replace its earlier rolls with perfect rolls. Elemental ATK, ATK% and DMG% have separate pull-up families among the native elements. Pull-up can raise a row’s maximum but cannot reduce its independent growth, including when original values are equal. Their ranks use generated factors; an unconfirmed rank leaves the projection unavailable. Tied primary stats are evaluated separately, and an ambiguous ceiling remains unknown. Current GRV/PRV uses actual captured values and does not require this forecast.": "该行的 泰坦 最大值将生成的增长应用于其 泰坦 之前的实际值；它不会用完美的卷取代早期的卷。 Elemental 攻击、攻击力% 和 伤害% 的原生元件具有独立的上拉系列。上拉可以提高行的最大值，但不能减少其独立增长，包括当原始值相等时。他们的排名使用生成因素；未经确认的排名会使预测不可用。并列的主要统计数据是单独评估的，并且模糊的上限仍然未知。当前 GRV/PRV 使用实际捕获的值，不需要此预测。",
    "Titan-added stat forecast": "泰坦追加属性预测",
    "The primary is the stat with the most equivalent rolls before Titan. Each added stat uses that primary’s generated priority/fallback pool; existing random stats are excluded. Unused priority stats fill the available slots first, and fallback stats fill only the remainder. The added stat does not receive Titan growth again. The share is an observed calibration, not a proven game maximum or drop probability. Current ratings use the actual added value.": "主要是在 泰坦 之前具有最等效掷骰的统计数据。每个添加的统计数据都使用该主节点生成的优先级/后备池；现有的随机统计数据被排除在外。未使用的优先级统计信息首先填充可用槽位，后备统计信息仅填充剩余部分。添加的统计数据不会再次获得 泰坦 增长。该份额是观察到的校准，而不是经过验证的游戏最大值或掉落概率。当前额定值使用实际附加值。"
  }
};
